INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4a58c111-46b7-565b-a5bd-13d985c8ee6d', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 43, 43, 'እኔም በግንባሬ ወደቅሁ፥ ሥጋዬም ሁሉ ቀለጠ፥ አእምሮዬም ተለወጠ።'),
  ('78577f5b-46ce-5104-a5d1-6689cbe694b1', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 44, 44, 'በታላቅ ቃልና በኀይል መንፈስም ጮህሁ፥ አመሰገንሁ፥ አከበርሁ፥ ከፍ ከፍም አደረግሁ።'),
  ('b0990701-fdff-54df-a6a4-d14225d670ac', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 45, 45, 'ከአፌ የወጡ እኒህ ምስጋናዎችም በዚያ ብሉየ መዋዕል ፊት የተወደዱ ሆኑ።'),
  ('a0841e9e-ea58-5e80-ae54-19dfcd713f8d', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 46, 46, 'ያም ብሉየ መዋዕል ከሚካኤልና ከገብርኤል፥ ከሩፋኤልና ከፋኑኤል፥ ቍጥር ከሌላቸው ብዙ፥ የብዙ ብዙ ከሚሆኑ መላእክትም ጋር መጣ።'),
  ('3a35eae5-2152-5f28-ad35-4f93bb8df393', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 47, 47, 'ያም መልአክ ወደ እኔ መጣ፥ በቃሉም ሰላም አለኝ።'),
  ('b0634d95-ec39-51c2-a114-7f13abb97648', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 48, 48, 'እንዲህም አለኝ- “ለእውነት የተወለድህ የሰው ልጅ አንተ ነህ፤ ጽድቅም በአንተ አደረ፤ የብሉየ መዋዕል ቸርነትም አይለይህም።”'),
  ('68c2189d-754a-5da5-a431-e75ff2690e34', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 49, 49, 'እንዲህም አለኝ- “ከጥንት ጀምሮ ሰላም በዚያ ተገኝትWaልና፥ ለዘለዓለም የሚሆን ሰላምን በስሙ ይጠራልሃል።'),
  ('23707dd3-923d-5e15-a558-b0748be1eb08', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 50, 50, 'እንደዚሁም ለዓለም፥ ለዘለዓለም ይሆንልሃል፥ ሁሉም ይደረግልሃል፤ ጽድቅም ለዘለዓለም ሳይለይህ ሁሉ በመንገድህ ይሄዳል።'),
  ('a0276e71-df95-5363-a0bf-ecea6b276dd5', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 51, 51, 'ማደሪያቸውም ከአንተ ጋር ይሆናል፥ ዕድል ፋንታቸውም ከአንተ ጋር ነው፤ ከአንተም ለዓለም ለዘለዓለም አይለዩም።'),
  ('4437ecea-204d-5b00-a540-cbcb105381ea', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 52, 52, 'እንደዚህም ከዚያ የሰው ልጅ ጋር ብዙ ዘመን ይሆናል።'),
  ('7d794c1c-37fa-5be2-a12e-a317210563ec', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 53, 53, 'ለጻድቃንም ሰላም ይሆናል፤ መንገዱም በመናፍስት ጌታ ስም ለጻድቃን ለዘለዓለም የቀና ነው።”'),
  ('1a0b0f9f-e846-50c3-a5ad-27206b64e283', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 1, 1, 'የሰማይ ብርሃናትን መመላለስ የሚናገር መጽሐፍ።'),
  ('a0018a29-ad42-5d59-a3ef-05c92fab5294', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 2, 2, 'እየአንዳንዳቸው በየወገናቸው እንደ አሉ፥ እየአንዳንዳቸውም በየሥልጣናቸውና በየዘመናቸው፥ እየአንዳንዳቸውም በየስማቸውና በየመውጫቸው፥ በየወራታቸውም ከእኔ ጋር ያለው መሪያቸው መልአክ ቅዱስ ዑርኤል እንደ አሳየኝ።'),
  ('b2deca6f-9d18-5bf7-af3c-374de89562ad', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 3, 3, 'ሰሌዳቸውንም ሁሉ፥ ዓመተ ዓለምን እስከ ዘለዓለም ድረስ፥ እስከ ዘለዓለም የሚኖር ሐዲስ ሥራም እስኪሠራ ድረስ እርሱ እንዳሳየኝ።'),
  ('9d7e035f-709b-5bb4-a1ae-e47977dfa55b', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 4, 4, 'የብርሃናት መጀመሪያ ትእዛዝ ይህ ነው።'),
  ('3d502176-a5a9-531e-aa2f-508b68c7074b', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 5, 5, 'ፀሐይ ብርሃን ነው፤ መውጫውም በምሥራቅ በኩል በሰማይ መስኮቶች ነው፤ መግቢያውም በምዕራብ በኩል በሰማይ መስኮቶች ነው።'),
  ('f8939edf-0353-5093-a97d-1b28e8971d52', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 6, 6, 'ፀሐይ የሚወጣባቸው ስድስት መስኮቶችን አየሁ፤ ፀሐይ የሚገባባቸውን ስድስት መስኮቶችንም አየሁ።'),
  ('c83d5255-0748-54cf-a395-5b49e08b5d6d', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 7, 7, 'ጨረቃም በእነዚያ መስኮቶች ይወጣል፤ ይገባልም።'),
  ('a57fb112-56ad-5730-a6e2-2165dcd6a367', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 8, 8, 'የሰማይ ከዋክብትን የሚመሩም ከሚመሯቸው ጋር፥ ስድስቱ በምሥራቅ፥ ስድስቱም በፀሐይ መግቢያ ናቸው።'),
  ('919dd59f-d28d-57bd-a929-53e447c26c1e', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 9, 9, 'ሁሉም እየአንዳንዱ ከሌላው በኋላ የቀና ነው፤ በዚያም መስኮት በቀኙና በግራው ብዙ መስኮቶች አሉ።'),
  ('9c4671b9-36e0-5c3f-ae26-34d789ec85bf', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 10, 10, 'መጀመሪያ ስሙ ፀሐይ የሚባል ታላቁ ብርሃን ይወጣል፤ ዙሪያውም እንደ ሰማይ ዙሪያ ነው፤ ሁለመናውም የሚያበራና የሚያቃጥል እሳትን የተመላ ነው።'),
  ('326cde63-1e71-58e1-aaa4-ea6d3430af2a', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 11, 11, 'የሚሄድባቸውንም ሠረገላዎች ነፋስ ይነዳቸዋል።'),
  ('d79c6028-2d52-5b13-ab1a-b1c5142c3ed5', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 12, 12, 'ፀሐይም ከሰማይ ይጠልቃል፤ ወደ ምሥራቅም ይሄድ ዘንድ ወደ መስዕ ይመለሳል፥ ወደዚያ መስኮት ይገባ ዘንድ ይመራል፤ በሰማይም ሆኖ ያበራል።'),
  ('3e8898cf-ddb9-57b6-abf7-410697ebcacd', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 13, 13, 'እንደዚህ በመጀመሪያው ወር በታላቁ መስኮት ይወጣል፤ ፀሐይ በምሥራቅ ከሚወጣባቸው ከስድስቱ መስኮቶች በአራተኛዪቱ ይወጣል።'),
  ('eb56bf31-8196-5a55-a88d-8b0fafdebb53', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 14, 14, 'በመጀመሪያው ወር ፀሐይ ከእርሷ በሚወጣባት በዚያች በአራተኛዪቱ ደጃፍም በዘመናቸው በሚከፈቱበት ጊዜ ከእነርሱ ዋዕይ የሚወጣባቸው ዐሥራ ሁለት ደጃፎች አሉባት።'),
  ('fdf73942-9f25-5c96-a2af-d29d1e2aac92', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 15, 15, 'ፀሐይ ከምሥራቅ በወጣ ጊዜ በዚች በአራተኛዪቱ ደጃፍ ሠላሳ ቀን ይወጣል።'),
  ('c1a6514c-3984-53c5-ab55-7e9b316e67b5', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 16, 16, 'በሰማይ በአለው መግቢያም በአራተኛዪቱ ደጃፍ አቅንቶ ይወርዳል።'),
  ('5ef3d8d4-7199-5ae8-a4bb-f33a3ace70ab', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 17, 17, 'በእነዚያም ወራት እስከ ሠላሳ ቀን ድረስ ቀኒቱ ከቀን ትረዝማለች፤ ሌሊቲቱም ከሌሊት ታጥራለች።'),
  ('a00fbfcb-49e3-5a4c-a021-e2cdd55ec36b', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 18, 18, 'በዚችም ቀን ቀኒቱ ከሌሊቱ ሁለት እጅ ትረዝማለች።'),
  ('5d70bb4c-c99a-5b06-afae-d12e1bb76259', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 19, 19, 'ጠንቅቀውም ቢቈጥሯት ቀኒቱ ዐሥር ክፍል ትሆናለች፤ ሌሊቲቱም ስምንት ክፍል ትሆናለች።'),
  ('bccb7393-c5fd-5e4a-ad9f-312a060d1cb8', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 20, 20, 'ፀሐይም ከዚች ከአራተኛዪቱ ደጃፍ ይወጣል፤ በአራተኛዪቱም ደጃፍ ይገባል።'),
  ('8259d2d6-8619-5f1e-a0ce-6d47e9e3fd33', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 21, 21, 'ሠላሳ ቀንም በምሥራቅ ወዳለችው ወደ አምስተኛዪቱ ደጃፍ ይመለሳል፤ ከእርሷም ይወጣል፤ በአምስተኛዪቱም ደጃፍ ይገባል።'),
  ('df9256b8-6772-57ef-a24b-702e9350cd21', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 22, 22, 'ያንጊዜም ቀኒቱ ሁለት እጅ ትረዝማለች፤ ቀኒቱም ዐሥራ አንድ ክፍልን ትሆናለች፤ ሌሊቲቱም ታጥራለች፤ ሰባት ክፍልንም ትሆናለች።'),
