  ('529be69f-bcf1-568b-aea5-7a2d51b2e0c1', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 50, 50, 'የቀንና የሌሊት ርዝመት፥ የቀንና የሌሊትም ማጠር በፀሐይ መንገድ ይለያል።'),
  ('1c7b9aed-9d7d-5748-a8da-0d15df743a88', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 51, 51, 'ስለዚህም መንገዱ ይረዝማል፤ ቀን ከቀን፥ ሌሊትም ከሌሊት ያጥራል።'),
  ('e20c558e-3d5a-5e29-aaad-de05e3141c96', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 52, 52, 'የፀሐይ ሥርዐቱ፥ መንገዱም፥ መመላለሻውም ይህ ነው።'),
  ('b1967783-f2f4-5e9a-a5a0-344d462c09bd', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 53, 53, 'በተመለሰም ጊዜ ስድሳውን ከንትሮስ ሊፈጽም ይመለሳል፤ ተመልሶም ይወጣል፤ ለዘለዓለም የሚኖር ታላቅ ብርሃንም ይህ ነው።'),
  ('9b1a9365-bfd3-5204-aa79-45dc120e6523', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 54, 54, 'ጌታ እንዳዘዘም በእርሱ አምሳል የሚጠራ፥ ከምሥራቅ የሚወጣ ታላቅ ብርሃን ይህ ነው።'),
  ('14a34088-3ade-5ba3-a584-bf6c6c3bd184', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 55, 55, 'እንደዚህም ይወጣል፤ ይገባልም፤ አይጐድልም፤ አያርፍምም፤ ነገር ግን በመዓልትና በሌሊት በሠረገላ ይሮጣል።'),
  ('e2fc51a5-230d-5607-a0db-2e4660aac4f2', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 56, 56, 'ብርሃኑም ከጨረቃ ይልቅ ሰባት እጅ ያበራል።'),
  ('7f4961d2-6f1f-57fb-ac60-5e57af5182e3', '46622db3-b2e2-5502-adc0-d16861e6e0b2', 'efbe8321-293d-5514-a1d0-79add0bd3157', 57, 57, 'የሁለቱም መጠናቸው እኩል ነው።'),
  ('e4368581-6500-55d8-a97e-6d6966c66243', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 1, 1, 'ከዚህ ሥርዐትም በኋላ ስሙ ጨረቃ የሚባል የታናሹን ብርሃን ሌላ ሥርዐት አየሁ።'),
  ('9672f54a-e22a-591e-aecf-0d374e4515c6', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 2, 2, 'ክበቡም እንደ ሰማይ ክበብ ነው፤ የሚሔድበትንም ሠረገላ ነፋስ ይነዳዋል።'),
  ('5db50f16-acda-59a4-a58b-a9a4ad2adb77', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 3, 3, 'ብርሃንም በመጠን ይሰጠዋል።'),
  ('b429505f-3ab3-5529-a3a1-ad3fa41e5a3d', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 4, 4, 'በወሩም ሁሉ መውጫውና መግቢያው ይለወጣል፤ ቀኑም እንደ ፀሐይ ቀን ነው።'),
  ('84fdd4b9-a89c-50ec-ae90-214787b3ffd3', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 5, 5, 'የብርሃኑ ሁኔታ በተስተካከለም ጊዜ የብርሃኑ መጠን ከፀሐይ ብርሃን ሰባተኛ እጅ ይሆናል።'),
  ('3556382b-44c6-5a26-afeb-62ecd3fc70b2', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 6, 6, 'እንደዚህም ይወጣል፤ ማጭድነቱም በሠላሳኛው ቀን ወደ ምሥራቅ ሆኖ ይወጣል።'),
  ('6addb471-65aa-5d4d-a21b-408c5a641948', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 7, 7, 'በዚያችም ቀን ይታያል፤ ለእናንተም ሠርቀ ወርኅ ይሆናል።'),
  ('c3262aee-19cd-5e29-a34c-efd5f489e151', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 8, 8, 'በሠላሳኛው ቀን ሠርቅ ሊያደርግ በሃያ ዘጠነኛው ቀን ፀሐይ በሚወጣበት ደጃፍ ከፀሐይ ጋር ያድራል።'),
  ('81ea5c70-896b-5ece-ab99-444913944ebd', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 9, 9, 'ሰባተኛ ክፍለ ብርሃን የሚሣልበት እኩሌታው አንዱ ወገን ከብርሃን የራቀ ነው፤ ከዐሥራ አራት እጅ ብርሃን ተለይታ ሰባት ክፍለ ብርሃን ከሚሣልባት ከሰባተኛዪቱ እጅ በቀር ሰሌዳው ሁሉ ብርሃን የሌለበት ባዶ ነው።'),
  ('e74b9dcc-ed8a-505d-a398-1b332c252bcd', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 10, 10, 'ከብርሃኑ እኩሌታ አንድ ሰባተኛ በሚቀበልበት ቀን ብርሃኑ የእኩሌታው አንድ ሰባተኛ ይሆናል።'),
  ('764ab099-93c4-55d2-abb9-e85b1d95be81', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 11, 11, 'ከፀሐይም ጋር ይገባል፤ ፀሐይም በሚወጣ ጊዜ ጨረቃ ከእርሱ ጋር ይወጣል፤ የብርሃኑንም እጅ ዕኩሌታ ይቀበላል።'),
  ('66251bf6-6f6b-5e07-aa80-a082e1a8bdbb', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 12, 12, 'ጨረቃ ሠርቅ ከሚያደርግበት ቀን አስቀድሞ በዚያች ሌሊት ጨረቃ ከፀሐይ ጋር ያድራል።'),
  ('2113b3c9-d015-53f9-a1aa-a9531bc546b8', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 13, 13, 'በዚያችም ሌሊት ሰባተኛውና ስድስተኛው እጅ፥ እኩሌታዋም እጅ ጨለማ ይሆናል፤ በዚያችም ቀን ሰባተኛውን እጅ ፈጽሞ ተቀብሎ ይወጣል።'),
  ('00099de1-2cfa-5dbf-a755-3513c1b39e6a', 'def6a0d8-b275-5247-ae7a-eaf5a24b5f54', '9c516188-a65b-5842-a202-47bc436bf1ea', 14, 14, 'ወጥቶም ከፀሐይ መውጫ ይርቃል፥ በቀረውም ቀኑ ሰባት ሰባት እጅ እየተቀበለ ያበራል።'),
  ('6f3cc80a-e203-5f9f-a3d9-648f714c4119', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 1, 1, 'የወሮቹን መንገድ በሚያደርግበት በዚያ ትእዛዝ ሁለተኛ መሄጃውንና ትእዛዙን አየሁለት።'),
  ('13f03f30-9843-593d-aa50-afc1f07b40fb', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 2, 2, 'የሁሉም መሪያቸው የሆነው ቅዱስ መልአክ ዑርኤል ሁሉን አሳየኝ፤'),
  ('981adbf1-b3e2-5de1-a9b1-b2ba902f1fff', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 3, 3, 'እንዳሳየኝም ቦታቸውን ጻፍሁ።'),
  ('2cd955bb-7da1-5195-afd7-34e2c37fd3d2', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 4, 4, 'ጸንተው እንደሚኖሩም ወራታቸውን ጻፍሁ፤ የብርሃናቸውንም መልክ ጻፍሁ።'),
  ('bb86e0d2-db14-5283-af02-b5c1c8fb23d5', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 5, 5, 'ዐሥራ አምስቱ ቀን እስኪፈጸም ድረስ በአንድ ቀን አንድ ሰባተኛ ክፍለ ብርሃን እየተቀበለ ብርሃኑን ሁሉ በምሥራቅ ፈጽሞ ያገኛል፤ አንድ ሰባተኛ ክፍለ ብርሃንም እየተነሣው ጨለማውን ሁሉ በምዕራብ ፈጽሞ ያገኛል።'),
  ('a9af2dcf-8947-5f4e-a26c-55162afe929c', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 6, 6, 'በታወቁም ወራቶች መግቢያዎቹን ይለውጣል፤ በታወቁም ወራቶች አንድ አንድ ክፍለ ብርሃን እየተሰጠው መንገዱን ይሄዳል።'),
  ('f762906e-1706-5b2d-a1dc-0539ef46d9f6', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 7, 7, 'ጨረቃም በሕፀፁ በሁለቱ ከፀሐይ ጋር ይገባል፤ በመካከል ባሉ በእነዚያ በሁለቱ መስኮቶች በአራተኛዪቱና በሦስተኛዪቱ መስኮት ሰባት ቀን ይወጣል።'),
  ('6f187792-d28f-5e54-a154-1fca6ef8eee4', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 8, 8, 'ዳግመኛም ዙሮ ተመልሶ ፀሐይ በሚወጣበት መስኮት ይወጣል፤ በዚያም መስኮት ብርሃኑን ሁሉ ፈጽሞ ያገኛል።'),
  ('859a796f-6d3d-53ee-a9cf-c064856a3be7', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 9, 9, 'ከፀሐይም ይርቃል፤ ፀሐይ ከእርሷ በሚወጣባት በስድስተኛዪቱም መስኮት ስምንት ቀን ይገባል።'),
  ('2f95f03c-58a7-569c-a402-29550ccf3f6e', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 10, 10, 'ፀሐይም ከአራተኛዪቱ መስኮት በሚወጣ ጊዜ ከአምስተኛዪቱ መስኮት እስኪወጣ ድረስ በአራተኛዪቱ መስኮት ሰባት ቀን ይወጣል።'),
  ('64711766-1860-5623-a04e-b96968371d06', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 11, 11, 'ዳግመኛም ተመልሶ በአራተኛዪቱ መስኮት ሰባት ቀን ይወጣል፤ ብርሃኑንም ሁሉ ፈጽሞ ያገኛል።'),
  ('1baa36c3-edd8-5b41-a5c3-469f9c38b780', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 12, 12, 'ይርቃል፥ በመጀመሪያዪቱም መስኮት ስምንት ቀን ይገባል፤ ዳግመኛም ተመልሶ ፀሐይ ከእርሷ በሚወጣባት በአራተኛዪቱ መስኮት ሰባት ቀን ይወጣል።'),
  ('0d868f81-dc4a-56fe-a6b1-35e5ad5c0f3e', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 13, 13, 'በየወራታቸው ሥርዐት ፀሐይ እንደሚወጣና እንደሚገባ አኗኗራቸውን እንዲህ አየሁ።'),
  ('f0faf2c0-b4c3-56b7-ac9f-7386976bc9da', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 14, 14, 'በእነዚያም ወራቶች አምስት ዓመት ይጨመራል፤ ለፀሐይም ሠላሳ ቀን ይደርሰዋል።'),
  ('dfdc51a4-3e83-5060-aff7-f41a3535e794', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 15, 15, 'ለአንዱ ዓመትም ቀኖች ሁሉ ይደርሱታል፤ ከእነዚህም ከአምስቱ ዓመታት ተውጣጥተው ቀኖቹ ሦስት መቶ ስሳ አራት ቀን ይሆናሉ።'),
  ('810c0369-9216-5e9b-ab21-9626e5d65eb0', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 16, 16, 'ለፀሐይና ለከዋክብትም ስድስት ቀን ይደርሳቸዋል፤ ከአምስቱ ዓመትም ስድስት ስድስት ቀን ወጥቶ ሠላሳ ቀን ይደርሳቸዋል።'),
  ('4f74e9af-c1f5-55dc-a2a0-67f7ae532288', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 17, 17, 'ጨረቃም ከፀሐይና ከከዋክብት ሠላሳ ቀን ይጐድላል።'),
  ('525a95a9-0c78-539d-a13b-3ba4903376c6', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 18, 18, 'ጨረቃም ዓመታትን ጠንቅቆ ያስቈጥራቸዋል።'),
  ('0ae4f2ef-56a6-58ce-a3c4-bdb7da38803c', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 19, 19, 'ሁሉም ለዘለዓለም እንደሚኖሩ አንዲት ቀን አያተርፉም፤ አያጐድሉምም። ነገር ግን ሦስት መቶ ስድሳ አራት ቀን እየሆነ በጥንቃቄ በእውነት ዓመቱን ይለውጣሉ።'),
  ('a972485e-f5c5-50b1-acb5-976f55e8cca4', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 20, 20, 'የሦስቱ ዓመት ቀን ሺህ ዘጠና ሁለት ነው፤ የስምንቱ ዓመት ቀን ሁለት ሺህ ዘጠኝ መቶ ዐሥራ ሁለት ቀን ይሆን ዘንድ የአምስቱ ዓመት ቀን ሺህ ስምንት መቶ ሃያ ቀን ነው።'),
  ('5a9d5064-b8c9-502f-ad95-7c0e188a0a83', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 21, 21, 'ለጨረቃም ለብቻው ይደርሰዋል፤ የሦስቱም ዓመት ቀኑ ሺህ ስድሳ ሁለት ቀን ነው።'),
  ('1f8ad282-c87a-51f8-a0fe-6751d5bb05d8', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 22, 22, 'በስድሳ ሁለቱ ቀን ላይ ወደ ላይ በመውጣቱ ለፀሐይ ቀን ይጨመርለታልና ጨረቃ ለአምስቱ ዓመት አምሳ ቀን ይጐድላል።'),
  ('1a24e251-02bf-502f-aa6a-36635b04f051', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 23, 23, 'ለጨረቃ የስምንቱ ዓመት ቀኑ ሁለት ሺህ ስምንት መቶ ሠላሳ ሁለት ቀን ይሆን ዘንድ የአምስቱ ዓመት ቀኑ ሺህ ሰባት መቶ ሰባ ቀን ይሆናል።'),
  ('2df8d104-37f7-5a22-aeca-81b6c96988eb', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 24, 24, 'በስምንቱ ዓመት የሚያንሰው ቀኑ ሰማንያ ቀን ነውና ከስምንቱም ዓመት የጐደለባቸው ቀኖች ሰማንያ ቀኖች ናቸው።'),
  ('ab9e1d3a-b287-5119-aba3-4b6db1c18514', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 25, 25, 'እነርሱ እንደሚኖሩበት፥ ፀሐይም እንደሚኖርበት መጠን ዘመኑ እንዲህ በእውነት ይፈጸማል።'),
  ('450d4e35-91ce-5d8a-afab-969775da7ee2', '3f49f3bf-894c-5b2b-a828-9aa4a539863e', '030838ce-31ef-5e2e-acf6-197c71c3ac62', 26, 26, 'ከዋክብት ከሚወጡባቸው መስኮቶች ፀሐይ ሠላሳ ቀን ይወጣል፥ ይገባልም።'),
  ('0807f8d9-8057-54ad-a246-543155a5eafb', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 1, 1, 'በፍጥረታት ሁሉ ላይና በከዋክብት ሁሉ ላይ የተሾሙ የሻለቆችን የሚመሩ፥ እንደ ዘመኑ ቍጥር ሁሉ ከሚጨመርባቸውና ከመኖሪያቸው ጋር ከማይለዩት ከአራቱ ከዋክብት ጋር'),
  ('1a777a1c-b3b9-50e4-ad16-f2211dc9c2ea', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 2, 2, 'እነዚህም፥ በዓመቱ ቍጥር የማይቈጠሩ አራቱን ቀኖች'),
  ('175836b1-f2d3-5d3a-a869-ebb3a2dd7cdb', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 3, 3, 'እነዚያ ከዋክብት ዓለም ጸንቶበት በሚኖረው ዘመን በእውነት ይገዛሉና ሰዎች በእነርሱ ይበድላሉ።'),
  ('3656b052-cf7c-5b53-a6a7-96499299b3c8', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 4, 4, 'አንዱ በመጀመሪያው መስኮት'),
  ('b52c1a8f-6ffa-5cb5-abaa-3b474d641865', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 5, 5, 'ለምልክት'),
  ('c803dd39-5729-5138-a816-9cecac2e4063', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 6, 6, 'በዚህ ዓለም በሰማይ ያበሩ ዘንድ፥ በምድርም ላይ ይታዩ ዘንድ፥'),
  ('dc2d6288-1e39-5922-ac0b-444a2a6c2806', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 7, 7, 'ፀሐይና ጨረቃ፥ ከዋክብትም፥ በሰማይ ሠረገላዎች ሁሉ የሚዞሩ ቅንየታት የሚባሉ ኮከቦችም ሁሉ ለመዓልትና ለሌሊት መሪዎች ይሆኑ ዘንድ፥'),
  ('3fcef5ce-9a89-5568-aee2-47e1c929547a', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 8, 8, 'ዑርኤል በሰማይ ፀሐይ በሚመላለስባቸው በሠረገላዎች ዙሪያ የፀሐይ እግሮች ከእነርሱ የሚወጡባቸው የተከፈቱ ዐሥራ ሁለት መስኮቶችን እንዲህ አሳየኝ።'),
  ('27732803-b367-5f0d-ab3c-48a83f362c06', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 9, 9, 'በታወቁባቸው ዘመኖችም በተከፈቱ ጊዜ ከእነርሱ በምድር ላይ ድርቅ ይወጣል።'),
  ('f1369eaf-2a17-57d8-a1af-0616f16dc344', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 10, 10, 'ለነፋሳትና ጠልን ለሚያመጣ ነፋስ በዘመኖች በተከፈቱ ጊዜ በምድር ዳርቻ በሰማይ ሆኜ ፀሐይና ጨረቃ፥ ከዋክብትም፥ የሰማይ ፍጥረቶችም ሁሉ በምሥራቅና በምዕራብ ከእነርሱ የሚወጡባቸው የተከፈቱ ዐሥራ ሁለት መስኮቶችን በምድር ዳርቻ ባለ በሰማይ አየሁ።'),
  ('5902b254-4b7c-5543-a279-c5ec7e89172e', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 11, 11, 'ብዙ የተከፈቱ መስኮቶችም ከቀኙና ከግራው አሉ።'),
  ('0bbc227a-b3ca-599d-ae54-f0e3c9f16a19', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 12, 12, 'ጌታ እንዳዘዛቸው ከዋክብት ከእነርሱ እንደሚወጡባቸው፥ እንደ ቍጥራቸው መጠን፥ እንደሚገቡባቸውም እንደ እነዚያ መስኮቶች አንዲቱ መስኮት በዘመኗ ሙቀትን ታስገኛለች።'),
  ('6a4774ff-e5c7-54ac-a8c1-1c4c179e4e8b', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 13, 13, 'የማይገቡ ከዋክብት በሚመላለሱባቸው በእነዚያ መስኮቶች በበላያቸውና በበታቻቸው ሠረገላዎችን ለዘለዓለም በሰማይ ሲሮጡ አየሁ።'),
  ('3d4443d3-66d9-5793-a8ae-f95259131154', '27c412e6-1416-573c-aa23-c1befa75d173', 'a1af806a-dd6a-5020-a4c9-b1fc46fd3b23', 14, 14, 'ሁሉንም አንዱ'),
  ('2af3537b-ce83-5cc4-a55e-48d3b30a01b6', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 1, 1, 'ነፋሳት ከእነርሱ የሚወጡባቸውና በምድር ላይ የሚነፍሱባቸው፥ ለነፋስት ሁሉ የተከፈቱ ዐሥራ ሁለት መስኮቶችን በምድር ዳርቻ አየሁ።'),
  ('cf40f740-dbb9-5151-a2d2-2335612da6de', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 2, 2, 'ከእነርሱም ሦስቱ በምሥራቅ፥ ሦስቱም በምዕራብ፥ ሦስቱም በሰሜን፥ ሦስቱም በደቡብ የተከፈቱ ናቸው።'),
  ('2b302607-0ec4-537f-aaaf-08351791dbfd', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 3, 3, 'መጀመሪያዎቹ ሦስቱ በምሥራቅ፥ ሦስቱም በመስዕ፥ በኋላ በግራ በኩል ያየኋቸው ሦስቱ በአዜብ፥ ሦስቱም በምዕራብ ናቸው።'),
  ('326d54c5-e49f-56c9-a354-e0c619569a2e', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 4, 4, 'ከእነርሱም በአራቱ የበረከትና የሰላም ነፋሶች ይወጣሉ፤ ከእነዚያም ከስምንቱ የመቅሠፍት ነፋሶች ይወጣሉ።'),
  ('77de8fc0-ccdf-5cce-af59-131047ab5d3b', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 5, 5, 'እነዚህም በተላኩ ጊዜ ምድርን ሁላ ያጠፏታል፤ በእርሷም ላይ ያለውን ውኃ፥ በእርሷም ላይ የሚኖሩትን ሁሉ፥ በውኃና በየብስ ላይ ያለውንም ሁሉ ይደመስሳሉ።'),
  ('35bd3508-dfe5-5ecb-aeb3-df7bf4c8a5a2', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 6, 6, 'ከእነዚህም መስኮቶች ለአዜብ በምትቀርብ በምሥራቅ በኩል ባለች በመጀመሪያዋ መስኮት ስሙ ጽባሓይ የሚባል መጀመሪያው ነፋስ ይወጣል፤ ከእርስዋም የምድር ድምሳሴ፥ ድርቅና ጥፋት ይወጣል።'),
  ('e58184cc-6608-5dac-a7ec-060cda1a26cc', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 7, 7, 'በመካከል ባለች በሁለተኛዪቱ መስኮትም ቅንነት ይወጣል፤ ከእርሷም ዝናብ፥ ፍሬም፥ ሰላምና ጠልም ይወጣል።'),
  ('9d8d78a5-8773-57b1-a03c-047b5b024584', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 8, 8, 'በመስዕ በኩል ባለች በሦስተኛዪቱ መስኮትም ውርጭ፥ ድርቅም ይወጣል።'),
  ('5f5c4f81-819f-5328-a542-08ed480ccc5c', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 9, 9, 'ከእነዚህም ነፋሳት በኋላ በደቡብ በኩል ያሉ ነፋሳት በመጀመሪያዎቹ በሦስቱ መስኮቶች ይወጣሉ።'),
  ('34f73fc9-c1d9-5230-a33f-20badadf974c', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 10, 10, 'ከእነርሱም ለምሥራቅ በምትቀርብ በመጀመሪያዪቱ መስኮት የድርቅ ነፋስ ይወጣል።'),
  ('da8a3734-6b01-5379-a7b9-9af8501528da', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 11, 11, 'በእርስዋ አጠገብ ባለች በመካከለኛዪቱ መስኮትም ከእርስዋ መልካም ሽቱ፥ ጠልና ዝናም፥ ሰላምና ሕይወት ይወጣል።'),
  ('7fe4b344-c5da-58a1-af17-9227105a663b', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 12, 12, 'በምዕራብ በኩል ባለች በሦስተኛዪቱ መስኮትም ከእርስዋ ጠልና ዝናም፥ ኩብኩባና ድምሳሴም ይወጣል።'),
  ('81fe78f5-f5ed-5e9e-a8cc-6624f995f7b2', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 13, 13, 'ስሙ ባሕር በሚባል በመስዕ በኩል ካሉ ነፋሶች በኋላ ከሦስቱ መስኮቶች ለአዜብ በምትቀርብ በምሥራቅ በኩል ባለች በሰባተኛዪቱ መስኮት ከእርስዋ ጠልና ዝናም፥ ኩብኩባና ድምሳሴም ይወጣል።'),
  ('5e79f7c4-7dab-54e8-a7ef-fb9cd72c1869', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 14, 14, 'በቀጥተኛዪቱ በመካከለኛዋ መስኮትም ከእርስዋ ዝናምና ጠል፥ ሕይወትና ሰላም ይወጣል።'),
  ('f56634d6-ab47-5b55-a518-729f0f1a0d7e', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 15, 15, 'ለመስዕ በምትቀርብ በምዕራብ በኩል ባለች በሦስተኛዪቱ መስኮትም ከእርስዋ ጉምና ውርጭ፥ ዋግና ጠል፥ ዝናምና ኩብኩባም ይወጣል።'),
  ('1e83f3fc-890f-5265-a04a-b8f360997255', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 16, 16, 'በምዕራብ በኩል ካሉ ከእነዚህ ከአራቱ ነፋሳት በኋላ ለመስዕ በቀረበች በመጀመሪያዪቱ መስኮት ከእርስዋ ጠልና ዝናም፥ የረጋውና የተበተነው ውርጭ፥ ዋግና ቀቅም ይወጣል።'),
  ('6bd78d95-bd83-5d50-a8a6-fb59d9a672a3', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 17, 17, 'ከመካከለኛዪቱ መስኮትም ጠልና ዝናም፥ ሰላምና በረከትም ይወጣል።'),
  ('58cda06d-ca23-5d75-a7de-1d3eb07f4839', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 18, 18, 'በአዜብ በኩል ባለች በሁለተኛዪቱ መስኮትም ከእርስዋ ድርቅና ድምሳሴ፥ ዋዕይና ጥፋት ይወጣል።'),
  ('9a7e9622-8e32-5450-affe-d0974ea7a084', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 19, 19, 'በአራቱ የሰማይ ማዕዘን ያሉ ዐሥራ ሁለቱ መስኮቶች ተፈጸሙ። ልጄ ማቱሳላ! ትእዛዛቸውን ሁሉና መቅሠፍታቸውን ሁሉ፥ ሰላማቸውንም ሁሉ አሳየሁህ።'),
  ('28540c20-ec31-5d57-a895-ebdeac5a9210', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 20, 20, 'መጀመሪያ ነውና መጀመሪያውን ነፋስ ስሙን ጽባሓዊ ብለው ይጠሩታል።'),
  ('d0a767e7-483e-54ef-acc9-06efda53a3d2', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 21, 21, 'በዚያ ልዑል'),
  ('0cdf070c-77a8-59a9-a1db-97b7d5a61467', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 22, 22, 'የሰማይ ብርሃናት ሁሉ በዚያ ይጐድላሉና፥ ወደዚያም ይወርዳሉና ከምዕራብ የሚነፍሰውንም ነፋስ ጐደሎ ብለው ይጠሩታል።'),
  ('6dbbb00f-4b3e-59d6-aa4f-98d3f83d35c4', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 23, 23, 'ስሙ መስዕ የሚባል አራተኛው ነፋስ ከሦስት ይከፈላል፤ ከእነርሱም አንዱ ለሰው ማደሪያ ነው፤ ሁለተኛውም በውኃ ባሕሮችና በጥልቆች፥ በዛፍና በወንዞችም፥ በጨለማና በጉምም የተሾመ ነው። ሦስተኛውም ክፍል በጽድቅ ገነት የተሾመ ነው።'),
  ('06e7d16c-6fef-51c9-aff6-87e112a541b0', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 24, 24, 'በምድር ካሉ ተራሮች ሁሉ የሚረዝሙ ሰባት ረጃጅሞች ተራሮችንም አየሁ።'),
  ('62361a58-34db-5564-a3e3-da19c0cbd5ec', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 25, 25, 'ከእነርሱም ውርጭ ይወጣል፤ ቀኑም፥ ዘመኑም፥ ዓመቱም ያልፋል፥ ይሄዳልም።'),
  ('520fb091-d07b-59b7-a8fc-e64158e06169', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 26, 26, 'ከፈሳሾች ሁሉ የሚበልጡ ሰባት ፈሳሾችን በምድር ላይ አየሁ፤ ከእነርሱም አንዱ ከምዕራብ መጥቶ ሰፊ ወደ ሆነው ውቅያኖስ ውኃውን ያፈስሳል።'),
  ('0d377a52-6207-593a-aec4-67baf3b11ace', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 27, 27, 'እነዚያም ሁለቱ ከመስዕ እስከ ባሕር ድረስ መጥተው ውኃቸውን ከወደ ምሥራቅ በኤርትራ ባሕር ያፈስሳሉ።'),
  ('e548ce8d-0532-5fbb-aee5-d598ae4a9bbe', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 28, 28, 'የቀሩትም አራቱ የእነርሱ ባሕር እስከሚሆነው እስከ ኤርትራ ባሕር ድረስ በመስዕ አጠገብ ይፈስሳሉ።'),
  ('0742c721-e279-5122-a860-49ad24b6c702', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 29, 29, 'ሁለቱ ፈሳሾችም ወደ ታላቁ ባሕር ይጨመራሉ፤ በዚያም ይከማቻሉ።'),
  ('10d0d17e-139d-5cac-adfe-bec9e062ff25', '593cc9e0-7a69-5546-aac4-a6f92acd194e', '5bd15d42-0f02-5e9e-abb3-b99190eaf8dc', 30, 30, 'በባሕርና በየብስ ሰባት ታላላቅ ደሴቶችን አየሁ፤ ከእነዚያም ሁለቱ በየብስ፥ አምስቱም በታላቁ ባሕር ናቸው።'),
  ('5ebcc2e2-0b03-5234-a120-5ca615d61254', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 1, 1, 'የፀሐይ ስሙ እንደዚህ ነው፤ አንዱ ኦርያሬስ፥ ሁለተኛውም ቶማስስ ይባላል።'),
  ('2b198495-3238-564d-a1b5-b498d65d03ed', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 2, 2, 'ለጨረቃም አራት ስሞች አሉት፤ አንዱ ስሙ አሶንያ ይባላል፥ ሁለተኛውም ዕብላ ይባላል፥ ሦስተኛው ብናሴ ይባላል፥ አራተኛውም ኤራዕ ይባላል።'),
  ('5a065580-3fe7-50e8-ae4f-d4c1135370df', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 3, 3, 'ታላላቅ ብርሃናት እነዚህ ሁለቱ ናቸው፤ ክበባቸውም እንደ ሰማይ ክበብ ነው፤ የሁለቱም መጠኖቻቸው እኩል ናቸው።'),
  ('c1135f8a-288e-555f-a603-8359efe596ee', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 4, 4, 'በፀሐይ ሰሌዳም ከጨረቃ ሰባት ክፍለ ብርሃን ይጨመርበታል፥ የፀሐይ ሰባተኛው ክፍል እስኪጨረስ ድረስ በልክ ትቀበላለች።'),
  ('d0e9a6f8-7308-5559-a645-6e7b836f7b28', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 5, 5, 'በምዕራብ መስኮት ይገባሉ፥ ወደ መስዕም ይዞራሉ፥ በምሥራቅም መስኮት በሰማይ ፊት ይወጣሉ።'),
  ('a4d02465-a276-5fc9-a278-ec2e4788702a', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 6, 6, 'ጨረቃም በወጣ ጊዜ በሰማይ ይታያል፤ የሰባተኛውን ክፍለ ብርሃን እኩሌታም ይቀበላል።'),
  ('e84b75c3-5c60-5268-a0a2-83c14b56e993', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 7, 7, 'በዐሥራ አራተኛው ቀንም ብርሃኑን ፈጽሞ ያገኛል፤ ሦስት አምስተኛ ክፍለ ብርሃንም ይጨመርለታል።'),
  ('e50bc1d2-f2de-577a-a356-6d005f39fc4b', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 8, 8, 'ለዘመን ምልክት ሊሆን እስከ ዐሥራ አምስት ቀን ብርሃኑን ፈጽሞ ያገኛል፤ ሦስት አምስተኛም ይሆናል፤ ጨረቃም በአንድ ሰባተኛ እጅ እኩሌታ ይሆናል።'),
  ('98f86e6e-5ef3-5083-a5c1-16c05ea91847', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 9, 9, 'በሕፀፁም ጊዜ በመጀመሪያዪቱ ቀን ዐሥራ አራተኛውን እጅ ክፍለ ብርሃን ያጣል፤ በሁለተኛዪቱም ቀን ዐሥራ ሦስተኛዪቱን እጅ ያጣል።'),
  ('cb496ede-23b1-58c9-a5e6-7b87d67f8c7e', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 10, 10, 'በሦስተኛውም ቀን ዐሥራ ሁለተኛውን እጅ ያጣል፤ በአራተኛውም ቀን ዐሥራ አንደኛውን እጅ ያጣል።'),
  ('3ea16102-2273-552e-ae1c-588db9387e68', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 11, 11, 'በአምስተኛውም ቀን ዐሥረኛውን ክፍል ያጣል፤ በስድስተኛውም ቀን ዘጠነኛውን ክፍል ያጣል።'),
  ('f07dde69-8bbb-5cbf-a538-733859f2297f', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 12, 12, 'በሰባተኛውም ቀን ስምንተኛውን ክፍል ያጣል፥ በስምንተኛውም ቀን ሰባተኛውን ክፍል ያጣል።'),
  ('8b993972-f2eb-5198-ac0c-a7e94d59e40d', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 13, 13, 'በዘጠነኛውም ቀን ስድስተኛውን ክፍል ያጣል፤ በዐሥረኛውም ቀን አምስተኛውን ክፍል ያጣል።'),
  ('e7b947ab-fd64-5791-aeb7-2f76d93ed85f', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 14, 14, 'በዐሥራ አንደኛውም ቀን አራተኛውን ክፍል ያጣል፤ በዐሥራ ሁለተኛውም ቀን ሦስተኛውን ክፍል ያጣል።'),
  ('7b2b3976-a927-57fb-a8a3-700212b48fb0', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 15, 15, 'በዐሥራ ሦስተኛውም ቀን ሁለተኛውን ክፍል ያጣል፤ በዐሥራ አራተኛውም ቀን የሰባተኛውን እጅ እኩሌታ ያጣል።'),
  ('e362859f-9c99-575b-a02b-967882c2bc61', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 16, 16, 'በዐሥራ አምስተኛው ቀንም ከብርሃን የቀረ ብርሃኑ ሁሉ ይጨረሳል።'),
  ('aafc91c2-4077-5938-a68e-a7464a22787d', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 17, 17, 'በታወቁም ወራቶች በእየሃያ ዘጠነኛው ቀን ለጨረቃ ምላት ይሆናል፤ በእየሃያ ስምንተኛው ቀንም ምላት የሚደረግበት ጊዜ አለ።'),
  ('24c31367-1f7e-59af-a045-0c7897617675', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 18, 18, 'መልአኩ ዑርኤልም ብርሃን በጨረቃ በተሣለ ጊዜ ሌላ ሥርዐትን አሳየኝ።'),
  ('3b2d3382-2535-5085-a21e-3c442ec55b0b', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 19, 19, 'ጨረቃም ከፀሐይ ብርሃን ከሚጨመርላት ቀን ጀምሮ በምትሄድበት ዘመን ሁሉ ብርሃኗን በፀሐይ ፊት ታገኛለች፤ እስከ ዐሥራ አራተኛው ቀን ድረስም ብርሃኗ በሰማይ ይፈጸማል።'),
  ('bd1b4d85-4729-5e39-ac69-ab8a903f2654', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 20, 20, 'ሁሉም'),
  ('24695726-4e94-5886-ae0a-b93bfdfdccf9', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 21, 21, 'ፀሐይ ወደ ምዕራብ በሚገባበትም ቀን ብርሃኑ በጥንቃቄ ይጨረሳል፥ በሌሊትም ከምሥራቅ ይወጣል።'),
  ('bcce2517-2745-570e-a9fe-2c19c8f351e3', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 22, 22, 'ፀሐይም በፊቱ እስኪወጣ ድረስ ጨረቃ መላ ሌሊቱን ያበራል፤ ጨረቃም በፀሐይ ፊት ይተያያል።'),
  ('18f33dcc-6d02-572a-a55b-c6c07ed452ff', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 23, 23, 'የጨረቃ ብርሃን ከወጣበት ጀምሮ ብርሃኑ ሁሉ እስኪጨረስ ድረስ ዳግመኛ ከዚያ ይጐድላል።'),
  ('48584746-4564-57d1-ac77-50a6363265ef', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 24, 24, 'ጨረቃም የሚያበራበት ወር ያልፋል፥ ሰሌዳውም ብርሃን የሌለበት ባዶ ይሆናል።'),
  ('140985d4-6cbf-5b6f-ae89-7f19163e732f', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 25, 25, 'ሦስት ወር ምላት በሚያደርግበት ዘመኑ በሠላሳኛው ቀን ሕፀፅ ያደርጋል። ሦስቱንም ወር ሕፀፅ በሚያደርግባቸው ቀኖች በእየሃያ ዘጠነኛው ቀን ሕፀፅ ያደርጋል።'),
  ('72fad340-56d5-5f57-ae9d-6c71b517da9e', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 26, 26, 'በመጀመሪያው ዘመን፥ በመጀመሪያው መስኮት በመቶ ሰባ ሰባት ቀን፥ በመወለጃውም ዘመን ሦስቱን ወር በየሠላሳኛው ቀን ይታያል። ሦስቱንም ወር በእየሃያ ዘጠነኛው ቀን ይታያል።'),
  ('737a2ae5-db3f-5b71-a6b9-29c2da728182', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 27, 27, 'ያለ ፀሐይ ብርሃን ሌላ ብርሃን ምንም የላትምና በእየሃያኛው ቀን በሌሊት ሰው መስሎ፥ በቀንም ሰማይ መስሎ ይታያል።'),
  ('ff292efb-e5c3-5844-a472-60b2c81f1fa7', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 28, 28, 'አሁንም ልጄ ማቱሳላ ሆይ፥ ሁሉን አሳየሁህ፤ የሰማይ ከዋክብት ሥርዐት ሁሉ ተፈጸመ።'),
  ('e7b578cb-e98b-5033-a7a0-e6fed00a9eaf', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 29, 29, 'በእየቀኑ ሁሉና በእየዘመኑ ሁሉ፥ በእየሹመታቸውም ሁሉ፥ በእየዓመቱም ሁሉ፥ በመውጫውና በታዘዘበት ሁሉ፥ በወሩ ሁሉና በሱባዔው ሁሉ የሚሆነውን የእነዚህን ሥርዐት አሳየኝ።'),
  ('119206c3-36ca-501d-a153-ee81ae4ce9a4', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 30, 30, 'በዚች በስድስተኛዪቱ መስኮት ብርሃኑ ጨርሶ ይጠፋልና በስድስተኛዪቱ መስኮት የሚደረግ የጨረቃንም ሕፀፅ አሳየኝ።'),
  ('e6bfcac0-f769-588b-a347-7d6eef3af026', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 31, 31, 'ከዚያም በኋላ የወር መባቻ ይሆናል፤ ሕፀፅ በሚያደርግበትም ዘመን በመጀመሪያዪቱ መስኮት የሚደረገውን ሕፀፅ አሳየኝ።'),
  ('9f236c1d-0caf-5ec5-aec5-d1e804bd6b63', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 32, 32, 'መቶ ሰባ ሰባት ቀን እስኪፈጸም ድረስ በሱባዔው ሥርዐት ቢቈጥሩት ሃያ አምስት ሱባዔ ከሁለት ቀን ይሆናል።'),
  ('5ad35c47-206f-5162-a920-0f850ab43184', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 33, 33, 'ጨረቃ በአንዱ ዓመት ከፀሐይና ከከዋክብት ሥርዐት የሚያንሰው በጥንቃቄ ቢቈጠር አምስት ቀን ይሆናል።'),
  ('162218c6-41fe-5c66-a7e1-2905205b5040', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 34, 34, 'ይህም የምታየው አንቀጽ በተፈጸመ ጊዜ መሪያቸው ታላቁ መልአክ ዑርኤል ካሳየኝ ከብርሃን ሁሉ የሚበልጥ እንደዚህ ያለ አርኣያና ምሳሌን ታያለህ።'),
  ('1a3526ef-61f6-52bb-ad7a-be4e83c2ed55', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 35, 35, 'በዚያም ወራት መልአኩ ዑርኤል ሄኖክ ሆይ፥ “እነሆ፥ ሁሉን አሳየሁህ” ብሎ መለሰልኝ።'),
  ('7f43a879-7aa4-5128-aca9-ce87b1195153', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 36, 36, 'ይህን ፀሐይ፥ ይህንም ጨረቃ ታየው ዘንድ፥ የሰማይ ከዋክብትን የሚመሯቸውን፥'),
  ('5b55f67d-2205-5dfc-ad13-c032727c64e2', '6bc686b9-cb94-5b85-a120-591454167cfa', 'de47a733-e63f-5874-ad17-6512e572a85c', 37, 37, 'ሥራቸውንና ዘመናቸውንም፥ መውጫቸውንም የሚለውጡትን ሁሉ ታያቸው ዘንድ ገለጥሁልህ።'),
  ('30452c73-f64b-5cd2-a611-feddb8fc4133', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 1, 1, 'በኃጥኣንም ወራት ክረምቶች ያጥራሉ፤ በእርሻቸውና በመሰምሪያቸው ያለ አዝመራቸውም በኋላ ይደርሳል።'),
  ('03ac87cf-0115-5654-a9fd-a703c8be81c5', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 2, 2, 'በምድር ላይ ያለ ሥራ ሁሉ ይለወጣል፥ በዘመኑም አይታይም፤ ዝናምም ይከለከላል፥ ሰማይም ዝናምን ታቆማለች።'),
  ('fddcb3f1-5b79-538b-a974-dd84e3c83bc7', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 3, 3, 'በእነዚያም ዘመኖች የምድሩ ፍሬ ኋለኛ ይሆናል፥ በዘመኑም አይበቅልም፤ የዛፉም ፍሬ በዘመኑ ከማፍራት ይከለከላል።'),
  ('c3c7e7a7-b343-54db-a7e1-fe139f1d84cc', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 4, 4, 'ጨረቃም ሥርዐቱን ይለውጣል፥ በዘመኑም ሲያበራ አይታይም።'),
  ('2c53482c-3266-5852-a768-e09e7f0ad3b6', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 5, 5, 'በእነዚያም ወራቶች ሰማይ ጠርቶ ይታያል፤ ድርቅም በምዕራብ በኩል በታላቅ ሠረገላ ዳርቻ ሁኖ ይደርሳል፥ ሰማይም ከብርሃን ሥርዐት ይልቅ ፈጽሞ ያበራል።'),
  ('803f6b28-bd23-521f-abd0-9aa96aa4a48f', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 6, 6, 'ብዙዎች የትእዛዝ ከዋክብት አለቆችን ይስታሉ፤ እኒህም መንገዳቸውንና ግብራቸውን ይለውጣሉ፥ በታዘዙላቸው ዘመኖቻቸውም አይታዩም።'),
  ('aa52c6df-61c7-51dc-a0ba-5a64fba3b424', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 7, 7, 'የከዋክብት ሥርዐትም ሁሉ በኀጢአተኞች ላይ ይለወጥባቸዋል፥ በምድር ላይም የሚኖሩ ሰዎች በእነርሱ ላይ አእምሮአቸውን ይለውጣሉ።'),
  ('c50a34c7-7801-58cf-a993-3b5a2a54f6a9', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 8, 8, 'ከመንገዳቸውም ሁሉ ይለወጣሉ፥ ይስታሉ፥ አማልክትንም ያስመስሏቸዋል።'),
  ('b8935127-f118-50e4-aef2-60ed4628a529', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 9, 9, 'መከራም ይበዛባቸዋል፥ መቅሠፍትም ሁሉን ያጠፋቸው ዘንድ ይመጣባቸዋል።'),
  ('d3e646e5-f029-526d-aba1-6b856ba6ea62', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 10, 10, 'እንዲህም አለኝ- “ሄኖክ ሆይ! በሰማይ ሰሌዳ የተጻፈውን መጽሐፍ ተመልከት፥ በእነርሱም የተጻፈውን አንብብ። እያንዳንዱንም ሁሉ መርምረህ ዕወቅ።” በሰማይ ሰሌዳ የተጻፈውንም ተመለከትሁ፤ የተጻፈውንም ሁሉ አነበብሁ፥ ሁሉንም ዐወቅሁ።'),
  ('0be5c7ea-958b-5134-a1cd-a26b0e55379f', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 11, 11, 'መጽሐፊቱንም አነበብኋት፥ በእርሷም የተጻፈውን የሰዎችን ሥራ ሁሉ ተመለከትሁ፤ እስከ ዓለም ትውልድ ድረስ በምድር ላይ ያለ ከሥጋ የተወለደውንም ሁሉ አየሁ።'),
  ('81a7c37b-3665-5823-a1b7-ccac89077d31', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 12, 12, 'ከዚህም በኋላ ያንጊዜ የዓለሙን ሥራ ሁሉ እንደ ሠራ ታላቁን የዘለዓለማዊ ክብር ንጉሥ ጌታን አመሰገንሁት።'),
  ('c0e36207-5de5-5e15-a120-323f236ece0d', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 13, 13, 'ስለ ትዕግሥቱም ጌታን አከበርሁ፤ አመሰገንሁም፥ በአዳም ልጆችም ላይ አለቀስሁ።'),
  ('ba34333f-54cb-5a41-ad1b-f3911df5ad80', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 14, 14, 'ያንጊዜም እንዲህ አልሁ- “ጻድቅና ቸር ሳለ የሚሞት፥ የበደልም ደብዳቤ ሁሉ ያልተጻፈበት፥ በፍርድ ቀንም በእርሱ ላይ በደል ያልተገኘበት ሰው ብፁዕ ነው።”'),
  ('42db1356-af88-5a82-ae08-447bf1f098b5', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 15, 15, 'እነዚያም ሦስቱ ቅዱሳን'),
  ('2c6c22d7-d298-5ee8-ae21-e7e57a2a7e17', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 16, 16, 'እንዲህም አሉኝ- “ለልጅህ ለማቱሳላ ይኽን ሁሉ ንገር፤ በጌታ ፊትም ሥጋዊ ሰው ሁሉ እንደማይጸድቅ ለልጆችህ ሁሉ ይህን ገልጠህ አስተምር፥ እርሱ ፈጥሮአቸዋልና።'),
  ('90571221-541e-5008-a28f-cfba2d7190a6', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 17, 17, 'ልጆችህን ታስተምራቸው ዘንድ፥ ትጽፍላቸውም ዘንድ፥ ለልጆችህም ሁሉ ታዳኝባቸው ዘንድ ዳግመኛ እስክታዝዛቸው ድረስ በልጆችህ ዘንድ አንድ ዓመት እንተውሃለን።'),
  ('c799fbd3-817e-5c19-a114-d19c6af85cf9', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 18, 18, 'በሁለተኛው ዓመት ግን ከእነርሱ መካከል ይወስዱሃል፤ ደጎች ለደጎች እውነትን ያስተምራሉና ልቡናህ ይጽና።'),
  ('ecdef0fe-03cc-56e6-aa58-9612b2d05175', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 19, 19, 'ጻድቅ ከጻድቅ ጋር ደስ ይለዋል፥ እርስ በርሳቸውም ሰላምታ ይሰጣጣሉ፤ ኃጥእም ከኃጥእ ጋር ይሞታል፥ ወደ ኀጢአትም የተመለሰ ወደ ኀጢአት ከተመለሰው ጋራ ይሰጥማል።'),
  ('457b0305-5b84-5a73-ab47-d6c1b4d920ac', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 20, 20, 'ጽድቅንም የሚሠሩ ሰዎች በክፉ ሰዎች ሥራ ይሞታሉ፥ ስለ ክፉ ሰዎች ሥራም ይሰበሰባሉ።'),
  ('cade2d6d-db05-5fab-a84b-89b3bf43fb30', '0773f202-fe3c-512f-aa1e-4da0e853ace3', '5d247fc5-a671-5348-a449-8229b43bf4a2', 21, 21, 'በእነዚያም ወራቶች ከእኔ ጋር መነጋገራቸውን ጨረሱ፥ የዓለማትንም ጌታ እያመሰገንሁ ወደ ዘመዶቼ ተመለስሁ።'),
  ('3f62a4cb-9e10-5690-a00d-0f9fa9aae36c', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 1, 1, 'አሁንም ልጄ ማቱሳላ፥ እነዚህን ሁሉ ለአንተ እናገራለሁ፤ ለአንተም እጽፍልሃለሁ፥ ሁሉንም ገለጥሁልህ፤ የእነዚህንም ሁሉ መጻፎቻቸውን ሰጠሁህ።'),
  ('86e88a10-e263-5abe-a3fe-37d84404a14c', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 2, 2, 'ልጄ ማቱሳላ፥ ለዓለም ትውልድ ታስተላልፍ ዘንድ የአባትህን የእጅ መጻፎች ጠብቅ።'),
  ('1ad6d021-f660-557b-a5ff-34e5e1d61dbd', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 3, 3, 'ለአንተና ለልጆችህ፥ ለአንተም ልጆች ለሚሆኑት ጥበብን ሰጠሁህ። ይህችም ጥበብ ለልጆቻቸውና ለልጅ ልጆቻቸው እስከ ዘለዓለም ያስተላልፉ ዘንድ በሕሊናቸው ትኖራለች።'),
  ('b89a1949-d0e1-5ed2-aed9-e0ed00c54d32', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 4, 4, 'ይህችን ጥበብ ይማሯት ዘንድ የሚያስተውሉና በጆሯቸው የሚያደምጡ ሰዎች አያንቀላፉም፥ ለሚበሏትም ካማሩ ምግቦች ይልቅ ትስማማቸዋለች።'),
  ('e531af35-e395-5c67-af41-4319eeb80278', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 5, 5, 'ጻድቃንም ሁሉ ብፁዓን ናቸው፤ በጽድቅ መንገድ የሚሄዱና በዘመናቸው ሁሉ ቍጥር እንደ ኃጥኣን ኀጢአት የሌለባቸውም ብፁዓን ናቸው።'),
  ('f20e21a1-af1c-5f41-a035-1777a50aabaa', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 6, 6, 'በሰማይ የሚሄድ ፀሓይ፥ ከሻለቆች ጋር በመስኮቶች ሠላሳ ቀን ይገባል፥ ይወጣልም።'),
  ('a046dc3e-cafb-55c8-abb0-b7ff8b90e8e5', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 7, 7, 'ከሚጨመሩላቸውና አራቱን ክፍለ ዘመን ከሚለዩ ከሚመሯቸው አራት ከዋክብት ጋራ የከዋክብት ሥርዐታቸው ይህ ነው።'),
  ('fd3f361c-1e72-5852-a6e8-6e5e0e6a28ae', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 8, 8, 'ከእነርሱም ጋር አራት ቀን ይገባሉ፥ ስለ እነርሱም ሰዎች ይሳሳታሉ፤ በዓለሙ ሁሉ ቍጥርም አይቈጥሯቸውም፥ ይስትWaቸዋልና።'),
  ('a685680b-17b2-5105-a032-b8bc9db7f308', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 9, 9, 'ሰዎችም ጠንቅቀው አያውቋቸውም፤ በዘመኑ ቍጥር አሉና፥ ለዘለዓለምም በእውነት የተጻፉ ናቸው።'),
  ('948b8ac8-dc89-5a09-ab7c-9ad7320feeee', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 10, 10, 'አንዱ በመጀመሪያዪቱ መስኮት፥ አንዱም በሦስተኛዪቱ መስኮት፥ አንዱም በአራተኛዪቱ መስኮት፥ አንዱም በስድስተኛዪቱ መስኮት ይገባል።'),
  ('bd03385a-accc-59da-a608-2ce040e8ed7a', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 11, 11, 'ዓመቱም በሦስት መቶ ስድሳ አራት ቀን ይፈጸማል፤ ነገሩም እውነት ነው፥ የተጻፈውም ቍጥሩ የተጠነቀቀ ነው።'),
  ('467fac8d-c456-54c7-aa03-16793ecc5757', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 12, 12, 'የዓለም ፍጥረት ሁሉ ጌታ ስለ ሰማይ ሠራዊት ለእኔ ያዘዘልኝ መልአኩ ዑርኤል ስለ ብርሃናትና ወሮች፥ ስለ በዓላት፥ ስለ አራቱ ክፍለ ዘመኖችና ዓመታት፥ ስለቀኖችም አሳየኝ፤ ዕውቀትንም አሳደረብኝ።'),
  ('632f72b5-658b-5398-a037-9993e3eb9c80', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 13, 13, 'እርሱም በሰዎች ላይ በሰማይ የፀሐይንና የጨረቃን፥ የከዋክብትንም፥ በክበባቸው የሚመላለሱ የሰማይ ሠራዊትንም ሁሉ ብርሃን ያሳይ ዘንድ በመዓልትና በሌሊት ሥልጣን አለው።'),
  ('9145a0af-9525-54fa-a302-d2ef2e5cb174', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 14, 14, 'በቦታዎቻቸውና በዘመኖቻቸው፥ በሱባዔዎቻቸውና በወሮቻቸውም የሚወጡና የሚገቡ የከዋክብት ሥርዐት ይህቺ ናት።'),
  ('a5b3154a-4b2f-5236-a918-b1fd3387ab1d', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 15, 15, 'ምግብናቸውን የሚጠብቁ ከዋክብትን የሚመሩ የከዋክብት ስማቸው ይህ ነው፤ በዘመኖቻቸውና በሥርዐቶቻቸው፥ በጊዜዎቻቸውና በወሮቻቸው፥ በሥልጣኖቻቸውም በመቋሚያዎቻቸውም ይገባሉ።'),
  ('24038e2e-780d-56cf-a5ec-a7acee65086c', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 16, 16, 'አራቱን ክፍለ ዓመት የሚለዩ አራቱ መሪዎቻቸው አስቀድመው ይገባሉ።'),
  ('87e19919-c476-5b26-a9d8-d48a9d098d14', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 17, 17, 'ከእነርሱም ቀጥሎ ሠላሳውን ቀንና ሦስት መቶ ስድሳ አራት ቀን የሚሆን ዓመቱን የሚለዩ ሥርዐታት የሚባሉ ኮከቦችን የሚመሩ ዐሥራ ሁለት የወር መጋቢዎች፥ ሰባቱን ዕለታትና አራቱን ክፍለ ዘመን በሚለዩ በዘጠና አንድ መጋቢዎች ላይ የሚጨመሩ አራቱንም ጳጉሜን ከሚለዩ ከሺ አለቆች ጋር ይገባሉ።'),
  ('b1d413ba-e036-563e-ade8-ea5c9ed350b8', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 18, 18, 'እነዚያም የሺህ አለቆቹ በመሪና በተመሪ መካከል ናቸው፥ አንዱም በአንዱ መቋሚያ በኋላ ይጨመራል፤ መሪዎቻቸውም ሠላሳውን ቀን ይለያሉ።'),
  ('43961b50-d258-5877-a8e0-6436d0d6242f', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 19, 19, 'የተሠሩ አራቱን ክፍለ ዘመን የሚለዩ የእነዚህ መጋቢዎች'),
  ('f3268003-2d3a-5047-a1f1-0b010f16ecc0', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 20, 20, 'የሺህ አለቆችን የሚመሯቸው የወር መጋቢዎች ስማቸው አንድርናኤል፥ ኢየሱሳኤል፥ ኢይሉማኤልም ናቸው።'),
  ('a1dd5430-8072-5fa9-a7db-9a6a057078ce', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 21, 21, 'ሥርዐታት የሚባሉ የሻለቆችን የሚመሩ መጋቢዎችን'),
  ('9c92e23d-c158-5084-adfc-0e5fa0a60e72', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 22, 22, 'አንዱም- አራቱን ክፍለ ዘመን የሚለዩ ምቅዋማትን'),
  ('cfad7081-d8fa-5d52-aade-69f6f05373dd', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 23, 23, 'ስሙ ተመዓኒና'),
  ('c155298b-f5c4-5828-a3f5-62d5cb4cb126', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 24, 24, 'በምግብናው የሚመግባቸው ቀኖችም ሁሉ ዘጠና አንድ ቀኖች ናቸው።'),
  ('54dccf18-a34e-5513-a1c5-0a272a01a9ab', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 25, 25, 'በእርሱ ምግብና ወራትም በምድር ላይ ይታዩ ዘንድ ያላቸው እነዚህ የቀኖቹ ምልክቶች ላብ፥ ዋዕይና ኀዘን ናቸው።'),
  ('82512140-ba43-57b5-a844-35e2ded911cd', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 26, 26, 'ዛፎችም ሁሉ ያፈራሉ፤ ቅጠልም በዛፎች ሁሉ ላይ ይወጣል፤ የስንዴውም መከርና ጽጌረዳውም፥ ሌሎች አበባዎችም ሁሉ በሜዳው ያብባሉ፤ በክረምት የሚለመልሙ ዛፎችም ይደርቃሉ።'),
  ('3a122c78-c263-5292-a0e4-8df4d47a6867', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 27, 27, 'በበታቾቻቸው ያሉ የመሪዎቻቸው ስሞች ብርክኤልና ዘሓብሳኤል ናቸው፤'),
  ('d4bef59f-1104-52b7-a51b-e59f4ec5f51c', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 28, 28, 'ከእነርሱ ጋር የሚጨመር ሌላው የሻለቃ ስሙ ሄሉያሴፍ ነው።'),
  ('601315b9-6617-52fd-a1ac-f420cfef3814', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 29, 29, 'የዚህ የምልክኤል የምግብናው ወራት ተፈጸመ፤ ከእርሱም ቀጥሎ ሁለተኛው መጋቢ ስሙን ብሩህ ፀሐይ ብለው የሚጠሩት ሕልመልመሌክ ነው።'),
  ('dd87dd81-fb19-5ce8-a42b-94242b834529', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 30, 30, 'የሚያበራበትም ቀን ሁሉ ዘጠና አንድ ቀን ነው፤ በምድር ላይ የሚመግብባቸው ወራቶች ምልክቶች ሙቀትና ድርቅ ናቸው።'),
  ('27536cc4-36c6-53ef-a098-426351ae0092', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 31, 31, 'ዛፎችም ፈጽሞ የበሰለ ፍሬያቸውን ያወጣሉ፥ የደረቀ ፍሬያቸውንም ይሰጣሉ፤ በጎችም ይንጠላጠላሉ፥ ይፀንሳሉም።'),
  ('5507ab2e-63bd-5b2f-a57f-a1fa27fe292c', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 32, 32, 'ሰዎችም የምድር ፍሬን ሁሉ፥ በእርሻውም ያለውን ፍሬ ሁሉ፥ በወይኑ ዐውድማ ያለውን ፍሬ ሁሉ ይሰበስባሉ፥ በምግብናውም ወራት ይህ ሁሉ ይደረጋል።'),
  ('a1e7c6b6-c889-5845-afae-da10f86c73d8', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 33, 33, 'ስማቸውና ሥርዐቶቻቸውም እነዚህ ናቸው፤ በበታቻቸው ያሉ የዕለት መጋቢዎችን የሚመሩ የሻለቆችም ስማቸው ጊዳኤልና ኪኤል፥ ሄኤልም ናቸው።'),
  ('b65907f4-9ca8-52bc-a030-4e147844211f', 'f674c8d9-807c-5c82-a2af-e665bf912921', 'c30d4f97-3853-5e96-adc1-075eb18be396', 34, 34, 'ከእነርሱም ጋር የሚጨመር የሺህ አለቃ ስሙ አስፋኤል ነው፥ የምግብናውም ወራት ተፈጸመ።'),
  ('97d898a4-0de7-5f26-a1d1-8e3c7e7a5660', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 1, 1, 'ልጄ ማቱሳላ፥ ዛሬ ያየሁትን ራእይ ሁሉ ገለጥሁልህ፥ ይህንም በፊትህ እናገራለሁ።'),
  ('80b4f551-18f4-5427-a19e-ac0c0b36c2b3', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 2, 2, 'ሚስት ሳላገባ ሁለት ራእዮችን አየሁ፤ ከእነርሱም አንዱ ከሌላው ጋር አይመሳሰልም።'),
  ('e9de106c-74d4-52be-a5c3-aeb34b3c0d14', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 3, 3, 'መጀመሪያውን ራእይ መጽሐፍን በምማርበት ጊዜ አየሁ፤ ሁለተኛም እናትህን ሳላገባት ጽኑዕ ራእይን አየሁ።'),
  ('473ecbb0-f1af-5347-a351-0f70add9f010', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 4, 4, 'ስለ እነዚህም ነገሮች ጌታን ለመንሁት፤ በአያቴ በመላልኤልም ቤት ተኝቼ ሳለሁ በራእይ ሰማይ ሲወድቅና ሲነጠቅ፥ በምድርም ላይ ሲወድቅ አየሁ።'),
  ('ce8bb329-9fb0-53a6-a0bc-4615f0d2b2ba', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 5, 5, 'በምድርም ላይ በወደቀ ጊዜ ምድርን በታላቅ ጥልቅ እንደምትሰጥም አየኋት።'),
  ('19334caf-af9a-5db8-a9cd-abf285447835', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 6, 6, 'ተራሮች በተራሮች ላይ ሲሰቀሉ፥ ኮረብታዎችም በኮረብታዎች ላይ ሲሰጥሙ፥ ረዣዥም ዛፎችም ከግንዶቻቸው እየተነቀሉ ሲወድቁ፥ በጥልቅ ወንዝም ሲሰጥሙ አየኋቸው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('efe8d8bf-4981-58c8-a8e1-f7d89eb01798', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 7, 7, 'ከእርሱም የተነሣ በአንደበቴ ነገር ተነገረ፥ “ምድር ጠፋች” ብዬ እጮህ ጀመር።'),
  ('fd05eb17-5efc-54bf-a1e5-16dbe2f16c2f', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 8, 8, 'አያቴ መላልኤልም እኔ በእርሱ ዘንድ ተኝቼ ሳለሁ አስነሣኝ፤ “ልጄ፥ እንደዚህ ለምን ትጮሃለህ? እንደዚህስ ለምን ታለቅሳለህ?” አለኝ።'),
  ('1e296a7e-ec75-5266-a6ae-ede00e8f4e54', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 9, 9, 'እኔም ያየሁትን ራእይ ሁሉ ነገርሁት።'),
  ('25691790-6e15-5c66-a70f-3221a88f3ba9', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 10, 10, 'እርሱም አለኝ- “ልጄ፥ በአእምሮ የጸናህ እንደ መሆንህ አየህ፥ በምድር የተሰወረውን ሁሉ ኀጢአት በሕልም ማየትህ በረታ፤ ምድርም በጥልቁ ትሰጥም ዘንድ አላት፥ ታላቅ ጥፋትንም ትጠፋለች።'),
  ('26195a31-17b5-5b34-a768-674298b464a4', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 11, 11, 'አሁንም ልጄ፥ አንተ የታመንህ ነህና በምድር ላይ ቅሬት እንዲተርፍ፥ ምድርንም እንዳያጠፋት ተነሥተህ የክብር ባለቤት ጌታን ለምነው።'),
  ('a8620a5c-bacb-52a1-ae58-efa94c83a24d', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 12, 12, 'ልጄ፥ ይህ ሁሉ ከሰማይ ወርዶ በምድር ይሆናል፥ በምድርም ላይ ጽኑዕ ጥፋት ይሆናል።”'),
  ('d9c6606c-d685-58bf-a1b1-e1a35b24459e', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 13, 13, 'ከዚህም በኋላ ተነሥቼ ጸለይሁ፥ ማለድሁ፤ ለመንሁም፥ ጸሎቴንም ለልጅ ልጅ ዘመን ሊሆን ጻፍሁት።'),
  ('3e72ddc8-df09-5620-a128-d496e4a97b06', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 14, 14, 'ልጄ ማቱሳላ! ሁሉን አሳየሁህ፤ አንገቴን ደፍቼ በወጣሁ ጌዜ ሰማይን አየሁት፥ ፀሐይንም በምሥራቅ ሲወጣ አየሁ።'),
  ('a9254214-c3c3-5a44-a17b-10064ea37f64', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 15, 15, 'ጨረቃም በምዕራብ ሲገባ አየሁ፤ የጥቂቶችን ከዋክብትና የምድርን ሁሉ ማነስ አየሁ፤ ሁሉንም ዐወቅሁ፥ በመጀመሪያም የፍርድ ባለቤት ጌታን አመሰገንሁት።'),
  ('1e6cfb86-cdaa-53ae-a6a8-ef0b65cb643d', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 16, 16, 'ከምሥራቅ መስኮትም ፀሐይን አውጥትWaልና ምስጋና አቀረብሁለት፤ ፀሐይም ወጥቶ በሰማይ ላይ አበራ፥ ተነሥቶም በታየችለት ጎዳና ይሄዳል።'),
  ('c40114d3-6ed5-5e50-a3a0-07d06b38ae92', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 17, 17, 'በእውነትም እጆቼን ከፍ ከፍ አደረግሁ፥ ቅዱሱንና ገናናውንም አመሰገንሁት፤'),
  ('d76c3b5c-c5f0-5e4a-aa8b-1ff67bc258bf', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 18, 18, 'አምላክ ይናገሩበት ዘንድ ለሰው ልጆች በፈጠረው በአፌ እስትንፋስና በሥጋዊ አንደበቴ ተናገርሁ፥ ይናገሩበትም ዘንድ እስትንፋስን፥ አንደበትንና አፍን ሰጣቸው።'),
  ('5db1fcca-4388-537e-a1da-37fa69cee294', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 19, 19, 'ጌታ ሆይ፥ አንተ ቡሩክ ነህ፤ ንጉሥ፥ ገናና፥ ኀያል፥ በገናናነትህም የሰማይ ፍጥረት ሁሉ ጌታ ነህ፥ የነገሥታት ንጉሥና የዓለሙ ሁሉ አምላክ ነህ።'),
  ('f6837a06-8c3a-533b-a6e1-e6bb22078822', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 20, 20, 'አገዛዝህና መንግሥትህ፥ ገናናነትህም ለዘለዓለም ይኖራል፤ ሥልጣንህም ለልጅ ልጅ ሁሉ ነው።'),
  ('442e48eb-b1c0-58af-a73f-ba738fe4c55c', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 21, 21, 'ሰማዮችም ሁሉ ለዘለዓለሙ መኖሪያህ ናቸው፤ ምድርም ሁላ ለዘለዓለም የእግሮችህ መረገጫ ናት።'),
  ('d31c506d-6d6c-563b-adb6-3ac2b0e7e511', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 22, 22, 'አንተ ሁሉን ፈጥረሃልና፥ አንተም ሁሉን ትገዛለህና አንዱ ስንኳ ሥራ አይሳንህም፤ አንዲት ጥበብም አትሰወርህም፤ ዙፋንህም ከአኗኗርዋ አትለወጥም፥ አንተም ከባሕርይህ አትለወጥም።'),
  ('389d7836-4cb5-5f0c-af46-652712c0a596', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 23, 23, 'አንተም ሁሉን ታውቃለህ፥ ታያለህም፥ ትሰማለህም፥ ሁሉንም ታያለህና ከአንተ የሚሰወር የለም።'),
  ('18260adf-8c54-54ac-a59b-89d4d7ca558e', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 24, 24, 'አሁንም የሰማያትህ መላእክት'),
  ('1f4e3e18-75a7-5e94-a184-29b14b5f7e6c', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 25, 25, 'አሁንም አምላክ፥ ጌታና ገናና ንጉሥ ሆይ፥ በምድር የልጅ ልጅ ታስቀርልኝ ዘንድ ልመናዬን እንድትሰማኝ ፈጽሜ እለምናለሁ።'),
  ('7b50a1e4-1382-5d88-a996-407ec6bd93cc', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 26, 26, 'ሰውን ሁሉ አታጥፋ፥ ምድርንም ባዶዋን አታስቀራት፥ ለዘለዓለምም ጥፋት አይሁን።'),
  ('4763bd59-de2e-5e6c-a806-9f379159b010', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 27, 27, 'አሁንም ጌታዬ ሆይ፥ አንተን ያሳዘነችህ ሰውነትን ከምድር አጥፋ።'),
  ('95e7b7ca-762b-5829-aa8d-f652c94f0a3e', '8be9daf7-4e84-5e90-a8c4-48f74f94ccf9', '2f90bcd2-d7a7-5628-a959-64026a0b4d68', 28, 28, 'የጽድቅና የቅንነት ሰውነትንም ለዘለዓለም ዘር ተክል አጽና። አቤቱ ከእኔ ከባሪያህም ልመና ፊትህን አትመልስ።'),
  ('faeeef8a-bae6-5dbe-a434-ccaaa9e9477d', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 1, 1, 'ከዚህ በኋላም ሌላ ሕልምን አየሁ፥ ልጄ፥ ሁሉን አሳየሁህ።'),
  ('9ff7c4c7-29fb-5298-ac4a-30302c0f382d', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 2, 2, 'ሄኖክም ለልጁ ማቱሳላ መለሰለት፥ እንዲህም አለ- “ልጄ፥ ነገሬን ስማኝ እልሃለሁ፤'),
  ('58897326-1e60-5e7f-a2d2-fa6aaf676f71', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 3, 3, 'የእኔን የአባትህን ሕልም ለመስማት ጆሮህን አዘንብል፥ እናትህ እድናንም ሳላገባት በመኝታዬ ራእይ አየሁ።'),
  ('aa0963d1-677f-5c28-a149-fa3de9be21ac', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 4, 4, 'እነሆ፥ ላም ከምድር ወጣ፥ ያም ላም ነጭ ሆነ፤ ከእርሱም በኋላ አንዲት ሴት ጥጃ ወጣች።'),
  ('be2f7226-70bb-5f2d-aaf2-9a2a5dce6e2e', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 5, 5, 'ከእርስዋም ሁለት ጥጆች ወጡ፤ ከሁለቱም አንዱ ጥቁር ሆነ፥ አንዱም ቀይ ሆነ፤ ያም ጥቁሩ ጥጃ ያን ቀይ ጥጃ ወጋው፥ በምድርም ተከታተለው።'),
  ('ff187591-569c-54eb-ab02-34b1e8388e44', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 6, 6, 'ከዚያም ጊዜ ጀምሮ ያን ቀይ ጥጃ ማየት አልተቻለኝም፥ ያም ጥቁሩ ጥጃ አደገ።'),
  ('db1ec243-17f6-54ed-ae47-e5603dcbbb7d', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 7, 7, 'ከእርሱም ጋር ያቺ ሴት ጥጃ መጣች። እርሱን መስለው ከእርሱ የሚወጡ ብዙ ላሞችንም አየሁ፥ እርሱንም ይከተላሉ።'),
  ('dd765873-5438-59f3-aa5a-c4885c20eac3', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 8, 8, 'ያችም መጀመሪያዋ ሴቲቱ ጊደር ከዚያ ከመጀመሪያው ላም ፊት ወጣች።'),
  ('59c8469f-423a-5c45-a8ad-a66c7ece5e2c', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 9, 9, 'ያንም ቀይ ጥጃ ፈለገችው፥ አላገኘችውምም፥ ያንጊዜም ታላቅ ጩኸትን ጮኸችና ፈለገችው።'),
  ('0f9c4ca9-35e1-56a0-a6d7-d892b978bd07', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 10, 10, 'ያም መጀመሪያው ላም ወደ እርሷ እስኪመጣ ድረስ አየሁ፥ ዝምም አሰኛት፥ ከዚያችም ጊዜ በኋላ አልጮኸችም።'),
  ('7ed62819-1c45-57dd-a9c4-14a6214bca42', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 11, 11, 'ከዚህም በኋላ ሌላ ነጭ ላምን ወለደች፥ ከእርሱም ቀጥሎ ብዙ ላሞችንና ጥቋቁር ጊደሮችን ወለደች።'),
  ('dd738890-7082-57d4-a999-845b2990e635', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 12, 12, 'በመኝታዬም ነጭ በሬን አየሁ፥ እንደዚህም አደገ፥ ታላቅ ነጭ በሬም ሆነ፥ ከእርሱም ብዙ ነጫጭ ላሞች ተወለዱ፥ በመልክም ይመስሉታል።'),
  ('98e6d449-f027-5e22-a660-a3e2287667c2', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 13, 13, 'ብዙ ነጫጭና የሚመስሏቸውን ላሞችንም ይወልዱ ጀመር፥ አንዱም ሌላውን ተከተለው።'),
  ('0727a682-518c-58e2-ac50-8dd946c374b8', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 14, 14, 'ዳግመኛም ተኝቼ በዐይኖቼ አየሁ፥ ወደ ላይም ሰማይን ተመለከትሁ።'),
  ('c157ffae-bb47-5c5d-a328-8068b4e3ea7e', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 15, 15, 'እነሆ፥ ከሰማይ አንድ ኮከብ ወደቀ፤ ከፍ ከፍም ይላል፥ ይበላልም፥ በእነዚያም ላሞች መካከል ይሰማራል።'),
  ('6bde73ae-db78-534b-a2e1-3fd3f8e0cc83', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 16, 16, 'ከዚያም በኋላ ታላላቆችንና ጥቋቁር ላሞችን አየሁ፥ እነሆ፥ ሁሉም መመሰጊያቸውንና መሰምሪያቸውን፥ ጥጆቻቸውንም ለወጡ፤ አያንዳንዳቸውም ከሌላው ጋር ይጮሁ ጀመሩ፥'),
  ('5dbf9f43-8c04-5f08-a963-7dfad3d13041', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 17, 17, 'ዳግመኛም ራእይ አየሁ፥ ሰማይንም ተመለከትሁ።'),
  ('d294f3a6-8c78-59c5-aa59-516546133443', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 18, 18, 'እነሆ፥ ብዙ ከዋክብትንም አየሁ፥ ከሰማይም ወደዚያ ወደ መጀመሪያው ኮከብ ወርደው ወደቁ፥ በእነዚያም ጥጆች መካከል ላሞች ሆኑ።'),
  ('d9728525-8bdb-5ff9-a6ad-52436305134c', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 19, 19, 'ከእነርሱም ጋር በመካከላቸው የሚሰማሩ ሆኑ፥ እነርሱንም ፈጽሜ አየኋቸው።'),
  ('0eef47b6-d82b-5d47-a1ad-0ef0f67197b6', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 20, 20, 'እነሆ፥ ሁሉም እንደ ፈረሶች ኀፍረታቸውን አውጥተው በላሞች ጊደሮች ላይ ይንጠላጠሉ ጀመሩ።'),
  ('45afe7e8-c8a1-555f-a315-5dee7ff8e581', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 21, 21, 'ሁሉም ፀንሰው ዝሆኖችንና ግመሎችን፥ አህዮችንም ወለዱ፤ ላሞችም ሁሉ እነርሱን ፈሩአቸው፥ ከእነርሱም የተነሣ ደነገጡ።'),
  ('b8dbf7a3-9c50-5a0c-a82d-44458259d121', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 22, 22, 'በጥርሳቸውም እየበታተኑ ይጥሏቸውና ይውጧቸው፥ በቀንዶቻቸውም ይወጓቸው ጀመሩ፤ ከዚያም በኋላ እነዚያን ላሞች ይበሏቸው ጀመሩ።'),
  ('3043715a-3504-59f0-a2a8-5af02307fd7f', 'c5a175a5-215d-51c6-aa2d-58d9064e73e0', 'f07eb99d-c0d5-5db4-affc-21e8f67fa88a', 23, 23, 'እነሆም፥ የምድር ልጆች ሁሉ ከእነርሱ የተነሣ ይንቀጠቀጡና ይነዋወጡ፥ ከእነርሱም ይሸሹ ጀመሩ።'),
  ('af364952-9e5f-5148-ad80-f032b79254fe', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 1, 1, 'ዳግመኛም፥ አንዱ ሌላውን ሲወጋው፥ አንዱም ሌላውን ሲውጠው አየሁ።'),
  ('ecb3881f-b729-5db1-a34f-6d541f5c2b45', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 2, 2, 'ምድርም ትጮህ ጀመረች፥ ዳግመኛም ዐይኖቼን ወደ ሰማይ አቅንቼ በራእይ አየሁ።'),
  ('6b2e8425-5d2a-5f69-aba2-13789b556134', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 3, 3, 'እነሆም፥ የሸበተ ሰውን የመሰሉ ከሰማይ ወጡ፥ አንዱም ከዚያ ቦታ ወጣ፤ ሦስቱም ከእርሱ ጋር ወጡ።'),
  ('57f40969-2f66-53a5-a0c5-69df9f5d3613', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 4, 4, 'ኋላም ከእርሱ ጋር የወጡ እነዚያ ሦስቱ እጄን ያዙኝ፥ በምድር ካሉ ሰዎችም ለይተው አነሡኝ።'),
  ('42d1d4e3-85d9-5fd3-a9d0-6488c768a772', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 5, 5, 'በረጅም ተራራ ላይም ከፍ አድርገው ከምድር የራቀች ግንብን አሳዩኝ፥ ኮረብታውም ሁሉ ከእርሱ ያነሰ ሆነ።'),
  ('209ef65d-d637-5ea1-a905-26bfb720ff54', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 6, 6, 'እንዲህም አሉኝ- “በእነዚያ ዝሆኖችና ግመሎች ላይ፥ በአህዮችም ላይ፥ በከዋክብትም ላይ፥ በላሞቹም ሁሉ ላይ፥ የሚመጣውን ሁሉ እስክታይ ድረስ በዚህ ተቀመጥ።”'),
  ('e4427242-2cc2-528f-ad9f-0427af5456b0', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 7, 7, 'ቀድመው ከወጡት ከእነዚያ ከአራቱ አንዱን አየሁት፥ ከሰማይም የወደቀ ያን መጀመሪያውን ኮከብ ያዘው።'),
  ('d1e61193-ed14-5512-a9f8-c21e804d4e6c', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 8, 8, 'እጅና እግሩንም አስሮ በጥልቁ ጣለው፥ ያም ጕድጓድ ጠባብና ጥልቅ፥ ጭንቅና ጨለማም ነው።'),
  ('df89688b-82c0-5338-a32e-8cd162b9c69b', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 9, 9, 'ከእነዚያም አንዱ ሰይፉን መዝዞ ለእነዚያ ዝሆኖች፥ ለእነዚያም ግመሎችና አህዮች ሰጣቸው።'),
  ('037ebc6e-6d2f-5b65-a099-4d532fa65348', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 10, 10, 'አንዱም ሌላውን ይወጋው ጀመረ፥ ምድርም ሁላ በእነርሱ ላይ ተነዋወጠች።'),
  ('384a236c-fd0d-515d-aacb-da9c267a89c8', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 11, 11, 'በራእይም ባየሁ ጊዜ ከእነዚያ ከወጡት ከአራቱ አንዱ እነሆ፥ ከሰማይ መረቡን ጣለ።'),
  ('750502be-a134-5176-ad00-5ed508a994b6', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 12, 12, 'ኀፍረታቸው እንደ ፈረሶች ኀፍረት የሆነ ታላላቅ ከዋክብትንም ሁሉ ሰብስቦ ያዘ።'),
  ('5810a2ff-94a1-5c4a-a9df-606fc315f948', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 13, 13, 'ሁሉንም እጃቸውንና እግራቸውን አስሮ በምድር ጕድጓድ ጣላቸው።'),
  ('c1712866-103d-5aaf-a326-c8b25a6583ec', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 14, 14, 'ከእነዚያም ከአራቱ አንዱ ወደ ነጩ ላም ሄደ፥ እየራደም ምሥጢርን አስተማረው።'),
  ('7d1fde7f-2862-574f-aae3-41f5679ed38d', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 15, 15, 'ያ ላምም ተወለደ፤ ሰውም ሆነ፥ መርከብንም ሠርቶ በእርሷ ተቀመጠ።'),
  ('5d610294-cd12-59dd-abda-1a067c3dd122', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 16, 16, 'ሦስቱ ላሞችም በዚያች መርከብ ከእርሱ ጋር ተቀመጡ፥ በእነርሱም ላይ መርከቡ ተዘጋ።'),
  ('ab80f3bc-2a25-5fbd-a9d7-719e2eed5689', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 17, 17, 'ዳግመኛም ዐይኖቼን ወደ ሰማይ አቅንቼ ከፍ ያለ ጠፈርን አየሁ፥ በእርሱም ሰባት የውኃ ሻሻቴዎች አሉ፤ እነዚህም ሻሻቴዎች በአንድ ቦታ ብዙ ውኃን ያፈስሳሉ።'),
  ('bdf4b6bf-cd49-5485-aae3-896aefea6690', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 18, 18, 'ዳግመኛም አየሁ፥ እነሆም፥ በምድር ላይ በዚያ በታላቁ ቦታ ምንጮች ተከፈቱ።'),
  ('9968daff-6a3b-5d26-a5fc-8a3caabce486', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 19, 19, 'ያም ውኃ ይፈላና በምድር ላይ ይነሣ ጀመር፥ ምድሩም ሁሉ በውኃ እስኪሸፈን ድረስ ያን ቦታ አያሳየውም ነበር።'),
  ('0779e35a-37f7-5082-ac4a-2379f6148a2f', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 20, 20, 'በሁሉም ላይ ውኃው በዛ፤ ጨለማና ጉምም ሆነ፤ የዚያንም ውኃ ከፍታውን አየሁ፥ ውኃውም በዚያ ቦታ ላይ ከፍ ከፍ አለ።'),
  ('38c72310-fa98-5c3d-a14f-36b4600b2e4b', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 21, 21, 'በቦታውም ላይ ውኃውን ያፈስስ ነበር፥ በምድር ላይም ጸና።'),
  ('8e2eec8a-5f61-5c03-a137-e44b02ad48d4', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 22, 22, 'በዚያም ቦታ ላሞች ሁሉ በውኃው ሲሰጥሙ፥ ሲዋጡና ሲጠፉም እስከማያቸው ድረስ ተሰበሰቡ።'),
  ('deb630df-edfe-5368-a069-5551c3a9ff6e', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 23, 23, 'ያም መርከብ በውኃው ላይ ይንሳፈፍ ነበር፥ ላሞችና ዝሆኖች፥ አህዮችና ግመሎች፥ ከብቶችም ሁሉ በምድር ተሰጠሙ።'),
  ('d98c2acc-478e-5a49-aaa6-6f5e3d44a329', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 24, 24, 'እኔም እነርሱን ማየት አልተቻለኝም፤ እነርሱም መውጣት ተሳናቸው፥ በጥልቁም ባሕር ተሰጥመው ጠፉ።'),
  ('e2985db4-2540-5cb8-afbf-32b049149b75', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 25, 25, 'ዳግመኛም ከዚህ ከታላቁ ጠፈር እነዚህ ሻሻቴዎች እስኪጠፉ ድረስ በራእይ አየሁ፥ የምድሩም ምንጭ ተደፈነ።'),
  ('1e76df2d-034b-5b2d-ad9b-8bdd02883886', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 26, 26, 'ሌሎች ጕድጓዶችም ተከፈቱ፥ ምድር እስኪገለጥ ድረስም ውኃው ወደ እነርሱ ይወርድ ጀመር።'),
  ('9ef7cad7-b08c-56e6-a649-4e048ab1b070', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 27, 27, 'ያ መርከብም በምድር ላይ ተቀመጠ። ጨለማዪቱ ራቀች፥ ብርሃንም ሆነ።'),
  ('64d9089d-7376-5b71-acc3-d8d1418a5ece', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 28, 28, 'ሰው የሆነ ያም ነጭ ላም ከመርከቡ ወጣ፥ ሦስቱም ላሞች ከእርሱ ጋር ወጡ።'),
  ('c7a0854c-210a-5287-ac17-dba529bd5575', '1d79106e-f4b9-53a0-ad50-b8bdc8a0806d', 'b1b9543d-a04c-502a-af58-e3cc156d7994', 29, 29, 'ከእነዚህም ከሦስቱ ላሞች አንዱ ነጭ ላም ያን ላም ይመስለዋል፥ ከእነርሱም አንዱ እንደ ደም ቀይ ነው፤ አንዱም ጥቁር ነው፥ ያም ነጩ ላም ከእነርሱ ተለይቶ ሞተ።'),
  ('cb0d0d06-1b9a-5caa-a970-71eed281596d', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 1, 1, 'የምድረ በዳ አውሬዎችንና ወፎችንም ይወልዱ ጀመሩ- ከእነርሱም የአሕዛብ ሁሉ ዓይነት ተገኘ።'),
  ('19d55161-f9a2-538f-af72-2a7914467922', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 2, 2, 'አንበሶችና ነብሮች፥ ዥቦችና ውሾች፥ አውጮችና የዱር እሪያ፥ ቀበሮዎችና ሽኮኮዎች፥'),
  ('f175bf18-95da-59fc-a8e5-8ce1f32d918d', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 3, 3, 'አነርና ዘማች አሞራ፥ ጥንብ አሞራና አንጭት አሞራ፥ ጉሬዛና ቍራዎች።'),
  ('dbea9cd6-b1fc-5edd-ace5-f14277cff13e', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 4, 4, 'በመካከላቸውም ነጭ ላም ተወለደ፤ አንዱም ከሌላው ጋር እርስ በርሳቸው ይነካከሱ ጀመሩ።'),
  ('790d3ed8-a0bd-505a-a7f0-f737fe31d87d', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 5, 5, 'በመካከላቸው የተወለደው ያ ነጭ ላምም የሜዳ አህያን፥ ከእርሱም ጋር ነጭ ላምን ወለደ።'),
  ('056877c9-3500-5b01-a855-45e699ba04cf', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 6, 6, 'የሜዳ አህዮችም በዙ፤ ከእርሱም የተወለደው ያ ላም- ጥቁር የዱር እሪያንና ነጭ በግን ወለደ።'),
  ('d8d422db-88c1-513f-a5f5-deb4249f81d3', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 7, 7, 'ያም የዱር እሪያ ብዙ እሪያዎችን ወለደ፤ በጉም ዐሥራ ሁለት በጎችን ወለደ።'),
  ('3b4585ad-82bd-56a4-a35d-425b1cbbd1fc', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 8, 8, 'ዐሥራ ሁለቱ በጎችም ባደጉ ጊዜ ከእነርሱ አንዱን ለሜዳ አህዮች አሳልፈው ሰጡት።'),
  ('38daf41a-ef74-5a82-a05b-81fa3a97a865', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 9, 9, 'እነዚያ የሜዳ አህዮችም ያን በግ ለዥቦች ሁለተኛ አሳልፈው ሰጡት። በጉም በዥቦች መካከል አደገ።'),
  ('19271e41-bf79-510a-a64e-564b74d61d66', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 10, 10, 'ጌታም ዐሥራ አንዱን በጎች ከእርሱ ጋር ይኖሩ ዘንድ፥ ከእርሱም ጋር በዥቦች መካከል ይሰማሩ ዘንድ አመጣቸው።'),
  ('df1d75c9-a733-55bd-acc2-c31dbbc4f180', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 11, 11, 'እነዚህም በዙ፤ ብዙ የበጎች መንጋዎችንም ሆኑ፤ ዥቦችም ልጆቻቸውን እስኪጨርሱባቸው ድረስ ያስፈሯቸውና ያስጨንቋቸው ጀመሩ።'),
  ('2ae39342-9e18-579d-ad0f-1dd9c6546b48', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 12, 12, 'ልጆቻቸውንም በብዙ ውኃ ፈሳሽ ጣሏቸው፤ እነዚያም በጎች ስለ ልጆቻቸው ይጮሁ፥ ወደ ጌታቸውም ይከሱ ጀመሩ።'),
  ('fe843179-1c6e-5cd5-a652-64662cc85077', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 13, 13, 'ከዥቦች የዳነውም በግ ሸሽቶ ወደ ሜዳ አህዮች ሄደ።'),
  ('3f0dee85-a301-5cd7-ac62-fd4fd25d7820', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 14, 14, 'የበጎች ጌታም የበጎችን ድምፅ ሰምቶ ከፍ ካለው ከጽርሐ አርያም እስኪወርድ ድረስ በጎችን እየጮሁ ሲያለቅሱ፥ በፍጹም ኀይላቸውም ጌታቸውን ሲለምኑት አየኋቸው።'),
  ('8a33620a-36e2-54fa-af88-d1ccb0b58f5e', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 15, 15, 'ወደ እነርሱም መጥቶ አያቸው፤ ከዥቦች ያመለጠውን ያን በግ ጠራው፤ በጎችንም እንዳይነኳቸው ያዳኝባቸው ዘንድ ስለ ዥቦች ነገረው።'),
  ('dd7b8f4f-b0b9-5141-a5dd-5729e21483f2', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 16, 16, 'በጉም በጌታ ቃል ወደ ዥቦች ሄደ፤ ሌላው በግም ያን በግ ተገናኘው፤ ከእርሱም ጋር ሄደ።'),
  ('5ff0a847-17af-59df-ae5e-ce20bfb11bcb', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 17, 17, 'ሁለቱም በአንድነት ወደ ዥቦቹ ማኅበር ገቡ፤ ተናገሯቸውም።'),
  ('26fe70e4-f599-554c-a9d5-edc3f90ce608', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 18, 18, 'እንግዲህም ወዲህ በጎቹን እንዳይነኳቸው አዳኙባቸው።'),
  ('591f47bd-1906-541d-a02a-55e7530a1e04', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 19, 19, 'ከዚህም በኋላ በፍጹም ኀይላቸው እጅግ እንደ ጸኑባቸው ዥቦችን አየኋቸው።'),
  ('3ba2b3f4-51e1-5d3e-a619-cf1a40fd7a57', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 20, 20, 'በጎችም ጮሁ፤ ጌታቸውም ወደ በጎች መጥቶ ዥቦቹን ይመታቸው ጀመረ።'),
  ('60865971-c2a5-5063-a3a4-cbfca8ab2dd0', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 21, 21, 'ዥቦችም ይጮሁ ጀመሩ፤ በጎቹም ዝም አሉ፤ ከዚያም ጊዜ ጀምሮ አልጮሁም፤ በጎችንም ከዥቦች ተለይተው እስኪወጡ ድረስ አየኋቸው።'),
  ('2e90bcce-74f8-5139-ac26-c05a2c10de8e', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 22, 22, 'የዥቦችም ዐይኖቻቸው ተጋረዱ። እነዚያም ዥቦች በፍጹም ኀይላቸው በጎችን እየተከተሉ ወጡ።'),
  ('0cabee45-3a30-581d-a637-a38c82a1c1be', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 23, 23, 'የበጎችም ጌታ እየመራቸው ከእነርሱ ጋር ሄደ፤ በጎችም ሁሉ እርሱን ተከተሉት፤ ፊቱም የበራና የከበረ ነው፤ መልኩም የሚያስፈራ ነው።'),
  ('b0ac11b5-a8e5-567c-af3f-20285914dde1', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 24, 24, 'ዥቦች ግን በአንዲት የውኃ መጠራቀሚያ እስኪገናኙአቸው ድረስ በጎቹን ይከተሏቸው ጀመሩ።'),
  ('9bd4ca22-045c-5fc1-aaae-99fa39c6fc88', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 25, 25, 'ያም የውኃ መጠራቀሚያ ተከፈለ፤ ውኃውም በዚህና በዚያ በፊታቸው ቆመ፤ የበጎቹም ጌታ ይመራቸው ነበር፤ በመካከላቸውና በዥቦቹም መካከል ቆመ።'),
  ('18e728d3-28ac-5e98-a4e0-fa0a79e63db6', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 26, 26, 'ዥቦቹም በጎቹን ገና አላዩአቸውም ነበር፤ በውኃው ማጠራቀሚያ መካከልም ሄዱ።'),
  ('608cc04d-e147-52cf-ad85-9b6d5ee65fe6', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 27, 27, 'ዥቦችም በጎችን ተከተሏቸው፤ ዥቦቹም በውኃው መጠራቀሚያ ላይ ተከትለዋቸው ሮጡ።'),
  ('ada91078-4cd5-5eb9-ad05-0306dbe8d96c', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 28, 28, 'የበጎቹንም ጌታ ባዩት ጊዜ ከፊቱ ይሸሹ ዘንድ ተመለሱ።'),
  ('4d4beb49-5303-5f20-a77f-40e2342dd0b0', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 29, 29, 'ያም የውኃው መጠራቀሚያ ተሰበሰበ፤ ፈጥኖም እንደ ቀድሞ ፍጥረቱ ሆነ፤ ውኃውም- እኒህን ዥቦች እስኪአሰጥማቸው ድረስ መልቶ ከፍ ከፍ አለ።'),
  ('0678d7d6-9fbb-5a4a-a0a5-c15de55140bc', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 30, 30, 'በጎቹንም የተከተሏቸው ዥቦች ሁሉ እስኪጠፉና እስኪሰጥሙ ድረስ አየሁ።'),
  ('3d665061-d445-522e-a098-c2aff22b5416', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 31, 31, 'በጎች ግን ከውኃው ዐለፉ፤ ሣርና ውኃ ወደሌለበትም ምድረ በዳ ወጡ።'),
  ('5bf6c69f-cee3-5842-a015-415c07e75b05', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 32, 32, 'ዐይኖቻቸውንም ገልጠው ያዩ ጀመሩ፤ ጌታቸውም ሲጠብቃቸውና ሣርና ውኃ ሲሰጣቸው አየሁ።'),
  ('69632773-8cac-5ae2-a5a8-5a60a2196b42', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 33, 33, 'ያም በግ በፊት በፊት እየሄደ ይመራቸው ነበር፤ በጉም ወደ ረዥሙ ዐለት ራስ ላይ ወጣ።'),
  ('56219315-4e15-5a7c-afd9-9af7589e557c', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 34, 34, 'የበጎቹም ጌታ ወደ እነርሱ ላከው፤ ከዚህ በላይ በፊታቸው የቆመውን የበጎችን ጌታ አየሁት።'),
  ('4707a39f-b2a4-51e5-a632-164038ff6a16', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 35, 35, 'መልኩም ያማረ የሚያስፈራና፥ ኀይለኛ ነው፤ በጎቹም ሁሉ እርሱን አይተው ከፊቱ የተነሣ ፈሩ።'),
  ('bcdaa5b0-31a4-5a8d-a3e7-e6d6c3f4a1f4', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 36, 36, 'እነዚያም ሁሉ ከእርሱ የተነሣ ይፈሩና ይንቀጠቀጡ ነበር፤ በመካከላቸውም ከነበረው ከሁለተኛው በግ ጋር ያለ ያን በግ ተከትለው ጮሁ።'),
  ('928617be-6067-5199-a68c-2f055bd85ad9', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 37, 37, 'በጌታችን ፊት መቆም እርሱንም ማየት አይቻለንም አሉ፤ የሚመራቸውም ያ በግ ተመልሶ ወደ ዐለቱ ራስ ወጣ።'),
  ('765c950e-a756-5ab8-a3de-a717b0559b2e', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 38, 38, 'በጎቹም ዐይኖቻቸውን ይጋረዱ፥ ካሳያቸውም መንገድ ይስቱ ጀመሩ።'),
  ('81036c3d-86d6-5669-a087-67ff82d50084', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 39, 39, 'ያም በግ አላወቀም ነበር፤ የበጎችም ጌታ በእነርሱ ላይ ታላቅ ቍጣን ተቈጣባቸው።'),
  ('18fa5439-2f7f-5184-a243-337a69ba8aa4', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 40, 40, 'በጉም ዐውቆ ከዐለቱ ራስ ወረደ።'),
  ('f74918ba-ba57-57f0-abed-f318a0e7e2dd', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 41, 41, 'ወደ በጎችም መጣ፤ ዐይኖቻቸው የተጋረዱባቸውንና ከመንገዱ የወጡትን አብዛኛዎቹን አገኘ።'),
  ('09744b1c-2f80-5e3f-abb7-38484a52b45b', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 42, 42, 'ባዩትም ጊዜ ፈሩ፤ ከፊቱም የተነሣ ተንቀጠቀጡ፤ ወደ ቦታቸውም ይመለሱ ዘንድ ወደዱ።'),
  ('0c8cc0a4-621b-5636-af2f-42bd9d398696', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 43, 43, 'ያም በግ ሌሎች በጎችን ከእርሱ ጋር ወሰደ፤ ወደ እነዚያ ወደ በደሉ በጎችም ገባ።'),
  ('0b5b3486-0606-579b-a55e-95c0c21d5785', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 44, 44, 'ከዚህም በኋላ ይገድላቸው ጀመረ፤ በጎችም ከፊቱ የተነሣ ፈሩ፤ በጉም የበደሉ እነዚያን በጎች መለሳቸው፤ ወደ ቦታዎቻቸውም ተመለሱ።'),
  ('5823e8a0-6f91-5517-a8de-668a26d8a75b', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 45, 45, 'በዚያም በጉ ሰው እስኪሆን ድረስ፥ ለበጎቹም ጌታ ቤትን እስኪሠራ ድረስ፥ በጎቹንም ሁሉ በዚያ ቤት እስኪያቆማቸው ድረስ ራእይን አየሁ።'),
  ('8ee53904-70e7-56ae-add4-43d1832732d8', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 46, 46, 'በጎችንም የመራቸውን ያን በግ የተገናኘው በግ እስኪተኛ ድረስ አየሁ።'),
  ('47f7e1f7-a965-5ac7-aeb5-4c1b60e68934', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 47, 47, 'ታላላቁ በጎችም ሁሉ እስኪጠፉ ድረስ አየሁ፤ በእነርሱም ፋንታ ታናናሾቹ ተነሥተው ወደ መንጋው ገቡ።'),
  ('1fc8fe3e-02fc-5376-a8a9-548d40e7d423', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 48, 48, 'ወደ ውኃው ፈሳሽም ቀረቡ፤ ይመራቸው የነበረው፥ ሰው የሆነው ያም በግ ከእነርሱ ተለይቶ ተኛ።'),
  ('fbb9a45f-0911-56bf-ad6c-8b4589bee919', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 49, 49, 'በጎችም ሁሉ ፈለጉት፤ በእርሱም ላይ ታላቅ ጩኸትን ጮሁ፤ ለዚያም በግ ከሚጮሁት ጩኸት ዝም እስኪሉ ድረስ አየሁ።'),
  ('2391e3a7-054c-51a6-a3b3-1af6a096f552', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 50, 50, 'ያንም የውኃ ፈሳሽ አልፈውት ሄዱ፤ ስለ አንቀላፉትም ምትክ የሚመሯቸው በጎች ተተክተው መሯቸው።'),
  ('bf678092-c2b4-589b-a569-0e06bdd9c2d2', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 51, 51, 'በጎችም ወደ አማረ ቦታ፥ ወደ ተወደደችና ወደ ሰባች ምድርም እስኪገቡ ድረስ አየሁ።'),
  ('560b7e39-9ea6-5122-a723-571c92940793', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 52, 52, 'እነዚያም በጎች እስኪጠግቡ ድረስ አየሁ፤ ያም ቤት ባማረች ምድር በመካከላቸው ይኖር ነበር።'),
  ('8d9673ab-84b9-52e8-a455-89cf43240c1e', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 53, 53, 'ሌላ በግ ተነሥቶ እስኪመራቸው ድረስ ዐይኖቻቸው የሚገለጡበትና የሚጋረዱበት ጊዜ ነበረ።'),
  ('2dade035-41cd-54a5-a28a-305485673ef3', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 54, 54, 'ሁሉንም መለሳቸው፤ ዐይኖቻቸውም ተገለጡ።'),
  ('02690b83-798d-5744-a38d-2a0941fa7a52', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 55, 55, 'የበጎች አውራ ሌላ በግ እስኪነሣ ድረስም- እነዚያን በጎች ውሾችና ቀበሮች፥ የዱር እሪያም ይበሏቸው ጀመሩ። የሚመራቸውም አውራ ከእነርሱ አንዱ ነበር።'),
  ('cdba1a7f-30fc-5d9f-ac4e-f276b8fe1dce', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 56, 56, 'ያም አውራ ሁሉን እስኪያጠፋቸው ድረስ እነዚያን ውሾችና ቀበሮች፥ የዱር እሪያውንም ወዲህና ወዲያ ይወጋ ጀመር።'),
  ('5b53003a-63b9-55a4-a3b2-eff28b009c8b', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 57, 57, 'የዚያም በግ ዐይኖቹ ተገለጡ፤ በበጎች መካከል ያለ ክብሩን የተወ ያን አውራም አየው።'),
  ('9dd56344-fff6-520c-a284-49c0cea411a9', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 58, 58, 'እነዚያንም በጎች ይወጋቸውና ይረግጣቸው ጀመረ፤ እርሱም ያለ ደስታ ኖረ።'),
  ('1f8960d9-6b44-52ba-a935-7be0dbaf6794', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 59, 59, 'የበጎችም ጌታ በጉን ወደ ሌላው በግ ላከው፤ ክብሩንም በተወው በዚያ በግ ፋንታ አውራ ይሆንና በጎችን ይመራቸው ዘንድ አስነሣው።'),
  ('c33b6ad7-c56c-58f7-ae47-d4e70186ea2b', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 60, 60, 'ወደ እርሱም ሄዶ ለብቻው አነጋገረው፤ ያንም አውራ አስነሥቶ ለበጎቹ ገዥና መሪ አደረገው።'),
  ('df42644d-2fa4-542d-a291-8ff345290e61', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 61, 61, 'በዚህም ሁሉ እነዚያ ውሾች በጎቹን ያስጨንቋቸው ነበር።'),
  ('3de0fe58-1e64-5924-ab53-6c77c8479520', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 62, 62, 'መጀመሪያው አውራ ያን ኋለኛውን አውራ አሳደደው፤ ያም ኋለኛው አውራ ተነሥቶ ከፊቱ ሸሸ።'),
  ('ec1dcb35-a8ce-52f1-a930-24becf29f088', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 63, 63, 'መጀመሪያውንም አውራ ውሾቹ እስኪያጠፉት ድረስ አየሁ።'),
  ('0eac8a36-4c4c-58c7-a647-e503e93cd3c6', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 64, 64, 'እንዲህም ሆነ- ኋለኛው አውራ ተነሥቶ ታናናሽ በጎችን መራቸው።'),
  ('33ab831e-f01c-587b-a77f-70791cb9c425', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 65, 65, 'ይህም ኋለኛው አውራ ብዙ በጎችን ወልዶ ሞተ።'),
  ('b0bdbe57-0ed8-5977-a244-5d34a58b0e76', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 66, 66, 'ትንሹም በግ በእርሱ ፋንታ አውራ ሆነ፤ ለእነዚያም በጎች ገዥና መሪ ሆነ።'),
  ('d02da833-09b8-5d13-acb6-80d99bdaffdc', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 67, 67, 'እነዚያም በጎች አደጉ፤ በዙም። እነዚያም ውሾችና ቀበሮች፥ የዱር እሪያም ፈሩ፤ ከእርሱም ሸሹ።'),
  ('8eb3516f-c965-5efd-a80b-b99933713486', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 68, 68, 'ያም አውራ አራዊትን ሁሉ ወጋ፤ አራዊትም ዳግመኛ በበጎች መካከል መግባት አልቻሉም። ከእነርሱም ምንም አልነጠቁም።'),
  ('adf043ee-723d-5721-a35b-44cdcc6cf44a', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 69, 69, 'ቤቱም ታላቅና ሰፊ ሆነ፤ ለእነዚያም በጎች በዚያ ቤት ላይ ግንብ ተሠራ። ለበጎችም ጌታ በዚያ ቤት ላይ ረዥምና ታላቅ ግንብ ተሠራ።'),
  ('a07fdc57-a4e6-5d08-abb6-fb8b8d3fcb8b', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 70, 70, 'ያም ቤት ተዋረደ፤ ግንቡ ግን ከፍ ከፍ አለ፤ ረዥምም ሆነ፤ የበጎችም ጌታ በዚያ ግንብ ላይ ቆመ፤ ሙሉ የሆነች ማዕድንም በፊቱ አቀረቡ።'),
  ('7fdb7700-3ad7-5439-a5e9-5c51ba314e6f', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 71, 71, 'ዳግመኛም እነዚያን በጎች እንደ ሳቱና በብዙ ጎዳና እንደሄዱ አየኋቸው፤ ያንም ቤታቸውን ተዉ።'),
  ('12ba88d7-bd36-59a6-a29d-020fef05abf8', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 72, 72, 'የበጎችም ጌታ ከበጎች ውስጥ ጠርቶ ወደ በጎች ላካቸው፤ በጎችም ይገድሏቸው ጀመሩ።'),
  ('f69b4320-4075-5cba-a08c-00821dd32189', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 73, 73, 'ከእነርሱም አንዱ ከሞት አመለጠ፤ አልተገደለምም፤ ፈጥኖም ሄዶ በበጎች ላይ ጮኸ።'),
  ('2c93aae7-6c48-574e-a438-e8e1a15b08ca', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 74, 74, 'ሊገድሉትም ወደዱ፤ የበጎችም ጌታ ከበጎች እጅ አዳነው፤ ወደ እኔም አውጥቶ አኖረው።'),
  ('8df521e5-0ebd-56e9-abb3-20d81592158a', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 75, 75, 'ጩኸውም ያዳኙባቸው ዘንድ ሌሎች ብዙ በጎችን ወደ እነዚያ በጎች ላከ።'),
  ('6f0013ca-b51c-5a58-ae02-e458f4a04ee2', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 76, 76, 'ከእነርሱም የተነሣ የበጎችን ጌታ ቤቱንና ግንቡን ሲተዉ አየሁ፤ ከዚህም ሁሉ ስተው ዐይኖቻቸው ተጋረዱ።'),
  ('51f5c30a-00cc-52b2-abb3-7cabf362f9ea', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 77, 77, 'የበጎችም ጌታ ብዙ ሰልፍን በእነርሱ ላይ እንዳደረገ፥ እነዚያም በጎች ያን ሰልፍ እስኪጠሩት ድረስ አየሁ።'),
  ('52a7e23f-8b91-5c49-af22-35beab68c4ff', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 78, 78, 'ቦታቸውንም አሳልፈው ሰጡ፤ እርሱም በአንበሶችና በነብሮች፥ በዥቦችና በአውጮች፥ በቀበሮችና በአውሬዎች ሁሉ እጅ ጣላቸው፤ እነዚያ የዱር አራዊትም በጎቹን ይነጥቋቸው ጀመሩ።'),
  ('3d8ed2aa-d891-5b43-ac40-ce67e99316ad', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 79, 79, 'እርሱም ቤታቸውንና ግንባቸውን እንደ ተወው አየሁ።'),
  ('2e6d7217-15c1-5a43-afdf-535a7d1a033a', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 80, 80, 'ይነጥቋቸውም ዘንድ በአንበሶች እጅ፥ ይበሏቸውም ዘንድ በአራዊት ሁሉ እጅ ሁሉንም ጣላቸው።'),
  ('c15a448d-3469-5d50-a6be-8cdb8bdfe12f', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 81, 81, 'እኔም በፍጹም ኀይሌ እጮህ፥ የበጎችንም ጌታ እጠራውና ስለ በጎቹም አመለክተው ዘንድ ጀመርሁ፤ በዱር አራዊት ሁሉ ተበልተዋልና።'),
  ('f0273014-b762-539f-a339-220bfb5acb82', '245fd5ce-1f1b-5959-a0e5-ca39d0c7733e', 'e7c0513c-29b7-5b37-a0ad-0504d69d83ba', 82, 82, 'እርሱም እያየ ዝም አለ፤ ደስም አለው፤ እነርሱ ተበልተው ተውጠዋልና፥ ንብረታቸውንም ተነጥቀዋልና፤ መብል እንዲሆኗቸውም በአራዊት ሁሉ እጅ ጣላቸው።'),
  ('0795537d-54fd-5dd9-ae39-a4236fa1a560', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 1, 1, 'ሰባውን እረኞች ጠራ፤ ይጠብቋቸውም ዘንድ እነዚያን በጎች ሰጣቸው።'),
  ('d404b0fd-4e42-590d-a966-a2bcfccb249a', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 2, 2, 'ለእረኞችና ለአገልጋዮቻቸውም እንዲህ አላቸው- “ከእናንተ እያንዳንዱ ሁሉ ከዛሬ ጀምሮ በጎችን ይጠብቋቸው፤ እኔም የማዝዛችሁን ሁሉ አድርጉ።'),
  ('9bbc977c-081e-5c55-a532-49fc4ee8b1b1', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 3, 3, 'እኔም በቍጥር እሰጣችኋለሁ፤ ከእነርሱም የሚጠፋውን እኔ እነግራችኋለሁ፤ እነርሱንም አጥፉ፥” እነዚያንም በጎች ሰጣቸው።'),
  ('02583e52-4639-5393-a013-52c3a16d30c5', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 4, 4, 'ሌላውንም ጠርቶ እንዲህ አለው- “ካዘዝኋቸው ወጥተው ከእነርሱ ውስጥ ያጠፋሉና በእነዚህ በጎች ላይ እረኞች የሚያደርጉትን ሁሉ አስተውል፤ ተመልከትም።'),
  ('77e79ec7-4db5-59c1-afcd-901ebcd02de4', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 5, 5, 'በእኔ ትእዛዝ ምን ያህል እንደሚያጠፉ፥ በራሳቸውም ምን ያህል እንደሚያጠፉ በእረኞች የሚደረገውን ጥጋብና ጥፋት ሁሉ ጻፍ።'),
  ('04516f7c-94ad-53b5-a55e-0126f8b6e61a', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 6, 6, 'የእያንዳንዳቸውንም እረኞች ጥፋት ሁሉ በእነርሱ ላይ ጻፍ። በፊቴም በቍጥር አንብብ፤ ምን ያህልም ያጠፏቸው እንደ ሆነ፥ ምን ያህልም ለጥፋት ይሰጧቸው እንደ ሆነ፥'),
  ('090dfdaf-e6a1-57a3-ae08-539e7f4154fe', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 7, 7, 'የእረኞችን ሥራ ሁሉ እንዳውቅ ይህ ምስክር ይሆነኝ ዘንድ፥'),
  ('63877c15-8e2f-55a4-aa9c-1c657354b68d', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 8, 8, 'ባዘዝኋቸውም ትእዛዝ ጸንተው ይኖሩ፥ ወይም አይኖሩ እንደ ሆነ የሚያደርጉትን አይቼ እሰጣቸው ዘንድ፥'),
  ('3853f37b-974c-5e06-a1b6-d2f7ee21811c', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 9, 9, 'እነርሱ አይወቁ፤ አንተም አታሳያቸው፤ አትዝለፋቸውም፤ ነገር ግን በየጊዜው እያንዳንዳቸው የሚያጠፉትን የእረኞችን ጥፋት ጻፍ። ሁሉንም ወደ እኔ አምጣ።'),
  ('bb43d0ca-ef19-5cf1-a779-ae733e72afae', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 10, 10, 'እነዚያም እረኞች በየጊዜው እስኪጠብቋቸው ድረስ አየሁ፤ ከታዘዙትም ወጥተው ብዙ ይገድሉና ያጠፉ ጀመሩ።'),
  ('33aa7a1e-00e3-5335-abcc-4713a80babf6', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 11, 11, 'እነዚያንም በጎች በአንበሶች እጅ ጣሏቸው፤ አንበሶችና ነብሮችም ከእነዚያ በጎች አብዛኛዎችን በልተው ዋጧቸው።'),
  ('4fb04af4-07c3-59ff-af77-13d6a585b4db', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 12, 12, 'የዱር እሪያዎችም ከእነርሱ ጋር በሉ፤ ያን ግንብም አቃጠሉት፤ ያንም የበጎች ቤት ቈፈሩት።'),
  ('9a74749b-9338-5c5f-af0c-a2e1decac914', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 13, 13, 'እኔም ያ የበጎች ቤት ተቈፍሯልና ስለ ግንቡ እጅግ ብዙ አዘንሁ።'),
  ('b64eebf7-35be-56df-a265-ec790fed638d', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 14, 14, 'ከዚያም በኋላ ወደዚያ ቤት ይገቡ እንደ ሆነ፥ ወይም አይገቡ እንደ ሆነ እነዚያን በጎች ማየት አልተቻለኝም።'),
  ('07675dff-ad63-51cf-a796-f8e54ae337a8', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 15, 15, 'እረኞቻቸውና አገልጋዮቻቸውም በጎቹን ይበሏቸው ዘንድ ለዱር አራዊት ሁሉ አሳልፈው ሰጧቸው።'),
  ('7d6003d2-92d2-58d6-ad84-a3a4fdfbbe8c', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 16, 16, 'ከእነርሱም እያንዳንዱ ሁሉ በየጊዜው በቍጥር ይቀበላል፤ ከእነርሱም እያንዳንዱ የሚያጠፋው ምን ያህል እንደ ሆነ ለሁለተኛው በመጽሐፍ ይጽፍለታል፤ ይልቁንም ከሥርዐታቸው ወጥተው እያንዳንዱ ይገድላል፤ ያጠፋልም።'),
  ('30cba0f0-4135-563c-a87d-840e13f7abbe', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 17, 17, 'እኔም ስለ እነዚያ በጎች ብዙ ጊዜ አለቅስና እጮህ ጀመርሁ።'),
  ('cca37423-aab7-57a1-a48d-5eba5ee138e7', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 18, 18, 'እንደዚህም በየቀኑ ከእነዚያ እረኞች ለሚያጠፋው ለአንዱ እንዴት እንደሚጽፍለት ያን የሚጽፍለትን በራእይ አየሁ።'),
  ('7d6a9fcc-5459-5118-a4ac-202452dc4c15', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 19, 19, 'አውጥቶም ያሳርፈዋል፤ ለበጎችም ጌታ መጽሐፉን ሁሉና የሚሠሩትን ሥራ ሁሉ፥ ከእነርሱም እያንዳንዳቸው ያሰወገዱትንና ለጥፋት አሳልፈው የሰጡትን ሁሉ ያሳያል።'),
  ('b74a383c-ce0b-5586-ad04-faf8f94876c8', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 20, 20, 'መጽሐፉም በበጎች ጌታ ፊት ተነበበ፤ እርሱም መጽሐፊቱን በእጁ አነሣ፤ አነበባት፤ አጥፎም አኖራት።'),
  ('58a2dc13-a350-51a1-ac23-12af77dd10bb', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 21, 21, 'ከዚያም በኋላ እረኞች ዐሥራ ሁለት ሰዓት ሲጠብቁ አየሁ፤ ከእነዚያም በጎች ሦስቱ ተመልሰው መጥተው ገቡ።'),
  ('c491a7b2-e37b-567c-a5a1-b5cbf96ae7ff', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 22, 22, 'ከዚያም ቤት የፈረሰውን ሁሉ ይሠሩ ጀመሩ፤ የዱር እሪያዎችም ከለከሏቸው፤ ነገር ግን አልተቻላቸውም።'),
  ('9b3554d3-e510-511a-a485-a2f5928866bf', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 23, 23, 'ዳግመኛም እንደ ቀድሞው ይሠሩ ጀመሩ፤ ግንቡንም አነሡት፤ ግንቡም ረዥም ይባላል።'),
  ('e326d2e5-536f-5ddc-aee5-6d0977188a9d', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 24, 24, 'ዳግመኛም በግንቡ ፊት ማዕዷን ሲያኖሩ፥ የረከሰውንና ንጹሕ ያይደለውን ኅብስት ሁሉ በእርሱ ላይ ሲሠሩ አየሁ።'),
  ('2eec2cc0-8c92-5b81-ad7a-7a1c7d47b71d', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 25, 25, 'በዚህ ሁሉ ላይም በጎች ዐይኖቻቸውን ተጋርደዋል፤ አያዩምም፤ እረኞቻቸውም እንደዚሁ ናቸው።'),
  ('d1bea8df-95c3-55dd-aeb9-156ccb364b6e', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 26, 26, 'ለጥፋትም አሳልፈው ይሰጧቸዋል፤ በጎቹንም በእግራቸው ይረግጧቸዋል፤ ይበሏቸዋልም።'),
  ('4fcfeb8c-c2e6-564c-a92b-d995b02e91a1', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 27, 27, 'የበጎቹም ጌታ በጎች ሁሉ ዳግመኛ እስኪበተኑ ድረስ ዝም አለ፤ ከእነርሱም ጋር አንድ ሆኑ፤ ከአራዊትም እጅ አላዳኗቸውም።'),
  ('999c672f-ec6f-5425-ad8d-24ca64486142', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 28, 28, 'ያም መጽሐፉን የሚጽፍ አውጥቶ አሳየው፤ በበጎች ጌታ ማደሪያም አነበበው፤ ስለ እነርሱም ይማልደዋል።'),
  ('c5a44d17-9ee0-5487-a557-f2823891fcdb', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 29, 29, 'የእረኞችንም ሥራ ሁሉ እያሳየው፤ ይለምነዋል፤ በእረኞችም ሁሉ ላይ በፊቱ ያዳኛል፤ ያንም መጽሐፍ አንሥቶ በእርሱ ዘንድ አኑሮ ወጣ።'),
  ('56ccd02b-0e9d-5369-a9d9-3f022bc0540f', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 30, 30, 'ሠላሳ ሰባቱም እረኞች እንደዚህ እስከሚጠብቁበት ዘመን ድረስ አየሁ።'),
  ('957ed066-9310-5f9a-afa7-93214d355897', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 31, 31, 'ሁሉም በየጊዜያቸው እንደ ቀድሞዎቹ ፈጸሙ።'),
  ('3d87f651-3f4e-5aee-a8ae-1f68b3d308ec', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 32, 32, 'ሌሎችም በየጊዜያቸው ይጠብቋቸው ዘንድ ከእጃቸው ተቀበሏቸው፤ እያንዳንዱም እረኛ ሁሉ በየጊዜው ነው።'),
  ('ce0a4b78-1e1f-53fe-a819-c3d90d0e1ac5', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 33, 33, 'ከዚህም በኋላ የሰማይ ወፎችን ሁሉ በራእይ አየሁ፥ ንስሮችና ጥንብ አሞራ፥ አንጭት አሞራና ቍራዎች መጡ። ንስሮችም ወፎችን ሁሉ ይመሯቸው ነበሩ።'),
  ('680a4778-ad3b-5d7d-a73a-f25f49936cf2', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 34, 34, 'እነዚያንም በጎች ይበሏቸው ጀመሩ፤ ዐይኖቻቸውንም ይጐጠጕጧቸው ጀመሩ፤ ሥጋቸውንም ይበሉአቸው ጀመሩ።'),
  ('247f748c-1293-5c1b-ad31-5636c16b3c00', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 35, 35, 'በጎችም ሥጋቸው በወፎች ተበልቶአልና ጮኹ።'),
  ('90c700ea-e151-55a7-a171-d116386569b7', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 36, 36, 'እኔም ተኝቼ ሳለሁ ጮኽሁ፤ በጎችንም በሚጠብቃቸው በእረኛው ላይ አለቀስሁ።'),
  ('9afb459a-bd80-5bd1-a0db-49faac7d31c9', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 37, 37, 'በጎችም በውሾችና በንስሮች፥ በአንጭት አሞራዎችም እስከ ተበሉ ድረስ አየሁ።'),
  ('8bbe4b33-8afc-524d-a1f5-21ceb340c8fe', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 38, 38, 'አጥንቶቻቸው ብቻቸውን እስከ ቆሙ ድረስ ሥጋንና ቍርበትን፥ ጅማትንም ፈጽሞ አልተዉላቸውም፤ አጥንቶቻቸውም በምድር ላይ ወደቁ፤ በጎችም አነሱ።'),
  ('84c921da-c3ee-535e-a690-5a81329b16f8', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 39, 39, 'ሃያ ሦስቱም እረኞች እስከሚጠብቁበት ዘመን ድረስ አየሁ፤ አምሳ ስምንት ሱባኤንም በየዘመናቸው ፈጸሙ።'),
  ('2dfc5ebd-459e-51f1-a346-46a92c2ff3b5', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 40, 40, 'ታናናሾች ጠቦቶችም ከእነዚያ ነጫጭ በጎች ተወለዱ፤ ዐይኖቻቸውንም ይገልጡና ያዩ፥ ወደ በጎችም ይጮኹ ጀመሩ።'),
  ('bdb42de6-9b34-5d7e-a7f6-f23216a3cea4', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 41, 41, 'በጎችም አልጮሁላቸውም፤ የነገሯቸውንም ነገር አላዳመጧቸውም፤ ነገር ግን ፈጽመው ቸል አሉ፤ ዐይኖቻቸውንም ተሸፈኑ፤ በረታባቸውም።'),
  ('946ffaa2-2c64-52b7-a58d-b8d49f2bd0ce', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 42, 42, 'በራእይም በጠቦቶቹ ላይ ሲበርሩባቸው ቍራዎችን አየሁ፤ ከእነዚያም ጠቦቶች አንዱን ያዙት።'),
  ('e5efc08a-f2de-5849-aab9-e7b13e522ab4', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 43, 43, 'በጎችንም ቀጥቅጠው በሏቸው፤ ለእነዚያ ጠቦቶችም ቀንዶች እስኪወጡላቸው ድረስ አየሁ። ቍራዎችም ቀንዶቻቸውን ይሰብሩባቸው ነበር።'),
  ('d34f315b-89f0-5e4b-a178-5897dc9db464', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 44, 44, 'ከእነዚያም በጎች በአንዱ ላይ አንድ ትልቅ ቀንድ እስኪበቅል አየሁ። ዐይኖቻቸውም ተገለጡ።'),
  ('3112a58a-a04b-55b1-a1e3-32dd5423b0d5', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 45, 45, 'በእነርሱም አየባቸው፤ ዐይኖቻቸውም ተከፈቱ፤ ለበጎችም ጮኸላቸው፤ አውራዎችም አዩት፤ ሁሉም ወደ እርሱ ሮጡ።'),
  ('d019d335-0f3c-5f24-afaa-b85ef6a5aae9', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 46, 46, 'ንስሮችና ጥንብ አሞራዎች፥ ቍራዎችና አንጭት አሞራዎች እስከ ዛሬ ድረስ ይነጥቋቸው ነበር። በላያቸውም እያንዣበቡ ይበሏቸው ነበር።'),
  ('1824af43-6fd9-55b0-a629-f7d35b7185d7', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 47, 47, 'በጎች ግን ዝም ብለው ነበር፤ አውራዎችም ፈጽመው ይጮኹ ነበር፤ እነዚያም ቍራዎች ከእነርሱ ጋር ይጋደሉና ይጣሉ ነበር። ቀንዱንም ሊያስወግዱ ወደዱ፤ ነገር ግን አልቻሉትም።'),
  ('ed623a9f-b450-5f4f-a3f3-415588bd6401', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 48, 48, 'እረኞች፥ ንስሮችና እነዚያ ጥንብ አሞራዎች፥ አንጭት አሞራም እስኪመጡ ድረስ አየኋቸው።'),
  ('580da0bf-d122-5705-aefc-fd8673edbfbc', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 49, 49, 'የዚያንም አውራ ቀንዱን ይሰብሩ ዘንድ ለቍራዎች ጮኹ።'),
  ('4e02d132-24a1-50bf-ab41-233a8b501287', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 50, 50, 'እነርሱም ከእርሱ ጋር ተጣልተው ተጋደሉ፤ እርሱም ከእነርሱ ጋር ተጣላ፤ ረድኤቱም ትመጣለት ዘንድ ጮኸ።'),
  ('eb3db0cf-9293-5225-a696-0e0abda515da', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 51, 51, 'የእረኞችን ስሞች የሚጽፍና በበጎች ጌታ ፊት የሚያቀርብ ያ ሰውም እስኪመጣ ድረስ አየሁ።'),
  ('adebe1cd-db13-5711-a90c-1764248daa59', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 52, 52, 'እርሱም ረዳው፤ ሁሉንም አሳየው፤ የዚያም አውራ ረዳቱ ወረደ፤ ያም የበጎች ጌታ ወደ እነርሱ በመዓት እስኪመጣባቸው ድረስ አየሁ።'),
  ('2071542b-e8c8-587a-a7f1-71e6125e4fc5', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 53, 53, 'ያዩትም ሁሉ ሸሹ፤ ሁሉም ከፊቱ የተነሣ በጥላው ወደቁ። ንስሮች፥ ጥንብ አሞራዎችና ቍራዎች፥ አንጭት አሞራም ተሰበሰቡ።'),
  ('8d5b8439-f78a-5b11-adee-b1b4bef1e8f1', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 54, 54, 'ከእነርሱም ጋር የሜዳ በጎችን አመጡ፤ ሁሉም በአንድነት የዚያን አውራ ቀንድ ሊሰብሩ ተረዳዱ።'),
  ('fc9aba40-57cb-5bba-af45-50ae1f264885', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 55, 55, 'በጌታ ቃል መጽሐፉን የሚጽፍ ያን ሰውም በኋላ የተነሡ እነዚያ ዐሥራ ሁለቱ እረኞች ያጠፉትን ያን የጥፋት መጽሐፍ እስኪገልጠው ድረስ አየሁት።'),
  ('a60f9d85-d6f0-5df4-a854-b777e20fc9f6', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 56, 56, 'ከእነርሱም አስቀድመው ከነበሩት እነርሱ አብልጠው እንዳጠፉ በበጎች ጌታ ፊት አሳየ፤ የበጎችም ጌታ ወደ እነርሱ እስኪመጣ ድረስ አየሁ።'),
  ('82220291-c34c-5182-a75d-089451a34491', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 57, 57, 'የቍጣውንም በትር በእጁ አንሥቶ ምድርን መታት፤ ምድርም ተሰነጠቀች፤ አራዊትም ሁሉ፥ የሰማይ ወፎችም ሁሉ ከእነዚያ ከበጎች የተነሣ ወደቁ፤ በምድርም ሰጠሙ፤ ምድርም ተጫነቻቸው።'),
  ('7b9837ce-7333-5f30-a0c3-4f1fe969b479', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 58, 58, 'ለበጎችም ታላቅ ሰይፍ እስኪሰጣቸው ድረስ አየሁ፤ በጎችም ይገድሏቸው ዘንድ በዱር አራዊት ሁሉ ላይ ወጡ።'),
  ('306ce2d4-3f96-5d84-ab76-310d01f6da86', '1bd4a8c2-b1ba-5aa4-a486-cc6759bbe9c7', '4f909aa1-cbea-5cd4-a403-5e7a4f46381e', 59, 59, 'አራዊትና የሰማይ ወፎችም ሁሉ ከፊታቸው ሸሹ።'),
  ('c7bc5018-5e76-5e75-abbf-6f4fa380a3d7', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 1, 1, 'ባማረችው ምድር ዙፋን እስኪሠራ ድረስ አየሁ፤ የበጎችም ጌታ በእርሱ ላይ ተቀመጠ።'),
  ('b2e4c8c9-ea4d-57b0-ab59-3a4bd49824bc', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 2, 2, 'የታጠፉትንም መጣፎች ሁሉ አነሣ፤ እነዚያንም መጣፎች በበጎች ጌታ ፊት ገለጣቸው።'),
  ('65229720-38a9-5767-a424-189b04105e14', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 3, 3, 'እነዚያንም የቀደሙትን ሰባቱን ነጮች ጠራቸው፤ ኀፍረታቸው እንደ ፈረስ ኀፍረት ከሆነ ከእነዚያ ከዋክብት ከሚቀድም ከመጀመሪያው ኮከብ ወደ እርሱ ያመጡ ዘንድ አዘዘ።'),
  ('4c2582cf-0e77-5d0d-a30f-26fe51586131', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 4, 4, 'አስቀድሞ የወደቀውን መጀመሪያውንም ኮከብ፥ ሁሉ ወደ እርሱ አመጧቸው።'),
  ('6c4ae612-fc05-589c-a5f9-f2387ccb6386', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 5, 5, 'ከሰባቱ ነጮች አንዱ የሆነውን በፊቱ የሚጽፈውንም ያን ሰው እንዲህ አለው-'),
  ('d50a844e-3964-58bc-a3eb-e5c2aae30d93', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 6, 6, '“በጎችን የሰጠኋቸውን፥ ተቀብለውም ካዘዝኋቸው ወጥተው ብዙዎችን ያጠፉትን እነዚህን ሰባውን እረኞች አግዛቸው።”'),
  ('1687b24b-b6ad-503f-abf9-b7c4a5de8726', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 7, 7, 'እነሆ ሁሉንም ታስረው አየኋቸው፤ ሁሉም በፊቱ ቆመው ነበር፤ ፍርድም አስቀድሞ ከከዋክብት ተጀመረ፤ ተወቀሱ፤ ኀጢአተኞችም ሆነው ተገኙ፤ ወደ ቅጣት ቦታም ሄዱ።'),
  ('91d0cf05-fdad-5ae1-a905-1bcdb61dfbd4', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 8, 8, 'ወደ ጥልቁም ጣሏቸው፤ ያም ቦታ የሚያላልብ፥ እሳትንና የእሳት ምሰሶን የተመላ ነው።'),
  ('8aba9fc4-57c4-56cc-a8f1-ff9b89fb1ad2', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 9, 9, 'እነዚያም ሰባው እረኞች ለፍርድ ቀረቡ፤ ኀጢአተኞችም ሆኑ፤ እነርሱም ወደዚያ የእሳት ጕድጓድ ተጣሉ።'),
  ('db69ec48-711b-5417-a538-2decc861f4ca', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 10, 10, 'ያንጊዜም እንደዚሁ እሳትን የተመላ አንድ ጕድጓድ በምድር መካከል እንደ ተከፈተ አየሁ።'),
  ('8600ed40-b996-5d21-a980-6bae7cb23ef5', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 11, 11, 'የታወሩ እነዚያን በጎችም አመጧቸው። ለፍርድ ቀረቡ፤ ኀጢአተኞችም ሆነው ተገኙ፤ ወደዚያ ወደ እሳቱ ጕድጓድም ተጣሉ፤ ተቃጠሉም።'),
  ('8ca7ef56-7f1e-5780-a182-2c5f315eefab', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 12, 12, 'ያም ጕድጓድ በዚያ ቤት በስተቀኝ ነበር፤ እነዚያንም በጎች ሲቃጠሉ፥ አጥንቶቻቸውም ሲቃጠሉ አየሁ።'),
  ('1fd5a843-c2b7-5cda-a5f2-279331df783e', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 13, 13, 'ያን ያረጀውንም ቤት እስኪጠቀልለው አይ ዘንድ ቆምኹ፤ ምሰሶዎችንም ሁሉ አወጧቸው።'),
  ('c22d9ae2-e93b-5390-aea8-cfc329be9f85', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 14, 14, 'የዚያም ቤት ተክሉና ጌጡ ሁሉ ከእርሱ ጋር ተጠቀለለ፤ አውጥተውም በምድር ቀኝ ባለ በአንድ ቦታ ጣሉት።'),
  ('f4d31958-e908-5d5d-a4f0-c48578451e32', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 15, 15, 'የበጎች ጌታም ከዚያ ከቀደመው ቤት ታላቅና ከፍ ያለ አዲስ ቤትን እስኪያመጣ ድረስ አየሁ፤ ያንም አስቀድማ በተጠቀለለችው ቤት ቦታ አቆመው።'),
  ('d23af095-3027-5d36-a22d-154600702554', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 16, 16, 'ምሰሶዎችዋም ሁሉ አዲሶች ናቸው፤ ጌጧም ሁሉ አዲስ ነው፤ ካፈረሳት ካረጀችው ከመጀመሪያዪቱም ቤት ይልቅ ታላቅ ነው፤ በጎችም ሁሉ በመካከሏ ናቸው።'),
  ('f3b9fa90-2180-5db4-ac40-585ba08f1115', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 17, 17, 'የቀሩትንም በጎች ሁሉና በምድር ላይ ያሉ እንስሳትን ሁሉ፥ የሰማይ ወፎችንም ሁሉ፥'),
  ('dcfbea92-ca30-5a4f-ada1-bbf4d7dac1bb', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 18, 18, 'ለእነዚያ በጎች ሲወድቁና ሲሰግዱ፥ ሲማልዷቸውና ቃላቸውንም ሁሉ ሲሰሟቸው አየኋቸው።'),
  ('7b8c6ff3-9dd5-542a-ab55-3b8ada500c02', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 19, 19, 'ከዚያም በኋላ ነጫጭ ልብስ የለበሱና አስቀድመው ወደ ሰማይ ያወጡኝ እነዚያ ሦስቱ እጄን ያዙኝ።'),
  ('ee94237c-a183-56cc-aadb-711994bdba69', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 20, 20, 'የዚያም አውራ እጅ ይዛኝ ሳለች አወጡኝ፤ ፍርድም ሳትደረግ በእነዚያ በጎች መካከል አኖሩኝ።'),
  ('1cee50a9-0cf5-5490-af76-b841e6409f61', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 21, 21, 'እነዚያም በጎች ሁሉ ነጫጭ ሆኑ፤ ፀጕራቸውም ታላቅና ንጹሕ ነበር።'),
  ('e9ca87e3-089d-500b-ab5f-a63de75b4b66', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 22, 22, 'የጠፉና የተበተኑ ሁሉ፥ የዱር አራዊት ሁሉና የሰማይ ወፎችም ሁሉ በዚያ ቤት ተሰበሰቡ።'),
  ('0ae4b523-4fd7-52a1-a4d6-9b1282018dfb', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 23, 23, 'ሁሉም ደጋግ ሁነዋልና፥ ወደ ማደሪያውም ተመልሰዋልና የበጎች ጌታ እጅግ ደስ አለው።'),
  ('a251ad23-c5bc-5d00-afc9-72d5e8ebbeec', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 24, 24, 'ለበጎችም የተሰጣቸውን ያን ሰይፍ እስኪያጋድሙት ድረስ አየሁ፤ ወደ ቤቱም መለሱት፤ በጌታም ፊት አተሙት።'),
  ('209806e6-a805-5566-ac77-f4a89a461ed6', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 25, 25, 'በጎችም ሁሉ በዚያ ቤት ተዘጋባቸው፤ ነገር ግን አልቻላቸውም፤ የሁሉም ዐይኖቻቸው ተገልጠው በጎውን ይመለከቱ ነበር፤ ከእነርሱም በመካከላቸው የማያይ አንድ እንኳ አልነበረም።'),
  ('2d5f5cb2-7995-5b82-a429-e5be8de046db', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 26, 26, 'ያም ቤት ታላቅና ሰፊ እንደ ሆነ አየሁ፤ ፈጽሞም ሙሉ ነበር። አንድ ነጭ ላምም ተወልዶ አየሁ፤ ቀንዶቹም ታላላቆች ነበሩ።'),
  ('e7528c66-006b-5eb2-a3c7-d645429dba7a', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 27, 27, 'የዱር አራዊትና የሰማይ ወፎችም ሁሉ ፈርተው በየጊዜው ይማልዱታል።'),
  ('4f355177-46e0-5776-a1ed-402e713c5cd4', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 28, 28, 'ዘመዶቻቸውም ሁሉ እስኪለወጡ ድረስ አየሁ፤ ላሞችም ሁሉ ነጫጭ ሆኑ።'),
  ('1ada59d5-d1df-5e9a-ac83-3cf58624bfd0', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 29, 29, 'በመጀመሪያም ነገር በመካከላቸው ሆነ፤ ያም ነገር ታላቅ አውሬ ሆነ፤ በራሱም ላይ ታላላቅና ጥቋቍር ቀንዶች አሉ።'),
  ('e8c72389-9c68-55f2-a19a-ff0770d00430', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 30, 30, 'የበጎችም ጌታ በእነርሱና በላሞች ሁሉ ደስ አለው።'),
  ('8425ad62-2ed4-5ac0-af60-cbc453967501', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 31, 31, 'እኔም በመካከላቸው ተኝቼ ነቃሁ፤ ሁሉንም አየሁ፤ ተኝቼም ያየሁት ራእይ ይህ ነው፤ ነቅቼም የጽድቅ ጌታን አመሰገንሁት፤ ለእርሱም ምስጋናን አቀረብሁለት።'),
  ('361c7838-a668-527d-a5cc-c7b86d50ffef', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 32, 32, 'ከእርሱም የተነሣ ታላቅ ልቅሶን አለቀስኹ፤ ወደዚያም ወደ አየሁት ሲወርዱ ባየሁ ጊዜ መታገሥን አልቻልሁምና እንባዬ አልተገታም።'),
  ('1d3a1ff9-3eff-5ea9-ae56-e2243ad97365', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 33, 33, 'ሁሉ መጥቶ ይጨረሳልና፥ የሰውም ሁሉ ሥራ በየወገኑ ተገለጠልኝ።'),
  ('55e8c306-cc88-5a35-af1b-abdf63eb0934', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 34, 34, 'በዚያችም ሌሊት የቀደመውን ሕልሜን አሰብሁት፤ ያን ራእይ አይቻለሁና ስለ እርሱ ነገር አለቀስሁ፤ ታወክሁም።'),
  ('fa721bfb-5694-5858-a9b5-8a58903877d6', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 35, 35, 'አሁንም ልጄ፥ ማቱሳላ! ወንድሞችህን ሁሉ ጥራልኝ፤ የእናትህንም ልጆች ሁሉ ሰብስብልኝ፤ ቃል ጠርቶኛልና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('81c8a875-f1e8-57a7-aaa3-0b512d73eba3', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 36, 36, 'እስከ ዘለዓለምም የሚደርስባችሁን እገልጥላችሁ ዘንድ መንፈስ በእኔ ላይ አድሮአልና።'),
  ('2727b33a-715c-5699-a092-1a4fb4d4d993', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 37, 37, 'ከዚያም በኋላ ማቱሳላ ሄዶ ወንድሞቹን ሁሉ ወደ እርሱ ጠራቸው፤ ዘመዶቹንም ሰበሰባቸው፤ ለልጆቹም ሁሉ እውነት ነገርን ነገራቸው።'),
  ('9c1847df-d31c-5453-a3be-510555b59240', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 38, 38, 'እንዲህም አለ- “ልጆቼ፥ የአባታችሁን ነገር ሁሉ ስሙ፤ ወዳጆቼ፥ በእናንተ አዳኝባችኋለሁና፥ እነግራችኋለሁምና የአፌን ቃል በቅንነት አድምጡ።'),
  ('6ed55638-fe1d-5630-abfe-33c95e16e890', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 39, 39, 'ሕግንም ውደዷት፤ በእርሷም ሂዱ፤ ሁለት ልብም ሆናችሁ ወደ ሕግ አትቅረቡ፤ ልጆቼ፥ በእውነት ኑሩ እንጂ ሁለት ልብ ሆነው ከሚኖሩ ሰዎች ጋር አትተባበሩ።'),
  ('9a5cac3e-fb88-521b-ad81-95518d9e2abf', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 40, 40, 'እርስዋም በመልካም ጐዳና ትመራችኋለች፤ በምድር ላይ የግፍ አካል እንዲጸና አውቃለሁና ጽድቅ ለእናንተ ኅብረት ይሆናል።'),
  ('b9eac3f0-e8f6-5c5f-ac11-aaf1c91eb133', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 41, 41, 'በምድርም ላይ ታላቅ መቅሠፍት ይፈጸማል፤ ዐመፅም ሁላ ትጨረሳለች፤ ከሥርዋም ትቈረጣለች።'),
  ('86cec493-fd01-5d73-a150-00eb61cc16f2', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 42, 42, 'ሕንጻውም ሁሉ ያልፋል፤ ዐመፅም ትደገማለች፤ በምድርም ላይ ትፈጸማለች፤ የዐመፅና የግፍ፥ የበደልም ሥራ ሁሉ እጥፍ ሆና ትሠራለች።'),
  ('294aa727-b284-50d1-aa02-7ffc24f8a4d9', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 43, 43, 'ዐመፅና ኀጢአት፥ ስድብና ግፍ፥ ክፉውም ሥራ ሁሉ በበዛ ጊዜ፥ በደልና ወንጀል፥ ርኵሰትም በበዛ ጊዜ ታላቅ መቅሠፍት ከሰማይ በእነዚህ ሁሉ ላይ ይደረጋል።'),
  ('d2e915cb-2d42-55c1-a3bc-631c547d1d51', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 44, 44, 'ቅዱስ እግዚአብሔርም በምድር ላይ ፍርድን ያደርግ ዘንድ በመቅሠፍትና በመዓት ይመጣል።'),
  ('416ec1be-a7b8-5310-adc7-de30b1dac921', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 45, 45, 'በእነዚያም ወራቶች ግፍ ከሥርዋ ትቈረጣለች፤ የዐመፅም ሥሮች ከሽንገላ ጋር ይቈረጣሉ፤ ከሰማይም በታች ይጠፋሉ።'),
  ('4bbac590-3fca-54b8-a1d7-6655f206341b', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 46, 46, 'ሁሉም ከአሕዛብ ጋር ይሰጣል፤ አዳራሾችም በእሳት ይቃጠላሉ፤ ከምድርም ሁሉ ያወጧቸዋል፤ በገሃነመ እሳትም ይጣላሉ። በመዓትና በዘለዓለማዊ ኀይለኛ ፍርድ ይጠፋሉ።'),
  ('7d065f01-2d22-52f7-a685-508f58d32f2d', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 47, 47, 'ጻድቁ ከእንቅልፉ ይነሣል፤ ጥበብም ይነሣል፤ ለእነርሱም ይሰጣል፤ ከእርሱም የተነሣ የዐመፅ ሥሮች ይቈረጣሉ።'),
  ('3a55ad9a-8e90-5657-af8d-b81670891108', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 48, 48, 'ኃጥኣንም በሰይፍ ይጠፋሉ፤ ተሳዳቢዎችም በቦታው ሁሉ ይቈረጣሉ።'),
  ('ac072674-6783-57bd-ab55-15bd3bc9ce92', 'c17944a0-b1f5-5473-ab48-5b970261aa52', 'bfb8f009-ee2f-51ad-a3e8-dcdaecb7b7cd', 49, 49, 'ግፍን የሚያስቧትና ስድብንም የሚሠሯት በሰይፍ ይጠፋሉ።'),
  ('f167a095-d042-54d9-a9e7-4533f6108340', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 1, 1, '“ከዚህም በኋላ ሁለተኛዋ ጽድቅ የሚደረግባት ስምንተኛዪቱ ሱባዔ ትደረጋለች፤ ከግፈኞች የተነሣም የእውነት ፍርድ ይደረግባት ዘንድ ለእርስዋ ሰይፍ ይሰጣል፤ ኃጥኣንም በጻድቃን እጅ ይሰጣሉ።'),
  ('0cec0517-3830-5148-a87a-65c8689dd51c', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 2, 2, 'በመጨረሻዋም ከጽድቃቸው የተነሣ ንብረት ያደርጋሉ፥ ለገናናው ንጉሥም እስከ ዘለዓለም ሊመሰገንበት ቤት ይሠራል።'),
  ('1b796af3-6a47-561a-a53f-6f3ce96ca5e2', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 3, 3, '“ከዚህም በኋላ በዘጠነኛዪቱ ሱባዔ ለዓለም ሁሉ የእውነት ፍርድ ትገለጣለች።'),
  ('13a13ef5-32c2-5db8-a430-4230086c10cb', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 4, 4, 'የዝንጉዎችም ሥራ ሁሉ ከምድር ይጠፋል፤ ዓለምም ለጥፋት ይቈጠራል፤ ሰዎችም ሁሉ የቀናች መንገድን ይመለከታሉ።'),
  ('7aef5b74-71cb-55da-aa3a-59eb912652f6', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 5, 5, '“ከዚህም በኋላ በዐሥረኛዪቱ ሱባዔ በሰባተኛው ክፍል የዘለዓለም ፍርድ ትደረግባታለች።'),
  ('92002767-beaa-51d4-adcf-ed2019eab05a', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 6, 6, 'ከመላእክት ሁሉ መካከል የሚወጣ ታላቅ ፍርድም በዘለዓለማዊው ሰማይ ከትጉሃን መላእክት ይደረጋል።'),
  ('db1ce536-0aa1-5cfa-ad86-df3ca333cee2', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 7, 7, 'የቀደመውም ሰማይ ፈጽሞ ያልፋል፤ አዲሱ ሰማይም ይገለጣል። የሰማይ ሠራዊትም ሁሉ ሰባት እጥፍ ለዘለዓለም ያበራሉ።'),
  ('99e166d5-0429-508c-ad65-b675a4bcf1b9', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 8, 8, 'ከዚህም በኋላ ቍጥር የሌላቸው ብዙ ሱባዔዎች በቸርነቱና በይቅርታው ለዘለዓለም ይሆናሉ፤ ከዚያም በኋላ ኀጢአት እስከ ዘለዓለም ትሠራለች አትባልም።'),
  ('3630745a-9093-5fb0-aabe-dd1439911611', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 9, 9, '“አሁንም ልጆቼ፥ እነግራችኋለሁ፤ የጽድቅ መንገዶችንና የግፍ መንገዶችንም አሳያችኋለሁ።'),
  ('d43b89a7-7db8-58bf-ae09-7e52ef01e1f1', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 10, 10, 'ዳግመኛም የሚመጣውን ታውቁ ዘንድ አሳያችኋለሁ፤ አሁንም ልጆቼ፥ ስሙኝ፤ በጽድቅ መንገዶችም ሂዱ።'),
  ('910cad71-1758-5629-a5ba-cdf5efcf2f32', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 11, 11, 'በዐመፅ መንገድ የሚሄዱ ሁሉ ለዘለዓለም ይጠፋሉና በግፍ መንገዶች አትሂዱ።”'),
  ('ecf08870-76dd-5a24-a154-da39af114c5c', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 12, 12, 'ከሰው ሁሉ ክቡር፥ የምድርም ሁሉ መምህር ከሆነው፥ የጥበብን ትምህርት ሁሉ ከጻፈው ከሄኖክ የተጻፈ መጽሐፍ፥'),
  ('392dc8c7-e4c5-5617-ae22-6cec40cea113', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 13, 13, 'በምድር ለሚኖሩ ለልጆቼ ሁሉ፥ ፍርድንና ሰላምን ለሚያደርጉ ለኋላ ልጆችም፥'),
  ('7739e845-617d-5eb7-a268-ea82c8370899', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 14, 14, 'ቅዱሱና ገናናው ለሁሉ ቀኖችን ሰጥትWaልና መንፈሳችሁ በዘመናት አትዘን።'),
  ('773d3d63-840e-5ce7-a00d-22bd7d05a656', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 15, 15, 'ጻድቅ ሰው ከእንቅልፉ ይነሣል፤ በጽድቅ መንገዶችም ይሄዳል።'),
  ('f8cfe102-2445-5ba4-aee6-f3bae0585bc0', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 16, 16, 'መንገዱም፥ አኗኗሩም ሁሉ በቸርነትና በዘለዓለማዊ ይቅርታ ነው፤ ጻድቁን ይቅር ይለዋል፤ ለእርሱም ለዘለዓለሙ ቅንነትን ይሰጠዋል፤ ሥልጣንንም ይሰጠዋል።'),
  ('3ec3c053-643b-5fd8-a5c3-5f8f2fb55446', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 17, 17, 'በቸርነትና በጽድቅ ጸንቶ ይኖራል፤ ብርሃንም ለዘለዓለም ይኖራል፤ ኀጢአትም በጨለማ እስከ ዘለዓለም ትጠፋለች፤ ከእንግዲህ ወዲያም ከዚያች ቀን ጀምሮ እስከ ዘለዓለም አትታይም።'),
  ('29a48b5d-7be8-5ba5-aac3-6e751275a39b', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 18, 18, 'ከዚህም በኋላ እንዲህ ሆነ፥ ሄኖክ ከመጻሕፍት ይናገር ጀመረ።'),
  ('ebe3b97a-f063-5b1e-adc0-1b3e00bcbbb1', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 19, 19, 'ሄኖክ ስለ ልጆችና ስለ ዓለም ምርጦች፥ ስለ ጽድቅና ስለ ቅን ፍርድ ተክልም እንዲህ አለ- “ልጆቼ፥ እነዚህን ነገሮች እነግራችኋለሁ፤ አስረዳችኋለሁም።'),
  ('f0e6d97d-1c6e-5d82-a5a9-a49249cf3b65', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 20, 20, 'ከሰማይ የታየኝን ራእይ፥ ከቅዱሳን መላእክት ቃልም ያወቅሁትንና በሰማይ ሰሌዳ ላይ ያስተዋልሁትን እነግራችኋለሁ።'),
  ('c1636f83-f7f8-51ca-ab74-f28471bcc1a5', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 21, 21, 'ሄኖክም ከመጻሕፍት ይናገር ጀመረ፥ እኔ ሰባተኛው ትውልድ በመጀመሪያቱ ሱባዔ ተወለድሁ።'),
  ('b54e344d-1039-53bf-ae80-74b86d02c063', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 22, 22, 'ፍርድና እውነት እስኪደረጉ ድረስ ጌታ ታገሠ፤ ከእኔም በኋላ በሁለተኛዪቱ ሱባዔ ታላቅ ኀጢአት ትሠራለች።'),
  ('151d7434-64b1-52f8-a14d-2b0f9ecb35be', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 23, 23, 'ተንኰልም ጸናች፤ በእርሷም የመጀመሪያዪቱ መጨረሻ ትደረጋለች።'),
  ('e0bdb1e6-848d-5ab5-a246-3e2d648acb38', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 24, 24, 'ሰውም በእርስዋ ይድናል፤ እርሱም ከተጨረሰ በኋላ ዐመፅ ታድጋለች፤ እርሱም ለኀጥኣን ሥርዐትን ያደርጋል።'),
  ('00ea37cf-faf3-5e52-a1d5-d1213111aa05', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 25, 25, 'ከዚህም በኋላ በሦስተኛዪቱ ሱባዔ በመጨረሻዋ ሰው ለእውነተኛ ፍርድ ተክል ይመረጣል፤ ከእርሱም በኋላ የዘለዓለም ጽድቅና ርትዕ ተክል ይወጣል።'),
  ('6e6dce81-7076-5216-af38-83f505b5708e', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 26, 26, 'ከዚህም በኋላ በአራተኛዪቱ ሱባዔ በመጨረሻዋ የቅዱሳንና የጻድቃን ራእያት ይገለጣሉ። ሥርዐትና ቅጥርም ለልጅ ልጅ ዘመን ይሠራላቸዋል።'),
  ('a5ae83e2-a434-52fd-a7af-f4601e9d1f0a', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 27, 27, 'ከዚህም በኋላ በአምስተኛዪቱ ሱባዔ በመጨረሻዋ የምስጋናና የመንግሥት ቤት እስከ ዘለዓለም ይሠራል።'),
  ('1e32aacb-9ee8-5ac3-a9d5-d175167daafb', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 28, 28, 'ከዚህም በኋላ በስድስተኛዪቱ ሱባዔ በእርሷ የሚኖሩ ሰዎች ሁሉ ደንቆሮዎች ናቸው፤ የሁሉም ልቡናቸው ከጥበብ ይለያል፤ በእርሷም ሰው ያርጋል።'),
  ('1b12156a-8aed-57a2-a140-b6717ee02ef1', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 29, 29, 'በመጨረሻዋም ቤተ መንግሥቱ በእሳት ይቃጠላል፤ የተመረጠው የመንግሥት ወገን ሁሉም በእርሷ ይበተናሉ።'),
  ('3e3703f6-3c4a-51f9-a151-be0f93d55c6e', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 30, 30, 'ከዚህም በኋላ በሰባተኛዪቱ ሱባዔ ወንጀለኛዋና ሥራዋ ብዙ የሆነ ትውልድ ትነሣለች፤ ሥራዋም ሁሉ ወንጀል ነው።'),
  ('fe3246be-e4d4-5c39-ae3f-c0880dfd8582', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 31, 31, 'በመጨረሻዋም ለፍጥረቱ ሁሉ ሰባት ዕጥፍ ትምህርት የሚሰጣቸው የተመረጡ ጻድቃን ከዘለዓለም የጽድቅ ተክል ይመረጣሉ።'),
  ('41a3a721-fd28-5732-a3c1-bc3c42eebaa6', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 32, 32, 'ከሰው ልጆች ሁሉ የቅዱሱን ቃል መስማት የሚችልና የማይታወክ ማን ነው? አሳቡንስ ያስብ ዘንድ የሚችል ማን ነው?'),
  ('d2c42c03-4a2b-5be5-abca-3477ba8f7706', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 33, 33, 'ሰማይንና ሥራዋንም ሁሉ ቀና ብሎ ማየት የሚችል ማን ነው?'),
  ('b1cc75e4-721b-5ba0-a587-9dc45047b1c1', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 34, 34, 'የሰማይንስ ሥራ ማወቅ የሚቻለው ማን ነው? ነፍሱን ያይ ዘንድ፥ ያም ባይሆን መንፈሱ ያይና ይናገር ዘንድ፥ ያም ባይሆን ወደ ላይ ይወጣና ክንፎቻቸውን ሁሉ ያይና ያስባቸው ዘንድ፥ ያም ባይሆን እንደ እነርሱ ያደርግ ዘንድ የሚቻለው ማን ነው?'),
  ('12764ba1-4506-5029-a884-995de6d380dd', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 35, 35, 'የምድር ወርዷና ርዝመትWa ምን እንደ ሆነ ማወቅ የሚችል ሰው ሁሉ ማን ነው?'),
  ('85ec9d37-a72d-514a-a8f4-4666faf46e0f', '92bdebf3-66d8-5316-a986-4ee8163b8b50', 'e886359f-7630-572d-accf-057156edeaba', 36, 36, 'የእነዚህ ሁሉ ልካቸው ለማን ተገለጠ? የሰማይም ምጥቀትWaና ርዝመትWa ምን እንደ ሆነ፥ የጸናችም በምን ላይ እንደ ሆነ ማወቅ የሚችል፥ የኮከቦችም ቍጥራቸው ምን ያህል እንደ ሆነ፥ ብርሃናትም ሁሉ በየት እንደሚያርፉ ማወቅ የሚቻለው ሰው ሁሉ ቢኖር በእርሱ ነው።'),
  ('29cbe8a9-9f71-59d7-a719-12c778e16bf3', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 1, 1, 'አሁንም ልጆቼ፥ እላችኋለሁ፤ ጽድቅን ውደዱአት፤ በእርሷም ሂዱ፤ የጽድቅ መንገዶችን ይቀበሏቸው ዘንድ ይገባልና፤'),
  ('c4de008d-2563-5541-a45f-1e9a38875510', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 2, 2, 'የዐመፅ መንገዶችም ፈጥነው ይጠፋሉ፤ ያንሳሉም፤ ለታወቁ ሰዎችም ከልጅ ልጅ ጀምሮ የዐመፅና የሞት መንገዶች ይገለጣሉ፤ ከእነርሱም ይርቃሉ፤ አይከተሏቸውምም።'),
  ('83289297-9b2c-5cba-a8b4-038aa14a2073', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 3, 3, 'አሁንም ለእናንተ ለጻድቃን እላችኋለሁ፤ በክፉ መንገዶች አትሂዱ፤ በግፍዕና በሞት መንገድም አትሂዱ፤ እንዳትጠፉም ወደ እነርሱ አትቅረቡ፤ ነገር ግን የተመረጠች ጽድቅንና ሕይወትን ለእናንተ ፈልጉ፤ ምረጡም።'),
  ('80bb730a-9085-5ffc-af3f-fcf2db98af90', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 4, 4, 'በሰላም መንገዶችም ሂዱ፤ ትድናላችሁ፤ በተድላም ትኖራላችሁ፤ በልቡናችሁም ዐሳብ ትይዛላችሁ።'),
  ('1dbfba9c-11bc-5a76-a6cd-91f0f6a32d6d', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 5, 5, 'ክፉ ጥበብን ይሠሩ ዘንድ ኃጥኣን ሰዎችን እንደሚፈትኗቸው አውቃለሁና ነገሬ ከልቡናቸሁ አይጥፋ፤ ቦታም ሁሉ አይገኝላትም፤ መከራም ሁሉ አይጐድልም።'),
  ('232330be-73f1-50f4-a8bb-5ec6a0e3dd0c', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 6, 6, 'ዐመፅንና ግፍን ለሚያንጹ፥ ተንኰልንም ለሚሠሯት ሰዎች ወዮላቸው! እነርሱ ፈጥነው ይጠፋሉና፥ ሰላምም የላቸውምና።'),
  ('351d2fa2-5ded-53d0-a496-2be25903aece', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 7, 7, 'ቤታቸውን በኀጢአት ለሚሠሩ ሰዎች ወዮላቸው! ከመሠረታቸው ሁሉ ይጠፋሉና፥ በሰይፍም ይወድቃሉና፥ ወርቅንና ብርንም የሚሰበስቧት በፍርድ ፈጥነው ይጠፋሉና።'),
  ('a497371f-36af-5803-a19d-12b5c8335b6f', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 8, 8, 'እናንተ ባለጠጎች ወዮላችሁ! በባለጠግነታችሁ ላይ ታምናችኋልና፥ ከባለጠግነታችሁም ትለያላችሁና።'),
  ('6c48d772-a14c-520b-ad40-16e76c3305cc', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 9, 9, 'በባለጠግነታችሁ ወራት ልዑልን አላሰባችሁትምና፥ እናንተስ ስድብን፥ በደልንም ሠራችኋት፤ ደም ለሚፈስባት ቀንና ለጨለማዋ ቀን፥ ለታላቅዋ ፍርድ ቀንም የተዘጋጃችሁ ሆናችኋል።'),
  ('464191f5-e84a-5c27-a88b-5feb873d1982', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 10, 10, 'የፈጠራችሁ እንደሚያጠፋችሁ፥ በውድቀታችሁም ላይ ይቅርታው እንደማይደረግላችሁ እኔ እንደዚህ ብዬ እነግራችኋለሁ።'),
  ('f49f3cb7-7371-5978-ae6e-73fd4178c13f', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 11, 11, 'ፈጣሪያችሁም በጥፋታችሁ ደስ ይለዋል፤ የእናንተም ጻድቃን በእነዚያ ወራት ለዝንጉዎችና ለኃጥኣን መዘባበቻ ይሆናሉ።'),
  ('8ed9f467-ab01-52c3-aaae-7941bdfb4e88', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 12, 12, 'ዐይኖቼ ውኃን የቋጠሩ ደመናዎችን ይሆኑ ዘንድ፥ በእናንተም ላይ አለቅስ ዘንድ፥ ውኃንም እንደ ቋጠረ ደመና እንባዬን አፈስ ዘንድ፥ ከልቡናዬ ኀዘንም አርፍ ዘንድ ማን በሰጠኝ ነበር።'),
  ('d34f8cc5-ab49-5ad6-a7ec-e5e7a46db187', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 13, 13, 'ስድብንና ክፋትን ታደርጉ ዘንድ ማን ሰጣችሁ? እናንተን ኃጥኣንን ቍርጥ ፍርድ ያገኛችኋል።'),
  ('00a28ad3-a8e9-5d21-acdb-6e8c06307e20', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 14, 14, 'ጻድቃን ከኃጥኣን የተነሣ አትፍሩ፤ እንደ ወደዳችሁ በእነርሱ ላይ ፍርድን ታደርጉባቸው ዘንድ እግዚአብሔር ዳግመኛ በእጃችሁ ይጥላቸዋልና።'),
  ('2a4261ff-e596-5b17-a05a-5313af3e8297', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 15, 15, 'እንዳትፈቱ ሆናችሁ ግዝትን ለምትገዝቱ ለእናንተ ወዮላችሁ! ስለ ኀጢአታችሁም ድኅነት ከእናንተ ራቀ።'),
  ('c8f153ad-da7c-58d7-a1e5-99246abdb278', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 16, 16, 'ለባልንጀራችሁ ክፉ ምላሽ ለምትመልሱ ለእናንተ ወዮላችሁ! እንደ ሥራችሁ መጠን ፍዳውን ትቀበላላችሁና።'),
  ('4a750edd-cc37-5a83-a30b-06e3eb52e835', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 17, 17, 'ሐሰት ለምትመሰክሩ፥ ለበደልም ለምትገቧት ለእናንተ ወዮላችሁ! ፈጥናችሁ ትጠፋላችሁና።'),
  ('83ead9d2-7c3b-595f-aa16-819f9599b782', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 18, 18, 'እናንተ ኃጥኣን፥ ወዮላችሁ! ጻድቃንን ታሳድዱአቸዋላችሁና፥ እናንተም በእነርሱ እጅ ትወድቃላችሁና፥ ከዐመፅም የተነሣ ትሰደዳላችሁና፥ የእነርሱም ቀንበር በእናንተ ይጸናልና።'),
  ('b0ecd46e-97b8-5209-ac27-0cf1f666f92d', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 19, 19, 'ጻድቃን፥ ይህን ተስፋ አድርጉ፤ ኃጥኣን ከፊታችሁ ፈጥነው ይጠፋሉና፥ እንደ ወደዳችሁም ሥልጣን በእነርሱ ላይ ይሆንላችኋልና።'),
  ('6a83b9d9-ce83-5c48-a940-c959d3c80d96', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 20, 20, 'ኃጥኣንም መከራ በሚቀበሉበት ቀን የእናንተ ልጆች እንደ አሞሮች ከፍ ከፍ ይላሉ፤ ይነሣሉ።'),
  ('7b9d395e-e24e-524a-abd3-f0e180f8934c', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 21, 21, 'ማረፊያችሁም ከጥንብ አሞራ ቦታ ይልቅ ይርቃል፤ ወጥታችሁም ከዐመፀኞች ፊት የተነሣ ወደ ጕድጓድና ወደ ዐለቱ ንቃቃት እንደ ሽኮኮ ለዘለዓለም ትገባላችሁ።'),
  ('9ba60b5a-0531-5cf8-a1cc-4a7aab07bdf4', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 22, 22, 'በእናንተም ላይ ይጮኻሉ፤ ይህ ኀጢአታችሁ በእናንተ ምስክር ይሆንባችኋል እንጂ እናንተ እንደ እነርሱ አትሆኑም፤ ከኃጥኣንም ጋር አንድ ሆናችሁ፤ እንደ ሄለይም ያለቅሳሉ።'),
  ('99a001e2-8fdd-5ca4-a6d4-fd9476b3926d', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 23, 23, 'መከራን የምትቀበሉ እናንተ ግን አትፍሩ፤ ድኅነት ይሆንላችኋልና፥ የበራ ብርሃንም ለእናንተ ያበራላችኋልና፥ ከሰማይም የዕረፍት ቃልን ትሰማላችሁና።'),
  ('8907b107-d17d-582f-ab6b-ba7a398bd9bb', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 24, 24, 'ኃጥኣን ወዮላችሁ! ባለጸግነታችሁ ጻድቃንን ያስመስላችኋልና፥ ልቡናችሁም ኃጥኣን እንደ ሆናችሁ ይዘልፋችኋልና።'),
  ('4c1f705f-c0f0-5e5d-a27b-1a8c92179c0e', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 25, 25, 'ይህም ነገር ለክፋታችሁ መታሰቢያ በእናንተ ላይ ምስክር ይሆናል።'),
  ('ce8b42b5-e321-585a-abcb-878adebd7428', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 26, 26, 'የስንዴውን ፍሬ የምትበሉ፥ ከምንጩም መነሻ ኀይልን የምትጠጡ፥ የተዋረዱትንም በኀይላችሁ የምትረጋግጧቸው ወዮላችሁ!'),
  ('836355a6-a082-5912-afc4-e68af78570a8', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 27, 27, 'ሁልጊዜ ውኃን የምትጠጡ ወዮላችሁ! ፍዳን ፈጥናችሁ ትቀበላላችሁና፥ የሕይወትንም ምንጭ ትታችኋልና ፈጽማችሁ ትጠፋላቸሁ።'),
  ('2824cb4c-f8c9-5b56-ad6f-3f44fa133329', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 28, 28, 'ዐመፅንና ሽንገላን፥ ፅርፈትንም የምትሠሩ ወዮላችሁ! ይህም በእናንተ ላይ ለክፋት መታሰቢያ ይሆናል።'),
  ('d3cff715-0bc3-526c-a1d5-9fb2987e78be', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 29, 29, 'ጻድቁን በኀይል የምትቀጠቅጡት ኀያላን ወዮላችሁ! የጥፋታችሁ ቀን ትመጣለችና።'),
  ('893dc79b-8a12-5dbb-a2d9-1b9a5ce7d731', 'c6cae1da-fb1a-529f-a8b0-96d628fec7ce', 'c2e7b310-02f0-5c2b-ac47-7b8a407f8f8c', 30, 30, 'በእነዚያም ወራቶች በፍርዳችሁ ቀን ብዙዎችና ደጎች ወራቶች ለጻድቃን ይመጣሉ።'),
  ('ec7ba67a-af1b-545d-a789-183b0c62bb69', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 1, 1, 'ጻድቃን፥ እመኑ፤ ኃጥኣን ለስድብ ይሆናሉና፥ በዐመፅም ቀን ይጠፋሉና።'),
  ('aefff7cc-7a54-5930-a475-519d6f29f875', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 2, 2, 'ልዑል የእናንተን ጥፋት ያስባልና፥ መላእክትም በሰማይ በእናንተ ጥፋት ላይ ደስ ይላቸዋልና ይህ የታወቀ ይሆንላችኋል።'),
  ('d2221608-2d48-51f6-a120-46c701b5c960', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 3, 3, 'ኃጥኣን፥ ምን ታደርጉ ዘንድ አላችሁ? የጻድቃን የጸሎታቸውን ቃል በምትሰሙበት ጊዜ በዚያች የፍርድ ቀን ወዴት ትሸሻላችሁ?'),
  ('dc400255-8dff-5c32-a34c-35f259801e50', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 4, 4, 'በእነዚያም ወራቶች የቅዱሳን ጸሎት ወደ እግዚአብሔር ትደርሳለች፥ በእናንተ ግን የቅጣታችሁ ወራት ይደርስባችኋል።'),
  ('b9bbdbd2-6cd1-5812-aed0-7f726243e34a', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 5, 5, 'የዐመፃችሁም ነገር ሁሉ በገናናውና በቅዱሱ ፊት ይነበባል፤ ፊታችሁም ያፍራል፤ በዐመፅ የጸና ሥራ ሁሉ ይጣላል።'),
  ('22a02d02-4731-56a6-a574-c64512803459', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 6, 6, 'በባሕርና በየብስ መካከል ያላችሁ፥ ክፉ መታሰቢያችሁም በላያችሁ ያለባችሁ ኃጥኣን ወዮላችሁ!'),
  ('f6414ebf-0a22-5084-ad66-8b7df4191679', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 7, 7, 'በእውነት ያይደለ ብርንና ወርቅን የምትሰበስቡ፥ ባለጸግነትን በለጸግን፤ ገንዘብም በዛልን፤ የወደድነውንም ሁሉ ገንዘብ አደረግን የምትሉ እናንተ፥ ወዮላችሁ!'),
  ('724b7cac-c01d-5b22-aa3a-a60eef5c593e', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 8, 8, 'ብሩን ሰብስበን በሳጥኖቻችን መልተናልና፥ በቤታችንም ያሉ አራሾች እንደ ውኃ በዝተውልናልና አሁን ያሰብነውን እናድርግ የምትሉ እናንተ ወዮላችሁ!'),
  ('4e658b97-41f5-5987-a515-b4c7c36da985', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 9, 9, 'ሐሰታችሁ እንደ ውኃ ይፈስሳል፤ ባለጠግነታችሁ አይኖርላችሁምና፤ ነገር ግን ከእናንተ ፈጥኖ ይጠፋል። ሁሉን በዐመፅ ሰብስባችሁታልና።'),
  ('90754d6b-bcee-5e0a-aad2-cc82f64ed87a', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 10, 10, 'እናንተም ለታላቅ ርግማን ትሰጣላችሁ።'),
  ('ab2a89fd-3cce-54da-a13d-89773d299fa2', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 11, 11, 'ዛሬም እኔ ለብልሆችና ለሰነፎች እምልላችኋለሁ፤ በምድር ላይ ብዙ ነገርን ታያላችሁና።'),
  ('42728f0c-a6db-50bd-ac10-75fb47d726fe', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 12, 12, 'እናንተ ወንዶቹ ከሴቶች ይልቅ ጌጥን ታጌጣላችሁና፥ ይልቁንም ከድንግሊቱ ይልቅ ብዙ መልክ ያለውን ጌጥ ታደርጋላችሁና።'),
  ('88982a9a-598e-5031-ade7-5c817289d2fc', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 13, 13, 'በመንግሥትና በገናናነት፥ በሥልጣንም፥ በብርና በወርቅ፥ በነጭ ሐርም፥ በክብርም ታጌጣላችሁ።'),
  ('bc7957b5-7b12-5280-a667-4fe0915d0e23', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 14, 14, 'መብሎችም እንደ ውኃ ይፈስሳሉ፤ ስለዚህም ትምህርትና ጥበብ የላቸውም።'),
  ('70297efb-4a8b-569b-a316-d2bce36065ad', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 15, 15, 'በዚያም ከገንዘባቸውና ከጌትነታቸው፥ ከክብራቸውም ሁሉ ጋር አንድ ሆነው ይጠፋሉ።'),
  ('3d7a335a-0ba3-5d85-a553-e7efb2d2fc8f', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 16, 16, 'በስድብና በችጋር፥ በታላቅ በቀልም ነፍሳቸው ወደ እሳት ጕድጓድ ትወድቃለች።'),
  ('9f3429bb-3c04-5f28-acaa-227990adca17', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 17, 17, 'ኃጥኣን፥ ተራራው ወንድ ባሪያ እንዳልነበረ፥ እንግዲህም ወዲህ እንደማይሆን፥ ኮረብታም ለሴት ሴት ባሪያ እንዳይደለች ለእናንተ ማልሁላችሁ።'),
  ('5d09072b-7443-55ec-a9ba-7e34b47aa27f', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 18, 18, 'እንደዚሁም ኀጢአት በምድር ላይ አልተላከችም፤ ነገር ግን ሰዎች ከራሳቸው ፈጠሩአት፤ እርሷንም የሠሯት ሰዎች ለታላቅ መርገም ይሆናሉ።'),
  ('e74cd0c0-e6ec-50af-a3be-48d92bdb5a13', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 19, 19, 'ለሴትም ምክነት አልተሰጣትም፤ ነገር ግን በእጅዋ በሠራችው ሥራ ልጅ ሳትወልድ ትሞታለች።'),
  ('c62025ce-f30f-593c-a391-8d0dd9280fad', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 20, 20, 'ኃጥኣን፥ በቅዱሱና በገናናው ማልሁላችሁ፤ ክፉ ሥራችሁ ሁሉ በሰማያት የተገለጠ ነውና፥ የተከደነና የተሰወረ የግፍ ሥራም የላችሁምና።'),
  ('3895a080-161a-58dc-aef5-26ec9be5d6eb', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 21, 21, 'በመንፈሳችሁ አታስመስሉ፤ በሰማይም በልዑል ፊት በየቀኑ ይጻፍ ዘንድ ያለውን ኀጢአታችሁን ሁሉ እንደማታውቁና እንደማታዩ በልቡናችሁ አትናገሩ።'),
  ('187f798f-66e1-5208-a652-24d8813a654c', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 22, 22, 'የምትሠሩትም ግፍ ሁሉ በየቀኑ እስከ ፍርዳችሁ ቀን ይጻፋልና ከዛሬ ጀምሮ ታውቃላችሁ።'),
  ('b9060543-7111-5b7d-a8a1-37fb2cd81b16', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 23, 23, 'ሰነፎች፥ ወዮላችሁ! በስንፍናችሁ ትጠፋላችሁና፥ ጠቢባንንም አትሰሟቸውምና፥ በጎ ነገርም አታገኛችሁምና።'),
  ('9a3ca38d-592e-5763-a47e-30e1208447c4', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 24, 24, 'አሁንም ለጥፋት ቀን የተዘጋጃችሁ እንደ ሆናችሁ ዕወቁ፥ ኃጥኣን ተፈርዶባችሁ ትሄዳላችሁ እንጂ እንድናለን ብላችሁ ተስፋ አታድርጉ።'),
  ('1a94c61c-19b2-504a-a21c-4dffc371fa52', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 25, 25, 'መድንን አታውቁምና ትሞታላችሁ። በነፍሳችሁ ለታላቅዋ የፍርድ ቀን፥ ለታላቅዋ የመከራና የጕስቍልና ቀንም ተዘጋጅታችኋልና።'),
  ('b314a1b5-d465-5b17-aeb9-290223ecd9c5', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 26, 26, 'ክፉ ሥራን የምትሠሩ፥ ብርንዶንም የምትበሉ ልበ ደንዳኖች ወዮላችሁ! በልታችሁና ጠጥታችሁ የምትጠግቡትን መልካሙን ነገር ከየት አገኛችሁ? ልዑል እግዚአብሔር በምድር ላይ ካበዛው መልካም ሁሉ አይደለምን? ነገር ግን ሰላም የላችሁም።'),
  ('9e00ba23-7440-5fe9-a37d-3f17286e6961', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 27, 27, 'የዐመፅን ሥራ የምትወዷት ወዮላችሁ! በጎዋን ነገር ለእናንተ ለምን ተስፋ ታደርጋላችሁ?'),
  ('824dca12-1397-5a10-a432-58e79ed5bf2b', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 28, 28, 'በጻድቃንም እጆች ተላልፋችሁ ትሰጡ ዘንድ እንዳላችሁ ዕወቁ፤ አንገቶቻችሁንም ቈርጠው ይገድሏችኋል፤ አይራሩላችሁምም።'),
  ('687b95bc-4b08-56a4-a5e8-cbe0cf6a8f39', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 29, 29, 'በጻድቃን መከራ ደስ የሚላችሁ ወዮላችሁ! ለእናንተ መቃብር አይቈፈርላችሁምና።'),
  ('bc234d49-76b2-52ee-a2f0-11a42fb65edc', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 30, 30, 'የጻድቃንን ነገር የምትንቁ ወዮላችሁ! የሕይወት ተስፋ አይሆንላችሁምና።'),
  ('dfcf1f78-03c1-5c76-ac88-e46ded156d45', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 31, 31, 'ሐሰት ነገርንና የዝንጉዎችን ነገር የምትጽፉ ወዮላችሁ! እነርሱ ስንፍናን እንዲሰሟትና እንዳይዘነጓት ሐሰታቸውን ይጽፋሉና።'),
  ('c76f403b-9348-5cb3-afa3-3711c899755d', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 32, 32, 'ሰላምም አይሆንላቸውም፤ ነገር ግን ሳይዘገዩ ፈጥነው ሞትን ይሞታሉ።'),
  ('4b3942f2-4513-50b8-ae5f-d0a7bd95395f', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 33, 33, 'ኀጢአትን የምትሠሩ፥ የሐሰትን ነገር የምታመሰግኑና የምታከብሩም ወዮላችሁ! በዚሁም ጠፋችሁ፤ ሕይወትና በጎ ነገርም የላችሁም።'),
  ('35f24b27-9625-5b1b-a4c9-ff473c4e436b', '48e95239-113d-52e1-a8e6-7e15fe015235', '66c5ca1d-a017-5625-afec-fb908606b4d9', 34, 34, 'የቅን ፍርድ ነገሮችን የሚለዋውጡ ወዮላቸው! የዘለዓለም ሥርዐትንም ይለውጣሉ፤ ራሳቸውንም ኀጢአተኞች እንዳልሆኑ የሚያደርጉ በምድር ላይ ይረገጡ ዘንድ አላቸው።'),
  ('7443a1aa-d76a-583a-a1fa-067bafcbfd1e', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 1, 1, 'ጻድቃን፥ በእነዚያ ወራቶች ለመታሰቢያ ጸሎታችሁን ትቀበሉ ዘንድ ተዘጋጁ።'),
  ('0b034c0a-0b54-503a-a9c4-340dfe8946db', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 2, 2, 'ኃጥኣን በልዑል ፊት ኀጢአትን ለመታሰቢያ እንደሚያኖሩት እናንተም በመላእክት ፊት ምስክሮች አድርጋችሁ አኑሯቸው።'),
  ('aa73cdfc-b1fc-5577-a994-eb93f0dd813f', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 3, 3, 'በእነዚያም ወራቶች አሕዛብ ይታወካሉ ፥ በጥፋትም ቀን የአሕዛብ ዘመዶች ይነሣሉ።'),
  ('7f76d89b-461b-5aca-a44c-18814eef9d74', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 4, 4, 'በእነዚያም ወራቶች የተቸገሩ ይወጣሉ፤ ልጆቻቸውንም ይነጥቃሉ፥ ልጆቻቸውንም ይጥሏቸዋል።'),
  ('101df353-8311-5015-ad2e-adcf4ee55324', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 5, 5, 'ከእነርሱም ልጆቻቸውን ያስወርዳሉ፤ እየጠቡም ሳሉ ልጆቻቸውን ይጥሏቸዋል።'),
  ('2ba258f6-4a73-5370-a672-ca5d81ffe171', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 6, 6, 'ወደ እነርሱም አይመለሱም፥ ለሚወዷቸውም አይራሩላቸውም።'),
  ('0eb2569a-b691-5bda-a6c6-b0669f0ac431', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 7, 7, 'ዳግመኛም ለእናንተ ለኃጥኣን እኔ እምልላችኋለሁ፥ የማይገታ ደም ለሚፈስባት ቀን ኀጢአት ተዘጋጅታለችና።'),
  ('230c1462-6d5a-51a8-a464-c45f0525f267', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 8, 8, 'ለድንጋይም ይሰግዳሉ፥ የወርቁንና የብሩን፥ የእንጨቱንና የሸክላውን ምስልም ይሠራሉ።'),
  ('0fbe6922-bae5-5d32-a18c-76232edbc8a2', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 9, 9, 'ለረከሱ መናፍስትና ለክፉዎች አጋንንት፥ ለጣዖቱም ሁሉ፥ ለመስገጃውም ሁሉ ይሰግዳሉ።'),
  ('9641343b-7fb3-5d2b-a7fd-66f4484d69ca', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 10, 10, 'ከእነርሱም ረድኤት ሁሉ አይገኝም፤ ስለ ልቡናቸውም ድንቍርና ይዘነጋሉ፥ በልቡናቸው ፍርሀትም ዐይኖቻቸው ይጋረዳሉ።'),
  ('db1dc96a-4ae7-5a3c-acd4-959ac4284506', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 11, 11, 'ሕልማቸውንም በማየት ይረሳሉ፥ ይፈራሉም፤ ሥራቸውን ሁሉ በሐሰት ሠርተዋልና፥ ለድንጋዩም ሰግደዋልና፥ ፈጥነውም ይጠፋሉና።'),
  ('e756b236-c5ef-5e35-afd9-c763d73551df', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 12, 12, 'በእነዚያም ወራቶች የጥበብን ነገር የሚቀበሉና የሚያውቋት ሁሉ ብፁዓን ናቸው።'),
  ('f2ede3cf-cf4b-5f2d-a4db-2fb53e71c27e', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 13, 13, 'የልዑልንም ሥራዎች ይሠሯቸዋል፥ በጽድቅም መንገድ ይሄዳሉ። እነርሱ ይድናሉና ከሚዘነጉ ሰዎች ጋር አይዘነጉም።'),
  ('aaeeee22-1efc-5131-aa67-0e2873eddf77', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 14, 14, 'ለወንድማችሁ ክፉውን የምትዘረጉ ወዮላችሁ! በሲኦል ትጠፋላችሁና።'),
  ('a566fa36-5f4b-502c-a21e-b35eb28926f2', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 15, 15, 'የኀጢአትንና የተንኰልን መሠረት የምትሠሩ፥ በምድርም ላይ የምታሳዝኑ ወዮላችሁ! በእርሱ ትጠፋላችሁና።'),
  ('f3a844d3-1ce0-5226-af2f-0bc8bd380d34', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 16, 16, 'በባዕድ ገንዘብ ቤታችሁን የምትሠሩ ወዮላችሁ! ሥራቸውም ሁሉ ጡብ ነው፥ የኀጢአትም ድንጋይ ነው፤ ሰላም እንደሌላችሁም እኔ እነግራችኋለሁ።'),
  ('a2407bec-7c05-5435-a270-04916cba3e90', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 17, 17, 'ለዘለዓለም የሚኖር የአባቶቻቸውን ድንበርና ርስት ለሚያፈርሱ ወዮላቸው! ለእነርሱም ዕረፍት አይደረግላቸውምና ልቡናቸውን ወደ ጣዖቱ ይወስዱታል።'),
  ('4558d848-accc-55af-adb1-fb6a3c9be72e', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 18, 18, 'ዐመፅን የምትሠሯትና ግፍን የምትረዷት፥ እስከ ታላቋ የፍርድ ቀንም ድረስ ባልንጀሮቻችሁን የምትገድሉ፥ ወዮላችሁ! ክብራችሁን ይጥላልና፤ በልቡናችሁም ክፋትን ይጨምራልና።'),
  ('e0b88b46-ff56-550e-abc2-8429bf3b6ada', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 19, 19, 'ሁላችሁንም በሰይፍ ያጠፋችሁ ዘንድ የቍጣውን መንፈስ ያስነሣል፥ ቅዱሳንና ጻድቃን ሁሉም ኀጢአታችሁን ያስባሉ።'),
  ('f56e6f44-efbb-5cbb-a238-05524baca874', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 20, 20, 'በእነዚያም ወራቶች አባቶች ከልጆቻቸው ጋር በአንድ ቦታ ይገደላሉ፤'),
  ('f29a71a9-dd6d-562d-a79d-f2057b59635d', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 21, 21, 'ወንድሞች ከወንድሞቻቸው ጋር ደማቸው እንደ ፈሳሽ ውኃ እስኪፈስስ ድረስ በሞት ይወድቃሉ። ሰው ከልጁና ከልጅ ልጁ ይገድለው ዘንድ በመራራት እጁን አይከለክልምና።'),
  ('70dbb501-9e5e-5f8b-afba-43b841ae47ab', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 22, 22, 'ኀጢአተኛውም ከከበረ ወንድሙ እጁን አይከለክልም፥ ከንጋትም ጀምሮ ፀሐይ እስኪገባ ድረስ ይዋጋሉ።'),
  ('f7725094-4f1b-5e60-ae70-5c09c9c280d8', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 23, 23, 'ፈረስም በኃጥኣን ደም ውስጥ እስከ እምቢያጕሱ ድረስ ይሄዳል፥ ሠረገላም እስከ ራሷ ድረስ ትሰጥማለች።'),
  ('7bd0c787-39b5-5997-ad3c-3b179291412e', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 24, 24, 'በእነዚያም ወራቶች መላእክት ወደሚሰወሩበት ቦታ ይወርዳሉ።'),
  ('8880ad5f-0cb0-5234-a801-620a2634092a', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 25, 25, 'ኀጢአትን የሚረዷትንም ሁሉ ወደ አንድ ቦታ ይመልሷቸዋል።'),
  ('90662d38-ee84-5a7e-a46e-93351a9a5c8a', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 26, 26, 'ልዑልም በኃጥኣን ሁሉ ታላቅ ፍርድ ይፈርድ ዘንድ በዚያች ቀን ይነሣል።'),
  ('bb0e59e4-f48b-57d6-a373-ba3abe580d46', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 27, 27, 'ከቅዱሳን መላእክትም በቅዱሳንና በጻድቃን ላይ ጠባቂዎችን ይሰጣል፥ እነርሱም ክፋት ሁሉ፥ ኀጢአትም ሁሉ ጨርሶ እስኪጠፋ ድረስ እንደ ዐይን ብሌን ይጠብቋቸዋል።'),
  ('3206c182-ca7a-558a-aa34-4bd7db099878', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 28, 28, 'ጻድቃን ረዥም እንቅልፍን ቢተኙም የሚፈሩት ነገር የላቸውም።'),
  ('4067bcab-32ea-5ed4-aa48-2fbeeb1678b3', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 29, 29, 'ጠቢባን እውነተኛ ነገርን ያያሉ፤ የዚህ ዓለም ልጆችም የዚችን መጽሐፍ ነገር ሁሉ ያስተውላሉ፥ ባለጸግነታቸውም በኀጢአታቸው በሚወድቁበት ጊዜ ሊያድናቸው እንደማይችል ያውቃሉ።'),
  ('82cb1a68-3fc1-5034-a851-fc6de89d001f', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 30, 30, 'ኃጥኣን፥ በጽኑ መከራ ቀን ጻድቃንን በምታስጨንቋቸው ጊዜ ወዮላችሁ! በእሳትም ታቃጥሏቸዋላችሁ፥ እናንተም እንደ ሥራችሁ ፍዳውን ትቀበላላችሁ።'),
  ('b746b296-4110-54d7-ae96-4d34912faea8', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 31, 31, 'ክፉውን ነገር ልብ ታደርጉ ዘንድ የምትተጉ ልበ ግልብጦች ወዮላችሁ! ፍራትም ያገኛችሁ ዘንድ አላችሁ፥ የሚረዳችሁም የለም።'),
  ('98d8775c-122a-5d4f-a278-0eae7c8cb975', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 32, 32, 'ኃጥኣን፥ ወዮላችሁ! በአፋችሁ ነገር ላይና ሥራን በዘነጋችሁባቸው በእጆቻችሁ ሥራ ላይ በእሳት ወላፈን ትቃጠላላችሁና።'),
  ('0ece1db0-764a-5e13-a557-72f6e85d1cc4', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 33, 33, 'አሁንም ዕወቁ፥ መላእክት በሰማይ ከፀሐይና ከጨረቃ፥ ከከዋክብትም የተነሣ ስለ ኀጢአታችሁ ሥራችሁን ይመራመራሉና።'),
  ('48086255-bdd3-51d2-a67e-d706c043aed0', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 34, 34, 'በምድር ላይ በጻድቃን ዘንድ ፍርድን ታደርጉባቸዋላችሁና ደመናውንና ጉሙን ሁሉ፥ ጠሉንና ዝናቡንም በእናንተ ያዳኝባችኋል፤ ወደ እናንተ እንዳይወርዱ ሁሉ ከእናንተ ይከለከላሉና፥ በኀጢአታችሁም አያስቡምና።'),
  ('2654fa74-dec3-50b9-a99b-715cf44968de', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 35, 35, 'አሁንም ዝናብ ወደ እናንተ መውረድን እንዳይከለከል፥ ጠልም ከእናንተ ወርቅንና ብርን ተቀብሎ እንዲወርድ ለዝናም እጅ መንሻን ስጡ።'),
  ('f62652a4-8343-5ec0-ae3a-d779e2700f13', '5f19f4fe-e150-50ff-af26-9633d88c512e', '75ec6a26-ce78-553b-a0e2-d0666ccc5cc5', 36, 36, 'ውርጭና ዐመዳይ፥ የእነርሱም ቅዝቃዜ፥ የዐመዳይ ነፋሳትም ሁሉ፥ የእነርሱም ጭንቅ ሁሉ ቢወድቁባችሁ በእነዚያ ወራቶች በፊታቸው መቆም አይቻላችሁም።'),
  ('7e8fcd6d-e47d-58d0-a1b0-ac3272fa9011', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 1, 1, 'የሰማይ ልጆች ሁሉ፥ ሰማይን ተረዷት፥ የልዑልንም ሥራ ሁሉ ተረዱ፤ ከእርሱም የተነሣ ፍሩ፤ በፊቱም ክፉ ነገርን አትሥሩ፤ ከእነርሱ የተነሣ ፍሩ።'),
  ('7b8c595f-50d4-59e7-aa1d-91eafbfcaf73', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 2, 2, 'የሰማይ ደጃፍን ቢዘጋ፥ ዝናቡንና ጠሉንም በምድር ላይ እንዳይወርድ በእናንተ ምክንያት ቢከለክል ምን ታደርጉ ዘንድ አላችሁ?'),
  ('7f6d0faf-db1f-5914-ac48-13f809ef569a', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 3, 3, 'መዓቱንም በእናንተ ላይና በሥራችሁ ሁሉ ላይ ቢልክ እርሱን እናንተ የምትማልዱት አይደላችሁምን?'),
  ('45777a9e-fc18-5e1f-a4f4-e07a35f9148b', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 4, 4, 'በቸርነቱ ላይ ታላላቅና የጸኑ ነገሮችን ትናገራላችሁና ሰላም የላችሁም።'),
  ('f81cd24a-8811-5e1b-adcf-dda1e9126043', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 5, 5, 'ከማዕበሉ የተነሣ እንደሚታወኩ፥ መርከቦቻቸውም ከነፋሳት የተነሣ እንደሚነዋወጡና እንደሚጨነቁ በመርከብ የሚሄዱ ነገሥታትን አታይዋቸውምን?'),
  ('27a70eb8-37d2-5291-ab35-51b035fc5ca8', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 6, 6, 'መልካሙ ገንዘባቸውም ሁሉ ከእነርሱ ጋር ወደ ባሕር ይወጣልና ስለዚህ ይፈራሉ።'),
  ('5ea83b6b-2e0b-5221-a3c0-39c548a18dd3', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 7, 7, 'ባሕር ትውጣቸዋለችና፥ በውስጧም ይጠፋሉና በልቡናቸው በጎ ነገርን አያስቡም፤ ባሕሯ ሁሉ፥ ውኃዎችዋም ሁሉ፥ መነዋወጧም ሁሉ የልዑል ሥራ አይደለምን?።'),
  ('a81c3651-a81b-5ad5-a836-4e22e65dba72', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 8, 8, 'እርሱ ሥራዋንና ውኃዎችዋን ሁሉ ወሰነ፥ ሁለመናዋንም በአሸዋ ገደበ።'),
  ('9eeaa796-e4ca-5e7b-a430-0afeb90512f5', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 9, 9, 'በተግሣጹም ፈርታ ትደርቃለች፥ ዓሣዎችዋም ሁሉ ይሞታሉ፥ በውስጧም ያለ ሁሉ ይሞታል።'),
  ('e5c53615-d3d0-51b1-a2b1-92221cf77b9e', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 10, 10, 'በምድር ያላችሁ እናንተ ኃጥኣን ግን አትፈሩትም፤ ሰማይንና ምድርን፥ በውስጣቸው ያለውንም ሁሉ የፈጠረ እርሱ አይደለምን?'),
  ('67f8bc4d-5fad-5bee-ab50-590ccbe225be', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 11, 11, 'በየብስና በባሕር ለሚንቀሳቀሱ ሁሉ ትምህርትንና ጥበብን የሰጠ ማን ነው? በመርከብ የሚሄዱ እነዚያ ባሕርን የሚፈሩ አይደለምን? ኃጥኣን ግን ልዑልን አይፈሩትም።'),
  ('7dba974b-bd5a-51f3-a23e-0a76ec9fd0a3', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 12, 12, 'በእነዚያ ወራቶች አስጨናቂ እሳትን በላያችሁ ቢጨምር ወዴት ትሸሻላችሁ? በየትስ ትድናላችሁ?'),
  ('8ec86b81-c318-5372-a7dd-1a2accf83fd8', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 13, 13, 'ቃሉንም በእናንተ ላይ በሚያኖር ጊዜ የምትደነግጡና የምትፈሩ አይደለምን? ብርሃናትስ ሁሉ በታላቅ ፍርሀት የሚደነግጡና የሚታወኩ አይደለምን?'),
  ('3306bcff-b376-5ce7-a379-630551f2dbde', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 14, 14, 'ምድርስ ሁላ በታላቅ ፍራት የምትደነግጥ፥ የምትንቀጠቀጥና የምትቸኩል አይደለምን?'),
  ('c0bdfe49-a4b9-5aaa-a4b8-d9aa247e3aef', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 15, 15, 'መላእክትም ሁሉ የታዘዙትን ይፈጽማሉ፥ ከክብር ጌታም ፊት ሊሰወሩ ይወዳሉ።'),
  ('590da566-390f-5d58-af61-f3448c68c939', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 16, 16, 'የዓለም ልጆች ይርዳሉ፤ ይታወካሉም፤ እናንተም ኃጥኣን ለዘለዓለም የተረገማችሁ ናችሁ፥ ሰላምም የላችሁም።'),
  ('87c858b9-1d65-5c26-af14-bbd8abd0701c', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 17, 17, 'እናንተ የጻድቃን ነፍሳት፥ አትፍሩ፤ እናንተም በእውነት የሞታችሁ፥ ተስፋ አድርጉ።'),
  ('269b16d6-e7a7-55f2-a6d1-8cfdab57bf46', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 18, 18, 'ነፍሳችሁ በታላቅ መከራና ጩኸት፥ በልቅሶና ኀዘን ወደ ሲኦል ስለ ወረደች አትዘኑ።'),
  ('a044580f-f5e2-5d04-a0c6-b39804a0289b', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 19, 19, 'ሥጋችሁም በሕይወታችሁ እንደ ቸርነታችሁ አላገኘም፤ ነገር ግን ጊዜው ኃጥኣን የተባላችሁበት ነበር፥ የመርገምና የመከራም ጊዜ ነበር።'),
  ('61072777-80f8-59a0-ad34-42f083113f94', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 20, 20, 'በምትሞቱበትም ጊዜ ኃጥኣን በእናንተ ላይ እንዲህ ይላሉ- “ጻድቃን እኛ እንደ ሞትን ሞቱ፥ በሥራቸውስ ጥቅማቸው ምንድን ነው?'),
  ('e52978ff-c7a7-57a5-a181-a714096293a1', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 21, 21, 'እነሆ፥ በኀዘንና በመከራ እንደ እኛ ሞቱ፥ ከእኛስ ብልጫቸው ምንድን ነው? ከዛሬም ጀምሮ ተካከልን፥ ምንስ ያገኛሉ? ለዘለዓለምስ ምን ያያሉ? እነሆ፥ እነርሱ ሞተዋልና፥ ከዛሬም ጀምሮ ለዘለዓለም ብርሃንን አያዩምና።”'),
  ('bbe3ab60-0bde-5f2c-aa1e-3961ff065f24', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 22, 22, 'እናንተ ኃጥኣን፥ እንዲህ እላችኋለሁ- “መብልና መጠጥ ቅሚያና ኀጢአት፥ ሰውን መግፈፍና ገንዘብ ማጠራቀም፥ ደግ ዘመን ማየትም በቃችሁ።'),
  ('0bc64485-1171-5a39-ae65-079a2a7961bf', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 23, 23, 'ፍጻሜያቸው እንዴት ሰላም እንደ ሆነ ጻድቃንን አያችኋቸውን? እስከ ዕለተ ሞታቸው ድረስ ግፍ ሁሉ በእነርሱ ላይ አልተገኘምና።'),
  ('b46255fe-837d-5d8f-a042-bb123617d57d', '7ae07aba-8e92-59a7-a623-36b2105471e9', '6051322e-5536-5b3f-a700-b2e1841a4312', 24, 24, 'ጠፉ፤ ተፈጥረውም እንዳልተፈጠሩ ሆኑ፥ ሰውነቶቻቸውም በመከራ ወደ መቃብር ወረዱ።”'),
  ('61a09857-ec7d-5e92-a323-803097937b15', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 1, 1, 'ዛሬም እኔ በታላቅ ጌትነቱና ክብሩ፥ በከበረ መንግሥቱና በገናናነቱ ለእናንተ ለጻድቃን እምላለሁ።'),
  ('129f229a-f1ee-5cae-a059-569b4f4ce57c', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 2, 2, 'ይህንም ምሥጢር እኔ አውቃለሁና፥ በሰማይ ሰሌዳ ያለውን አንብቤአለሁና፥ ቅዱሳን የጻፉትንም አይቻለሁና እምልላችኋለሁ።'),
  ('8248a6f2-52ec-5e1e-ad7e-9f2bcb3a4ccc', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 3, 3, 'በጎው ነገር ሁሉ፥ ደስታውና ክብሩም ተዘጋጅቶላቸዋልና ስለ እነርሱ በውስጣቸው ተጽፎና ተቀርፆ አገኘሁ።'),
  ('5baca547-e9c8-59e9-a049-782a93843fcd', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 4, 4, 'በእውነትና በቀና ነገር፥ በብዙም በጎነት ለሞቱ ሰዎች ነፍሳት ተጻፈላቸው፤ የድካማችሁም ዋጋ ይሰጣችኋል፤ እድላችሁም ከሕያዋን እድል ይበልጣል።'),
  ('0dd838c5-e36b-5b46-a345-5889de903cf2', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 5, 5, 'ስለ ጽድቅ የሞታችሁ የእናንተ ነፍስ ትድናለች፤ ነፍሶቻቸውም ደስ ይላቸዋል፤ ሐሤትም ያደርጋሉ።'),
  ('fcd96cd2-d407-5b46-a801-47fd2731f67d', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 6, 6, 'መታሰቢያቸውም በእግዚአብሔር ፊት ለልጅ ልጅ ዘመን ይኖራል፤ አሁንም መከራቸውን አትፍሩት።'),
  ('85c29946-07d2-56c2-a5db-cfbd9744d8bf', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 7, 7, 'የሞታችሁ ኃጥኣን፥ በኀጢአታችሁ በምትሞቱበት ጊዜ ወዮላችሁ!'),
  ('45d66626-7686-5283-a2c0-c433809bda13', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 8, 8, 'እንደ እናንተም ያሉ በእናንተ ላይ እንዲህ ይላሉ፤ ኃጥኣን ብፁዓን ናቸው፤ ዘመናቸውን ሁሉ አይተዋልና።'),
  ('776f4409-e3d1-5ef4-afa2-b39e777fe879', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 9, 9, 'ዛሬም በበጎነትና በባለጠግነት ሞቱ፤ መከራውንና ሰልፉንም በሕይወታቸው አላዩም፤ በጌትነትም ሞቱ፤ በሕይወታቸውም ፍርድ አልተደረገባቸውም።'),
  ('39221621-3631-5a4d-af08-d7f91d55321b', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 10, 10, 'ነፍሶቻቸው ወደ ሲኦል እንደሚወርዱ፥ ክፋታቸውም ጽኑ መከራ እንደሚሆንባቸው አታውቋቸውምን?'),
  ('02aae9c6-e3f5-5e2b-a8a3-937c7cb3c425', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 11, 11, 'ሰውነታችሁም በጨለማና በወጥመድ፥ በሚነድ ወላፈንም ወደ ጽኑ ፍርድ ትገባለች፤ ጽኑ ፍርድም በዓለም ትውልድ ሁሉ ትሆናለች።'),
  ('5c0b289c-3a9b-56fd-a190-19a4fdb12c08', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 12, 12, 'ሰላም የላችሁምና ወዮላችሁ! በሕይወት ላሉ ለጻድቃንና ለደጋጎች እንዲህ አትበሉአቸው- “በደከምንበት ወራት ድካምን ደከምን።'),
  ('77e2403a-0398-51a6-af28-c71acca59f5d', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 13, 13, 'መከራውን ሁሉ አየን፤ ብዙ መከራዎችንም ተቀበልን፤ ጨርሰን ጠፋን፤ አነስን፤ ሰውነታችንም አነሰች፤ ጠፋንም።'),
  ('911fd0c8-c95f-5041-a0cd-e00126a8e147', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 14, 14, 'በነገርም የሚረዳን የለም፤ በሥራም ደከምን፤ ምንም አላገኘንም፥ ተጨነቅን፤ ጠፋንም፤'),
  ('f46dd782-0d6c-560b-a71e-f17416ba32fb', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 15, 15, 'ከዛሬ ነገ ሕይወትን እናይ ዘንድ ተስፋ አደረግን፥ ራስ ልንሆን ተስፋ አደረግን፤ ነገር ግን ጅራት ሆን፤ ስንሠራም ደከምን።'),
  ('1140c9df-93ea-56a4-a33a-de21ffd79891', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 16, 16, 'ነገር ግን በድካማችን ላይ ግዳጃችንን አልፈጸምንም፤ ለኃጥኣንም መብሎችን ሆን፤ ዐመፀኞችም ቀንበራቸውን አከበዱብን።'),
  ('cec9f5c1-675c-59ab-a0b6-0e62211ff386', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 17, 17, 'እኛን የሚጠሉንና የሚወጉን በእኛ ሠለጠኑብን፤ ለሚጠሉንም አንገታችንን ዝቅ አደረግን፤ እነርሱ ግን አልራሩልንም።'),
  ('d23a5a5f-0c9a-5d51-a618-feefce32b9a9', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 18, 18, 'ከእነርሱ እንሸሽና እናርፍ ዘንድ እንድንሄድ ወደድን፤ ከእነርሱም ሸሽተን የምንድንበትን አላገኘንም።'),
  ('bcefd9b6-b63f-598a-afac-c39f1a612493', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 19, 19, 'በመከራችን ጊዜ በአለቆች ዘንድ ከሰስናቸው፤ በሚጠሉንም ላይ ጮህን፤ ጩኸታችንን ግን አልሰሙንም፤ ቃላችንንም ሊሰሙን አይወዱም።'),
  ('1d5d6ce9-5bed-5ee8-a158-38299376ebaa', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 20, 20, 'የሚቀሙንን፥ የሚበሉብንን፥ ያጐደሉብንንም ይረዷቸዋል፤ ግፋቸውንም ይሰውሩላቸዋል፤ ቀንበራቸውን ከእኛ አያወጡም፤ ነገር ግን ይበሉናል።'),
  ('ce09691d-a864-56ea-a029-0f01b7804722', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 21, 21, 'ይበትኑናል፤ ይገድሉናል፤ ሞታችንንም ይሰውራሉ፤ እጃቸውንም ከእኛ ላይ ያነሡ ዘንድ አላሰቡም።”'),
  ('ca59f2a1-63f3-5590-acc7-c3bea9d0e7a1', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 22, 22, 'ጻድቃን! እምልላችኋለሁ፤ መላእክት በገናናው ጌትነት ፊት በሰማይ ስለ እናንተ በጎ ያስባሉና።'),
  ('287a3630-6ff9-54b3-a3f4-43359303f57a', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 23, 23, 'ስሞቻችሁም በገናናው ጌትነት ፊት ይጻፋሉ። አስቀድሞ በክፋትና በድካም ጐስቍላችኋልና ተስፋ አድርጉ።'),
  ('5e3bec26-25dd-5a0c-aa5a-f76d521f6c48', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 24, 24, 'አሁንም እንደ ሰማይ ብርሃን አብርታችሁ ትታያላችሁ፤ የሰማይ ደጃፍም ይከፈትላችኋል።'),
  ('8f814df8-36a2-5a0f-a6b7-ec46e1de4f58', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 25, 25, 'ጩኸታችሁ ይሰማል፤ ለፍርድ ጩኹ፤ ይገለጥላችሁማል፤ ችግራችሁም ሁሉ ከመላእክትና የሚነጥቋችሁን ከሚረዷቸው ሁሉ ይመረመራልና።'),
  ('0a978889-3f0e-5f8f-a1db-da4e79392cd3', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 26, 26, 'እንደ መላእክት በሰማይ ታደርጓት ዘንድ ታላቅ ደስታ ትሆንላችኋለችና ተስፋ አድርጉ፤ ተስፋችሁንም አትተዉ፥ በታላቋ የፍርድ ቀንም ትሰወሩ ዘንድ ያላችሁ አይደለም።'),
  ('05066703-a419-510b-a70b-57d6606b40ef', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 27, 27, 'እንደ ኃጥኣንም ሁናችሁ አትገኙም፤ ከእናንተ ወዲያ የዘለዓለም ፍርድ ለዓለም ትውልድ ሁሉ ትሆናለች።'),
  ('152955e0-e0f1-5e27-aefb-54b626c7424b', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 28, 28, 'አሁንም ጻድቃን! ኃጥኣንን በፈቃዳቸው ጸንተውና ተዘጋጅተው በምታይዋቸው ጊዜ አትፍሩ።'),
  ('e2e525ef-1480-5c65-ae8f-b93c620897a9', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 29, 29, 'ከሰማይ ሠራዊት ጋር አንድ ትሆኑ ዘንድ አላችሁና ከእነርሱ ግፍ ራቁ እንጂ ከእነርሱ ጋራ አትተባበሩ።'),
  ('995cca18-b7a5-5093-a2c1-e7d31ac4778a', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 30, 30, 'እናንተ ኃጥኣን! ኀጢአታችን ሁሉ አይመረመርም፤ አይጻፍብንም፥ ትላላችሁ፥ ነገር ግን ኃጢአቶቻችሁ ሁሉ በየቀኑ ይጻፉ ዘንድ አላቸው።'),
  ('2abe037c-4121-5c2d-a14f-fe9173906ba6', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 31, 31, 'አሁንም ብርሃንና ጨለማ፥ ቀንና ሌሊት ኀጢአታችሁን ሁሉ ይገልጡባችኋልና እኔ አሳያችኋለሁ፤ በልቡናችሁም አትዘንጉ፤ አቷሹም።'),
  ('5eac2e35-c22a-5adb-a74e-dd39e49a1354', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 32, 32, 'የፍርድንም ነገር አትመልሱት፤ የቅዱሱንና የገናናውንም ነገር ሐሰት አታድርጉት፤ ጣዖታችሁንም አታክብሩት፥ ሐሰታችሁ ሁሉ፥ ዝንጋታችሁም ሁሉ ለታላቅ ኀጢኣት እንጂ ለጽድቅ አይደለችምና።'),
  ('4aeaa896-0e34-53ca-a93c-44b999e1246f', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 33, 33, 'ዛሬም እኔ ይህን ምሥጢር ዐውቀዋለሁ፤ ብዙዎች ኃጥኣን የፍርድን ነገር ይመልሳሉና፥ ይገለብጡማልና።'),
  ('447dede8-035b-5b2a-ade2-64a73539878e', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 34, 34, 'ክፉዎችንም ነገሮች ይናገራሉ፤ ታላላቅ ልብ ወለድንም በሐሰት ፈጥረው ይናገራሉ፤ በነገራቸውም ላይ መጻፎችን ይጽፋሉ።'),
  ('baa90c1e-20b0-50ad-a253-e01d0f68d371', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 35, 35, 'ነገር ግን ነገሮቼን ሁሉ በቅንነት በአንደበቶቻቸው ቢጽፉ ኖሮ፥ ከነገሮቼም በአይለውጡና በአያጐድሉም ስለ እነርሱ አስቀድሜ ያዳኘሁባቸውን ሁሉ በቅንነት በጻፉ ነበር።'),
  ('dd3d64e2-ad08-5017-a119-fd03e589ca08', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 36, 36, 'ሌላ ምሥጢርንም ዐውቃለሁ፤ ለጻድቃንና ለጠቢባን ስለ ደስታና ስለ ቅን ፍርድ፥ ስለ ብዙ ጥበብም መጻሕፍት ይሰጧቸዋልና፤'),
  ('6a0360b3-a264-538c-a86f-013c6e7081de', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 37, 37, 'ለእነርሱም መጻሕፍት ይሰጣሉ፤ እነርሱም ያምኑባቸዋል፤ በእነርሱም ደስ ይላቸዋል፤ ሐሤትም ያደርጋሉ፤ ከእነርሱም የእውነት መንገዶችን ሁሉ ያወቁ ጻድቃን ሁሉ ዋጋቸውን ያገኛሉ።'),
  ('5dbffbf3-4e73-5d8f-a958-fbd198d927f2', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 38, 38, 'በእነዚያም ወራቶች ጌታ እንዲጠሯቸውና ጥበባቸውን ለምድር ልጆች እንዲያሰሙ እንዲህ አለ-'),
  ('862d4a36-cdb5-5e6c-ad9c-61fac6e52bad', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 39, 39, '“እናንተ መሪዎቻቸው ናችሁና፥ በምድርም ሁሉ ላይ ስጦታዎች ናችሁና አሳዩአቸው።'),
  ('593082c2-bd22-5cb1-a0c6-daa89b5630e1', '45bc7009-d878-51af-a7cc-86faa1ec7b72', '2d899106-8c89-52ad-a717-4c8c1d34617c', 40, 40, 'እኔና ልጄ በእውነት መንገዶች በሕይወታቸው ከእነርሱ ጋር ለዘለዓለም አንድ እንሆናለን፤ ሰላምም ይሆንላችኋል፤ የእውነት ልጆች! በእውነት ደስ ይበላችሁ።”'),
  ('8fd41230-9062-56de-ab1c-39f08f4912d6', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 1, 1, 'ከብዙ ቀንም በኋላ ልጄ ማቱሳላ ለልጁ ላሜህ ሚስት አጋባው፤ ከእርሱም ፀንሳ ወንድ ልጅን ወለደች።'),
  ('ee377ded-ad14-56fb-a63b-6a844baad41a', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 2, 2, 'ሰውነቱም እንደ በረዶ ነጭ ሆነ፥ እንደ ጽጌረዳም ቀይ ነው፤ የራሱም ጠጕር እንደ ባዘቶ ነጭ ነው፤ የተሸራሸም ነው፤ ዐይኖቹም ያማሩ ናቸው።'),
  ('1d41085c-8e8c-56cb-a35d-fcd858bd9a3a', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 3, 3, 'ዐይኖቹንም በገለጠ ጊዜ ቤቱን ሁሉ እንደ ፀሐይ አበራ፤ ቤቱም ሁሉ ፈጽሞ በራ፤ ከአዋላጂቱም እጅ በተነሣ ጊዜ አፉን ከፈተ፤ የጽድቅ ጌታንም ክብር ተናገረ።'),
  ('9bf8fbb4-f97c-560f-aae1-b149bdcaf266', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 4, 4, 'አባቱ ላሜህም ከእርሱ የተነሣ ፈርቶ ሸሸ፥ ወደ አባቱም ወደ ማቱሳላ መጣ፤ እንዲህም አለ- “እኔ ልውጥ ልጅ ወለድሁ፤ እንደ ሰውም አይደለም።'),
  ('adb4ff02-046a-567d-aac7-972bc7b88b4e', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 5, 5, 'የሰማይ መላእክት ልጆችንም ይመስላል፤ ፍጥረቱም ልዩ ናት፤ እንደ እኛም አይደለም፤ ዐይኖቹም እንደ ፀሐይ ጨረር ናቸው፤ ፊቱም የበራ ነው።'),
  ('7395b828-d88f-51d0-a74a-0bcb45e41ecf', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 6, 6, 'ከመላእክት ነው እንጂ ከእኔ ያልተወለደ ይመስለኛል፥ እኔስ በምድር ላይ በዘመኑ ድንቅ ሥራ እንዳይሠራ ብዬ እፈራለሁ።'),
  ('3914695a-722a-5e9d-ad1a-fcf9d59ed3ee', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 7, 7, '“አሁንም አባቴ ወደ አባታችን ወደ ሄኖክ ትሄድና እውነቱን ከእርሱ ትሰማ ዘንድ እማልድሃለሁ፤ እለምንሃለሁም። መኖሪያው ከመላእክት ጋር ነውና።”'),
  ('5c11a270-f2a4-5b23-a3ac-bf648b4afae5', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 8, 8, 'ማቱሳላም የልጁን ነገር በሰማ ጊዜ እኔ በዚያ እንደ አለሁ ሰምትWaልና ወደ ምድር ዳርቻ ወደ እኔ መጣ።'),
  ('75ddd9cf-3b22-5c5d-a7fb-0de4abdc65c2', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 9, 9, 'ጮኸ፤ እኔም ቃሉን ሰማሁት። ወደ እርሱም መጣሁ፤ “ወደ እኔ መጥተሃልና ልጄ፥ እነሆ፥ አለሁ” አልሁት።'),
  ('5edc1873-5073-5d7f-ae38-3f96ed0fe88e', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 10, 10, 'እርሱም መለሰልኝ፥ እንዲህም አለኝ- “ስለ ታላቁ ነገርና ስለ ቀረብሁበት አስጨናቂ ራእይ ወደ አንተ መጣሁ።'),
  ('fa21283e-30e8-53e8-ae64-c5a0582b013e', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 11, 11, 'አሁንም አባቴ ሆይ! ስማኝ፤ መልኩና ፍጥረቱ እንደ ሰው ፍጥረት ያልሆነ፥ መልኩም ከበረዶ ይልቅ የሚነጣ፥ ከጽጌረዳም የሚቀላ፥ የራሱም ጠጕር ከነጭ ባዘቶ ይልቅ የሚነጣ፥ ዐይኖቹም እንደ ፀሐይ ጨረር የሚያበሩ ልጅ ለልጄ ለላሜህ ተወልዷልና።'),
  ('9bef8515-5cac-5abd-a335-e00c0d1b1afd', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 12, 12, 'ዐይኖቹንም በገለጠ ጊዜ ቤቱን ሁሉ አበራ፤ ከአዋላጂቱም እጅ ተነሣ፤ አፉንም ፈትቶ የሰማይን ጌታ አመሰገነው።'),
  ('26b00f02-265e-59ab-a2db-5673e98f4cea', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 13, 13, 'አባቱ ልጄ ላሜህም ፈርቶ ወደ እኔ ሸሸ፤ ከሰማይ መላእክት የተወለደ አስመሰለው እንጂ ከእርሱ እንደ ተወለደ አላመነም።'),
  ('9743368e-529e-58c9-ae69-0e9d95873837', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 14, 14, 'እነሆም፥ እውነቱን ትነግረኝ ዘንድ እኔ ወደ አንተ መጣሁ።”'),
  ('96af6b01-a3a2-5d93-abe4-ac793ed5348f', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 15, 15, 'እኔም ሄኖክ ስለ እርሱ መለስሁ፥ እንዲህም አልሁት- “እግዚአብሔር በምድር ላይ አዲስ ነገርን ያደርጋል፤ የአባቴ የያሬድ የልጁ ወገኖች ከሰማይ በላይ ያለ የጌታን ቃል ተላልፈዋልና ይህን በራእይ ፈጽሜ አይቼ ነገርሁህ።'),
  ('7adc4ec6-872d-55c6-a52a-d37836f9e1f8', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 16, 16, 'እነኋቸው፥ ኀጢአትን ይሠራሉ፤ ሥርዐቱንም ይተላለፋሉ፤ ከሴቶችም ጋር አንድ ሆኑ፤ ከእነርሱም ጋር ኀጢአትን ይሠራሉ፤ ከእነርሱም ሚስቶችን አገቡ፤ ከእነርሱም ልጆችን ወለዱ፤ በምድርም ሁሉ ላይ ታላቅ ጥፋት ይደረጋል።'),
  ('24bce74c-53fd-5cf3-a1a2-fa8e5cbdeb3c', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 17, 17, 'የጥፋት ውኃም ይወርዳል፤ ታላቁም ጥፋት በአንዱ ዓመት ይደረጋል፤ ለእናንተም የተወለደው ልጅ ይህ ነው፤ እርሱ በምድር ላይ ይቀራል፤ ሦስቱ ልጆቹም ከእርሱ ጋራ ይድናሉ።'),
  ('d05739d6-0e54-5ed2-a5cb-d0310f53d5f1', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 18, 18, 'በምድር ላይ ሰው ሁሉ በሚሞትበት ጊዜ እርሱ ይድናል፤ ልጆቹም አርበኞችን ይወልዳሉ፥ እነዚህም ሥጋውያን እንጂ መንፈሳውያን አይደሉም።'),
  ('81797a50-2a96-542f-a2b6-f4fe72c237ba', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 19, 19, 'ታላቅ መቅሠፍትም በምድር ላይ ይደረጋል፤ ምድርም ከጥፋት ሁሉ ትነጻለች።'),
  ('dd9ef1cb-f5bc-5155-ad4b-c1eae467e27a', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 20, 20, '“አሁንም ይህ የተወለደ ልጅ በእውነት የእርሱ ልጅ እንደ ሆነ ለልጅህ ለላሜህ ንገረው፤ እርሱም ቀሪ ይሆንላችኋልና ስሙን ኖኅ ብለህ ጥራው፤ በእርሱ ዘመን በምድር ላይ ትፈጸም ዘንድ ካላት ከኀጢአት ሁሉና ከዐመፅ ሁሉ የተነሣ ወደ ምድር ከምትመጣ ጥፋት እርሱና ልጆቹ ይድናሉ። ከዚህም በኋላ በምድር ላይ አስቀድማ ከተፈጸመችው ይልቅ ፈጽማ የምትበልጥ ዐመፅ ትደረጋለች፤ የቅዱሳንን ምሥጢራት ዐውቃለሁና። እርሱ እግዚአብሔር ገልጦልኛልና፥ አስረድቶኛልምና፤ በሰማይ ሰሌዳም አነበብሁ፤ አስተዋልሁም።'),
  ('24dedd60-0ed0-591d-a06b-1681cc72f0c7', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 21, 21, '“እውነተኛ ትውልድ እስክትነሣ ድረስ ትውልድ ከትውልድ ይልቅ አብልጣ ትበድላለችና በእነርሱ ላይ የተጻፈውን አየሁ፤ በደልም ትጠፋለች፤ ኀጢአትም ከምድር ላይ ትርቃለች፤ በጎውም ነገር ሁሉ በእርሷ ላይ ይመጣል፤ አሁንም ይህ የተወለደው ልጅ በእውነት የእርሱ ልጅ ነውና፥ ሐሰትም አይደለምና ሄደህ ለልጅህ ለላሜህ ንገረው፤” ማቱሳላም የአባቱ የሄኖክን ነገር በሰማ ጊዜ ሥራውን ሁሉ በስውር አሳይቶታልና ነገሩን ሰምቶ ተመለሰ።'),
  ('ea4ec60c-fa0d-578f-a8dd-3299866cae8e', '72e254a2-f841-524d-ac86-9d8bd554fd2b', '021deca2-d3f4-5882-ae7c-b3ee5515e058', 22, 22, 'እርሱም ምድርን ከጥፋቷ ሁሉ ያሳርፋታልና የዚያን ልጅ ስም ኖኅ አለው።'),
  ('f595a26f-a060-5fb1-a5b4-f58202511caf', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 1, 1, 'ለልጁ ለማቱሳላ፥ ከእርሱም በኋላ ለሚመጡና በኋላ ዘመን ሥርዐቱን ለሚጠብቁ ሰዎች ሄኖክ የጻፈው ሁለተኛ መጽሐፍ ይህ ነው።'),
  ('d79c4ee5-9764-560c-a292-3b9d640f1dc3', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 2, 2, 'ክፉውን ሥራ የሚሠሩ ሰዎች እስኪጨረሱ ድረስ፥ የበደለኞችም ሠራዊት እስኪፈጸም ድረስ መልካም የሠራችሁ እናንተ፥ በእነዚያ ወራቶች ትቈያላችሁ።'),
  ('ee4ebcdb-8c27-5ebb-a577-04ca564a2559', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 3, 3, 'እናንተ ግን ኀጢአት እስክታልፍ ድረስ ደጅ ጥኑ። ስማቸው ቅዱሳን ከተጻፉበት መጽሐፍ ይፋቅ ዘንድ አለውና፥ ዘራቸውም ለዘላለም ይጠፋልና። ልጆቻቸውም ይሞታሉ፥ በማይታይም ምድረ በዳ ጮኸው ያለቅሳሉ፤ በእሳትም ይቃጠላሉ፥ በዚያ ምድር የለምና።'),
  ('df991ea1-d69e-5628-a8f3-98f08fbc8c37', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 4, 4, 'የእሳቱም ወላፈን ሲነድ አየሁት፥ የሚበራም ነበር፤ እንደሚያበሩ ተራሮችም የተከበቡ ነገሮች ነበሩ፥ ወዲያና ወዲህም ይታወካሉ።'),
  ('d33e7e0a-9f54-5a08-afdb-6c03ebfec135', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 5, 5, 'ከእኔ ጋር ካሉ ከቅዱሳን መላእክት አንዱን ጠየቅሁት፥ እንዲህም አልሁት- “ይህ የሚያበራው ምንድን ነው? ሰማይ አይደለምና፥ ነገር ግን ብቻውን የሚነድድ የእሳት ወላፈን፥ የጩኸትና የልቅሶ፥ የዋይታና የብርቱ ሕማም ቃል ነው።”'),
  ('56ede424-7128-50d4-a848-204e5df4ca5d', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 6, 6, 'እርሱም እንዲህ አለኝ- “ይህ የምታየው ቦታ የኃጥኣንና የተሳዳቢዎች፥ ኀጢኣትን የሚሠሩ፥'),
  ('2dbf661a-a9f5-5994-aee0-c8f60f89defe', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 7, 7, 'እግዚአብሔር በነቢያት አንደበት ያናገራቸውን በምድር ላይ ይደረጉ ዘንድ ያላቸውን ሁሉ የሚለውጡ ሰዎች ነፍሳት የሚጣሉበት ቦታ ነው።'),
  ('db2b441e-23d0-5875-a356-59a40fca423a', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 8, 8, 'መላእክት ያነብቧቸው ዘንድ፥ በኃጥኣንና በተዋረዱትም ሰዎች መናፍስት ይደርስባቸው ዘንድ ያለውን ያውቁ ዘንድ ከእነርሱ ወገን በላይ በሰማይ የተጻፉና የተቀረጹ አሉና።'),
  ('b92feb68-4d75-59ea-ad71-81da2903aba5', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 9, 9, 'ነገር ግን ሥጋቸውን መከራ ያስቻሉ፥ ከፈጣሪም ዘንድ ዋጋ የተቀበሉ፥ ከክፉ ሰዎችም የተነሣ የተዋረዱ፥ ፈጣሪያቸውንም የወደዱ ወርቅና ብርን፥ በዚህም ዓለም ያለውን በጎ ነገር ሁሉ አይወዱም፤ ነገር ግን ሥጋቸውን ለመከራ ሰጡ፤ ከተፈጠሩም ጀምሮ በዚህ ዓለም ያሉ መብሎችን ያልተመኙ ራሳቸውን እንደ ሞተች ሰውነት አደረጉ። ይህንም ጠበቁ፥ ጌታም ብዙ ጊዜ ፈተናቸው፤ ስሙንም ያመሰግኑ ዘንድ ሰውነቶቻቸው በንጽሕና ተገኙ።'),
  ('1a2a7da0-d4a6-5388-adf0-da758e131ceb', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 10, 10, 'በረከታቸውንም ሁሉ በመጻሕፍት ተናገርሁ፤ እኒህ ከዘለዓለማዊ ሕይወታቸው ጀምሮ ሰማያዊውን ሲወዱት፥'),
  ('b73d1d83-1f9b-5d8c-a666-6f482c42510f', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 11, 11, 'ከክፉ ሰዎችም መከራን ሲቀበሉ፥ ከእነርሱም ተግዳሮትንና ስድብን ሲሰሙ፥ እያመሰገኑኝም ሲጐሳቈሉ ተገኝተዋልና ለእየራሳቸው ዋጋቸውን ሰጣቸው።'),
  ('fdc3c434-1409-5d35-ab54-3dc33535c0b9', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 12, 12, 'አሁንም ከብርሃን ልጆች የተወለዱ የደጎችን ነፍሳት እጠራለሁ፥ ለሃይማኖታቸው እንደሚገባ በሥጋቸው ክብርን ላልተቀበሉና በጨለማ ለተወለዱ እለውጣለሁ።'),
  ('99b9e12f-f3fa-5eb2-a923-f69f0b1ffbbf', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 13, 13, 'ቅዱስ ስሜንም የወደዱትን በብሩህ ብርሃን አወጣቸዋለሁ፤ እያንዳንዱንም እንደ ክብሩ በክብር ዙፋን አስቀምጠዋለሁ፥ የአምላክም ፍርድ እውነት ነውና ቍጥር በሌላቸው ዘመኖች ያበራሉ።'),
  ('54204814-ef5c-5604-aa65-a552bbfcf8c6', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 14, 14, 'በቅን መንገዶች ማደሪያ ለምእመናን ሃይማኖትን ይሰጣቸዋልና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('67695d05-49d5-5868-a196-304d2d1d83ce', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 15, 15, 'ጻድቃን እያበሩ በጨለማ የተወለዱትን በጨለማ ሲጣሉ ያዩአቸዋል፤ ኃጥኣንም እየጮኹ ጻድቃንን ሲያበሩ ያዩአቸዋል።'),
  ('3def85ab-0034-53f3-a7b4-08be7b1e87a1', 'ce8d8e4e-b079-5cc8-a858-d0e2a4d357bd', 'd02c4642-ffb4-5126-a0d9-952b190c7c76', 16, 16, 'እነርሱም በተጻፉላቸው ቀኖችና ዘመኖች ይኖራሉ።'),
  ('b3bbe7e8-70dd-591f-a950-1e748b622a74', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 1, 1, 'በኤርምያስ አፍ የተናገረው የእግዚአብሔር ቃል ከተፈጸመ በኋላ በፋርስ ንጉሥ በቂሮስ በመጀመሪያው ዓመት እግዚአብሔር የፋርስን ንጉሥ የቂሮስን መንፈስ አስነሣ፤ እርሱም በመንግሥቱ ሁሉ አዋጅ አስነገረ፤ ደግሞም በጽሕፈት እንዲህ አለ፦'),
  ('c20d93dc-8e24-5f9e-a88e-5ad031f36fe2', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 2, 2, '“የፋርስ ንጉሥ ቂሮስ እንዲህ ይላል፦ የሰማይ አምላክ እግዚአብሔር የምድርን መንግሥታት ሁሉ ሰጥቶኛል፤ በይሁዳም ባለችው በኢየሩሳሌም ቤትን እሠራለት ዘንድ እንዳስብ አደረገኝ፤'),
  ('671a3e9d-09c4-5a8e-a020-3056c8e58b84', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 3, 3, 'ከሕዝቡ ሁሉ በእናንተ ዘንድ ማንም ቢሆን አምላኩ ከእርሱ ጋር ይሁን፤ እርሱም በይሁዳ ወዳለችው ወደ ኢየሩሳሌም ይውጣ፤ በኢየሩሳሌምም ለሚኖረው አምላክ፥ ለእስራኤል አምላክ ለእግዚአብሔር ቤትን ይሥራ፤'),
  ('6596ce65-7870-512d-ae88-8d85617744b2', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 4, 4, 'በስደት በሚኖርባቸው ከተሞች ሁሉ ለቀረው ሰው ሁሉ የሀገሩ ሰዎች በብርና በወርቅ፥ በዕቃም፥ በእንስሳም ይርዱት፤ ይህም በኢየሩሳሌም ላለው ለእግዚአብሔር ቤት በፈቃዳቸው ከሚያቀርቡት ሌላ ይሁን።”'),
  ('b12e5c74-61d1-518b-a99e-7c2af30b684f', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 5, 5, 'የይሁዳና የብንያም የአባቶች ቤቶች አለቆችም፥ ካህናቱም፥ ሌዋውያኑም፥ በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ለመሥራት ይወጡ ዘንድ እግዚአብሔር መንፈሳቸውን ያነሣሣው ሁሉ ተነሡ።'),
  ('30903e28-5963-5f35-a3d7-fc61751caf03', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 6, 6, 'በዙሪያቸውም ያሉ ሁሉ በፈቃዳቸው ካቀረቡት ሁሉ ሌላ በብር ዕቃና በወርቅ፥ በገንዘቦችና በእንስሶች፥ በሌላም ስጦታ ይረዷቸው ነበር።'),
  ('ae316c08-8bbd-51c5-a1be-f5a256fb4fe0', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 7, 7, 'ንጉሡ ቂሮስም ናቡከደነፆር ከኢየሩሳሌም ወስዶ በአምላኩ ቤት ያኖራቸውን የእግዚአብሔርን ቤተ መቅደስ ዕቃዎች አወጣ።'),
  ('82fd5cb5-0977-500e-a491-fe00687a9656', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 8, 8, 'የፋርስ ንጉሥ ቂሮስም የመዝገብ ሐላፊ በነበረው በሚትሪዳጡ እጅ አወጣቸው፤ ለይሁዳም መስፍን ለሲሳብሳር ቈጠራቸው።'),
  ('20deb15b-be25-5d19-a163-d74483831415', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 9, 9, 'ቍጥራቸውም ይህ ነው፤ ሠላሳ የወርቅ ሳሕኖች፥ አንድ ሺህም የብር ሳሕኖች፥ ሃያ ዘጠኝም ቢላዋዎች፥ ሠላሳ የወርቅ ዳካዎች፥'),
  ('df04e1c4-7b20-5845-a60e-febd6d84c76f', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 10, 10, 'አራት መቶ ዐሥርም ሌላ ዓይነት የብር ዳካዎች፥ አንድ ሺህም ሌላ ዕቃ ነበረ።'),
  ('90490515-e6e5-54d9-af56-86c73d93c152', 'e16a93e3-d8e9-53cb-a86d-22f33ac90a57', 'c9873348-813e-5574-ae8c-40fc70e8599f', 11, 11, 'የወርቁና የብሩ ዕቃዎች ሁሉ አምስት ሺህ አራት መቶ ነበሩ፤ እነዚህንም ሁሉ ሲሳብሳር ከባቢሎን ወደ ኢየሩሳሌም ከተመለሱ ምርኮኞች ጋር ወሰደ።'),
  ('aca7fd01-e764-52b3-aa88-42d3b1c0cfe2', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 1, 1, 'የባቢሎንም ንጉሥ ናቡከደነፆር ወደ ባቢሎን ከማረካቸው ምርኮኞች ወደ ኢየሩሳሌምና ወደ ይሁዳ፥ ወደ እየከተማቸው የተመለሱት የሀገር ልጆች እነዚህ ናቸው።'),
  ('d70249cf-ffc1-5ae2-a0d0-9387239d9a91', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 2, 2, 'ከዘሩባቤል፥ ከኢያሱ፥ ከነህምያ፥ ከሠራያ፥ ከሮሃልያ፥ ከመርዶክዮስ፥ ከበላሳን፥ ከመሴፋር፥ ከበጎዋይ፥ ከሬሁም፥ ከበዓና ጋር መጡ። የእስራኤልም ሕዝብ ሰዎች ቍጥር ይህ ነው፤'),
  ('61efc104-481a-5d3c-af0b-4ceadfe9a630', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 3, 3, 'የፋሮስ ልጆች ሁለት ሺህ መቶ ሰባ ሁለት።'),
  ('093e20dd-6e82-583e-a2b8-201a0a2c9044', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 4, 4, 'የሰፋጥያስ ልጆች ሦስት መቶ ሰባ ሁለት።'),
