  ('68a02bc4-cb2a-5e8b-a4d6-6f35f95d3b73', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 53, 53, 'የበርቆስ ልጆች፥ የሲሣራ ልጆች፥ የቴማ ልጆች፥'),
  ('cec0eb47-45b6-5371-ac6a-838e5ec80239', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 54, 54, 'የንስያ ልጆች፥ የአጡፋ ልጆች።'),
  ('afbeeb50-218a-5867-a4ff-b6aaac9c393f', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 55, 55, 'የሰሎሞን አገልጋዮች ልጆች፤ የሳጢ ልጆች፥ የሰፌርታ ልጆች፥ የፋዱርሓ ልጆች፤'),
  ('f378769e-6ba4-5463-a8fc-decbc3bd3cfe', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 56, 56, 'የኢያሔል ልጆች፥ የደርቆን ልጆች፥ የጌዴል ልጆች፤'),
  ('e7b07bac-ac04-511d-a58e-63e715163033', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 57, 57, 'የሰፋጥያስ ልጆች፥ የአጤል ልጆች፥ የፎኬርት ልጆች፥ የሐፂባይም ልጆች፥ የአሚ ልጆች።'),
  ('2b4d7bef-7f43-5238-a40a-f975b7ce0152', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 58, 58, 'እነዚህ ናታኒም ሁሉና የሰሎሞን አገልጋዮች ልጆች ሦስት መቶ ዘጠና ሁለት ነበሩ።'),
  ('35bbc062-2807-5897-a07e-03b05352feff', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 59, 59, 'ከቲልሜላ፥ ከቴላርሳ፥ ከክሩብ፥ ከሐዳን፥ ከኤሜር የወጡ እነዚህ ነበሩ፤ ነገር ግን የአባቶቻቸውን ቤቶችና ዘራቸውን ወይም ከእስራኤል ወገን መሆናቸውን ያስታውቁ ዘንድ አልቻሉም፤'),
  ('d8cdb6e7-2494-5f9a-aeed-4da242ddbadd', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 60, 60, 'የዳላያ ልጆች፥ የጦብያ ልጆች፥ የኒቆዳ ልጆች፥ ስድስት መቶ አምሳ ሁለት ነበሩ።'),
  ('7e00cb9b-f324-5c93-adab-0c9dadb26676', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 61, 61, 'ከካህናቱም ልጆች፤ የአብያ ልጆች፥ የአቆስ ልጆች፥ ከገለዓዳዊው ከቤርዜሊ ልጆች ሚስት ያገባ፥ በስማቸውም የተጠራ የቤርዜሊ ልጆች።'),
  ('7a10fd6f-33e6-5e6b-a263-b600a24eb8c8', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 62, 62, 'እነዚህ በትውልድ መጽሐፍ ትውልዳቸውን ፈለጉ፤ ነገር ግን አልተገኘም፤ ከክህነትም ተከለከሉ።'),
  ('ee6d1383-ee46-5fc5-a3a1-c47c3304c8e1', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 63, 63, 'ሐቲርሰስታም፥ “በኡሪምና በቱሚም የሚፈርድ ካህን እስኪነሣ ድረስ ከቅዱሰ ቅዱሳኑ አትበሉም” አላቸው።'),
  ('766b8032-6df6-56c2-affb-ac165c92d38e', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 64, 64, 'ጉባኤው ሁሉ አርባ ሁለት ሺህ ሦስት መቶ ስድሳ ነበሩ።'),
  ('9d59ddbc-7b4a-59e6-a225-bfda63019291', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 65, 65, 'ይኸውም ሰባት ሺህ ሦስት መቶ ሠላሳ ሰባት ከነበሩ ከሎሌዎቻቸውና ከገረዶቻቸው ሌላ ሁለት መቶ ወንዶች መዘምራንና ሴቶች መዘምራትም ነበሩአቸው።'),
  ('c00c7100-7073-5b28-a608-3b3f684e1222', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 66, 66, 'ፈረሶቻቸውም ሰባት መቶ ሠላሳ ስድስት፥ በቅሎዎቻቸውም ሁለት መቶ አርባ አምስት፥'),
  ('ac39c2b9-4528-5907-a15c-a95d8677df46', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 67, 67, 'ግመሎቻቸውም አራት መቶ ሠላሳ አምስት፥ አህዮቻቸውም ስድስት ሺህ ሰባት መቶ ሃያ ነበሩ።'),
  ('37ac27c8-4b23-55b2-ae59-3cf9fcbf3339', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 68, 68, 'በኢየሩሳሌምም ወዳለው ወደ እግዚአብሔር ቤት በመጡ ጊዜ ከአባቶች ቤቶች አለቆች አያሌዎች ለእግዚአብሔር ቤት በስፍራው ይሠሩት ዘንድ በፈቃዳቸው ሰጡ።'),
  ('ad28b201-0fed-51ea-a740-79e6d3681d22', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 69, 69, 'ስድሳ አንድ ሺህም የወርቅ ዳሪክ፥ አምስት ሺህም ምናን ብር፥ አንድ መቶም የካህናት ልብስ እንደ ችሎታቸው ወደ ሥራው ቤተ መዛግብት አቀረቡ።'),
  ('ebe16220-9dca-55b2-af3d-297c96666c36', '87a3a6ff-084a-5889-ac64-e84a7ea57169', '019348b4-caee-5400-a1d8-e5bb2d5b99a0', 70, 70, 'ካህናቱና ሌዋውያኑም፥ ከሕዝቡም አያሌዎች፥ መዘምራኑና በረኞቹም፥ ናታኒምም በከተሞቻቸው፥ እስራኤልም ሁሉ በከተሞቻቸው ተቀመጡ።'),
  ('4994bbd0-7606-5d77-a17e-fc7065a03aa2', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 1, 1, 'ሰባተኛውም ወር በደረሰ ጊዜ፥ የእስራኤልም ልጆች በከተሞቻቸው ሳሉ፥ ሕዝቡ እንደ አንድ ሰው ሆነው ወደ ኢየሩሳሌም ተሰበሰቡ።'),
  ('68500e6d-43c6-566f-acb7-09797effb353', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 2, 2, 'የኢዮሴዴቅም ልጅ ኢያሱ፥ ወንድሞቹም ካህናቱ፥ የሰላትያልም ልጅ ዘሩባቤል፥ ወንድሞቹም ተነሥተው በእግዚአብሔር ሰው በሙሴ ሕግ እንደ ተጻፈ የሚቃጠለውን መሥዋዕት ያቀርቡበት ዘንድ የእስራኤልን አምላክ መሠዊያ ሠሩ።'),
  ('3e62b5a7-173e-5279-a0e1-ced86185c013', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 3, 3, 'በሀገሩም ካሉት አሕዛብ ፈርተው ነበርና መሠዊያውን በስፍራው ላይ አስቀመጡት፤ በጥዋትና በማታም የሚቃጠለውን መሥዋዕት ለእግዚአብሔር አቀረቡበት።'),
  ('d0f8a53a-74dd-5883-a5a0-b764892194d9', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 4, 4, 'እንደ ተጻፈውም የዳስ በዓል አደረጉ፤ እንደ ሥርዐቱም ለየዕለቱ የተገባውን የየዕለቱን የሚቃጠል መሥዋዕት በቍጥር አቀረቡ።'),
  ('b8833d4e-dfd0-516c-af82-f85b4e118c32', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 5, 5, 'ከዚያም በኋላ ዘወትር የሚቃጠለውን መሥዋዕት፥ የመባቻውንም መሥዋዕት፥ የተቀደሱትንም የእግዚአብሔር በዓላት ሁሉ መሥዋዕት፥ ሰውም ሁሉ ለእግዚአብሔር በፈቃድ የሰጠውን ቍርባን አቀረቡ።'),
  ('77386db4-9348-5465-ab63-01148d8d084e', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 6, 6, 'በሰባተኛውም ወር በመጀመሪያው ቀን ለእግዚአብሔር የሚቃጠል መሥዋዕት ማቅረብ ጀመሩ፤ የእግዚአብሔር መቅደስ ግን ገና አልተመሠረተም ነበር።'),
  ('ead62c76-d2ac-5898-a5bc-b6203413a4d5', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 7, 7, 'ለጠራቢዎችና ለአናጢዎችም ብር ሰጡ፤ የፋርስም ንጉሥ ቂሮስ እንደ ፈቀደላቸው የዝግባ ዛፍ ከሊባኖስ በባሕር ወደ ኢዮጴ ያመጡ ዘንድ ለሲዶናና ለጢሮስ ሰዎች መብልና መጠጥ፥ ዘይትም ሰጡ።'),
  ('d8b8f1b1-6267-5d36-adbb-e5963babfa6e', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 8, 8, 'በኢየሩሳሌምም ወዳለው ወደ እግዚአብሔር ቤት በመጡ በሁለተኛው ዓመት በሁለተኛውም ወር የሰላትያል ልጅ ዘሩባቤል፥ የኢዮሴዴቅም ልጅ ኢያሱ፥ የቀሩትም ወንድሞቻቸው ካህናትና ሌዋውያን፥ ከምርኮ ወደ ኢየሩሳሌምም የተመለሱት ሁሉ ጀመሩ፤ ሌዋውያንንም ከሃያ ዓመት ጀምሮ ከዚያም በላይ የእግዚአብሔርን ቤት ሥራ እንዲያሠሩት ሾሙአቸው።'),
  ('a5f1782a-4077-5763-a153-1cca056bb440', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 9, 9, 'ኢያሱም፥ ልጆቹም ተሾሙ፤ ወንድሞቹም፥ የይሁዳም ልጆች ቀደምያልና ልጆቹ፥ የኢንሐዳድም ልጆች፥ ልጆቻቸውና ወንድሞቻቸው ሌዋውያንም የእግዚአብሔርን ቤት የሚሠሩትን ያሠሩ ዘንድ በአንድነት ቆሙ።'),
  ('0429589d-00a4-5fea-abda-41b3c4d7da82', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 10, 10, 'አናጢዎቹም የእግዚአብሔርን መቅደስ ይሠሩ ዘንድ መሠረት በጣሉ ጊዜ ካህናቱ ልብሳቸውን ለብሰው መለከቱን ይዘው፥ የአሳፍም ልጆች ሌዋውያን ጸናጽል ይዘው እንደ እስራኤል ንጉሥ እንደ ዳዊት ሥርዐት እግዚአብሔርን ያመሰግኑ ዘንድ ቆሙ።'),
  ('79dabc78-f176-51f8-a398-489dbb19143e', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 11, 11, 'ደግሞ፥ “ቸር ነውና፥ ለእስራኤልም ምሕረቱ ለዘለዓለም ነውና” እያሉ እግዚአብሔርን እያመሰገኑና እያከበሩ እርስ በርሳቸው ያስተዛዝሉ ነበር፤ የእግዚአብሔርም ቤት በተመሠረተ ጊዜ ሕዝቡ ሁሉ እግዚአብሔርን እያከበሩ በታላቅ ድምፅ ዘመሩ።'),
  ('34e836b7-6c08-567f-abbd-ef6562c4c9b2', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 12, 12, 'የፊተኛውን ቤት ያዩ ሽማግሌዎች የሆኑ ብዙ ካህናትና ሌዋውያን፥ የአባቶችም ቤቶች አለቆች ግን ይህ መቅደስ በፊታቸው በተመሠረተ ጊዜ በታላቅ ድምፅ ያለቅሱ ነበር፤ ብዙ ሰዎችም እየዘመሩ በደስታ ይጮኹ ነበር፤'),
  ('3659ea9b-368c-5185-a44c-242df8943a05', 'dec335a8-516b-52cb-a6d5-9af352b4e8b1', 'cd0ab53d-0701-53d5-ab9a-1b626a9e9705', 13, 13, 'ደስ ብሎአቸው የሚጮኹትን ድምፅ ከሕዝቡ ልቅሶ ድምፅ መለየት የሚችል አልነበረም፥ ሕዝቡ በታላቅ ድምፅ ይጮኽ ነበርና ድምፁም ከሩቅ ይሰማ ነበርና።'),
  ('44342a94-8bc0-5f9f-ac80-b532121ec37d', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 1, 1, 'የይሁዳና የብንያምም ጠላቶች፥ የምርኮኞቹ ልጆች ለእስራኤል አምላክ ለእግዚአብሔር መቅደስ እንደሚሠሩ ሰሙ።'),
  ('f78bcc2d-6889-58ea-afb7-ed423525a9c2', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 2, 2, 'ወደ ዘሩባቤልና ወደ አባቶች ቤቶች አለቆችም ቀርበው፥ “የአሦር ንጉሥ አስራዶን ወደዚህ ካመጣን ቀን ጀምሮ ለአምላካችሁ እንሠዋለንና፥ እንደ እናንተም እንፈልገዋለንና ከእናንተ ጋር እንሥራ” አሉአቸው።'),
  ('113bf2df-36fa-546d-ad05-9121e6977483', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 3, 3, 'ዘሩባቤልና ኢያሱም፥ የቀሩትም የእስራኤል አባቶች ቤቶች አለቆች፥ “የአምላካችንን ቤት መሥራት ለእኛና ለእናንተ አይደለም፤ እኛ ራሳችን ግን የፋርስ ንጉሥ ቂሮስ እንዳዘዘን ለአምላካችን ለእግዚአብሔር ቤት እንሠራለን” አሉአቸው።'),
  ('1d10a292-7f37-5edf-a583-fc2c86132d1b', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 4, 4, 'የሀገሩም ሕዝብ የይሁዳን ሕዝብ እጅግ ያዳክሙ ነበር፤ እንዳይሠሩም ከለከሉአቸው፤'),
  ('34003a48-61a4-5ba5-af5f-544ae7e11d37', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 5, 5, 'ምክራቸውንም ያፈርሱ ዘንድ በፋርሱ ንጉሥ በቂሮስ ዘመን ሁሉ እስከ ፋርስ ንጉሥ እስከ ዳርዮስ መንግሥት ድረስ መካሪዎችን ገዙባቸው።'),
  ('20f9294e-2632-5207-a2fe-60ee9b4cc2e5', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 6, 6, 'በአሕሳዊሮስም መንግሥት፥ በመንግሥቱም በመጀመሪያ ዘመን፥ በይሁዳና በኢየሩሳሌም በሚኖሩት ላይ ደብዳቤ ጻፉ።'),
  ('324c1283-f173-51d7-ae50-6677997ba365', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 7, 7, 'በአርተሰስታ ዘመን በሴሌም፥ ሜትሪዳጡ፥ ጣብሄል፥ የቀሩት ተባባሪውቻቸውም ለፋርስ ንጉሥ ለአርተሰስታ ጻፉ፤ ደብዳቤውም በሶርያ ፊደልና በሶርያ ቋንቋ ተጽፎ ነበር።'),
  ('1b53bde7-8fc6-58f0-a197-65905486e552', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 8, 8, 'አዛዡ ሬሁም፥ ጸሓፊውም ሲምሳይ በኢየሩሳሌም ላይ ለንጉሡ ለአርተሰስታ አንድ የክስ ደብዳቤ ጻፉ።'),
  ('99e80d1f-25d1-59ae-a3bb-4fdc36900000', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 9, 9, 'አዛዡ ሬሁም፥ ጸሓፊውም ሲምሳይ፥ የቀሩትም ተባባሪዎቻቸው፥ ዲናውያን፥ አፈርሳትካዋያን፥ ጠርፈላውያን፥ አፈርሳውያን፥ አርካውያን፥ ባቢሎናውያን፥ ሱስናካውያን፥ ዴሐውያን፥ ኤላማውያን፥'),
  ('14e0ce42-a4dc-50ae-a7b6-67f1a733b0d4', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 10, 10, 'ታላቁና ኀይለኛው አስናፍር ያፈለሳቸው፥ በሰማርያና በወንዝ ማዶ ያኖራቸው፥ የቀሩትም አሕዛብ ደብዳቤውን ጻፉ።'),
  ('717cc03d-1bf0-567b-a183-b1bc122ce510', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 11, 11, 'ለንጉሡ ለአርተሰስታ የላኩት የደብዳቤ ቃልም ይህ ነው፥ “በወንዝ ማዶ ያሉት ሰዎች ባሪያዎችህ፤'),
  ('cb131f40-1f3d-578e-a85f-8a05ff5f9ed7', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 12, 12, 'አሁንም ከአንተ ዘንድ የወጡ አይሁድ ወደ እኛ ወደ ኢየሩሳሌም እንደ መጡ ጌታቸው ንጉሡ ይወቅ፤ ዐመፀኛዪቱንና እጅግም የከፋችቱን ከተማ ይሠራሉ፤ ቅጥርዋንም ያድሳሉ፤ መሠረቷንም ጠገኑ።'),
  ('cd33c5be-03a1-5634-a538-eba6e6283f1f', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 13, 13, 'አሁንም ይህች ከተማ የተሠራች እንደ ሆነ፥ ቅጥርዋም የታደሰ እንደ ሆነ፥ ግብርና ቀረጥ መጥንም እንደማይሰጡ፥ ንጉሡ ይወቅ፤ ይህም መንግሥትን ይጐዳል።'),
  ('d9f5fa3e-caed-57ef-a8be-03ceb221672e', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 14, 14, 'ንጉሡንም ሲያቃልሉት ማየት አይገባንምና ስለዚህ ልከን ለንጉሡ አስታውቀናል፤'),
  ('1196623c-0802-54bf-a521-6445ac0be1c2', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 15, 15, 'በአባቶችህ ታሪክ መጽሐፍ ምርመራ ይደረግ፤ በዚያም በታሪክ መጽሐፍ ይህች ከተማ ዐመፀኛ እንደ ሆነች፥ ነገሥታትንና አውራጃዎችንም እንደ ጎዳች፥ ከጥንቱም የገባሮች ሽፍትነት በእርስዋ እንደ ተጀመረ ታገኛለህ፤ ታውቃለህም፤ ስለዚህም ይህች ከተማ ፈርሳ ነበር።'),
  ('d458e957-ce20-5184-ae38-244fad28be19', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 16, 16, 'ይህችም ከተማ የተሠራች እንደ ሆነ፥ ቅጥርዋም የታደሰ እንደ ሆነ፥ ሰላም እንደማይኖርህ ለንጉሡ እናስታውቃለን።”'),
  ('8fb62703-5695-5e95-a226-a4c4e963c788', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 17, 17, 'ንጉሡም ለአዛዡ ለሬሁም፥ ለጸሓፊውም ለሲምሳይ፥ በሰማርያና በወንዝ ማዶም ለተቀመጡትና ለቀሩት ተባባሪዎቻቸው እንዲህ የሚለውን መልስ ላከ፥ “ሰላም ለእናንተ ይሁን።'),
  ('a10ef0b5-8bcd-5e7e-a224-24be39280b5f', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 18, 18, 'አሁንም ወደ እኛ የላካችሁት መልእክተኛ ወደ እኔ ደረሰ'),
  ('4c249ebf-b416-586d-aea2-0d6f3e98edd5', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 19, 19, 'እኔም አዝዣለሁ፤ ተመረመረም፤ ይህችም ከተማ ከጥንት ጀምራ በነገሥታት ላይ ዐመፀኛ እንደ ነበረች፥ በእርስዋም ዐመፅና ሽፍትነት እንደ ተደረገ ተገኘ።'),
  ('f12a872e-ba9e-533a-a0a7-199e21c023bf', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 20, 20, 'በኢየሩሳሌምም እጅግ ኀያላን ነገሥታት ነበሩ፤ በወንዝም ማዶ ያለውን ሀገር ሁሉ ይገዙ ነበር፤ ግብርንና እጅ መንሻንም ይቀበሉ ነበር።'),
  ('3c92a54d-0a7b-50a3-ac66-5474677f334b', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 21, 21, 'አሁንም እነዚህ ሰዎች ሥራውን እንዲተዉ፥ ይህችም ከተማ እንዳትሠራ ትእዛዝ ስጡ።'),
  ('a9d3ae08-6190-5643-aae1-99837baecad1', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 22, 22, 'በዚህም ነገር እንዳትሳሳቱ፥ በነገሥታቱም ጕዳትና ጥፋት እንዳይበዛ ተጠንቀቁ።”'),
  ('2410f914-3afb-5a85-a2f4-a5d315f62c45', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 23, 23, 'የንጉሡም የአርተሰስታ መልእክተኛ በደረሰ ጊዜ በአዛዡ በሬሁምና በጸሓፊው በሲምሳይ፥ በተባባሪዎቻቸውም ፊት መልእክቱን ባነበበ ጊዜ ፈጥነው ወደ ኢየሩሳሌም ወደ አይሁድ በፈረስ ሄዱ፤ በኀይልም አስተዉአቸው።'),
  ('afde668a-d625-5de9-a74f-67552c1af285', '530b84e1-df45-501c-a299-694f7cbd8195', '1359cc0b-369e-5119-a46f-9e1e21fd1dea', 24, 24, 'በዚያን ጊዜም በኢየሩሳሌም ያለው የእግዚአብሔር ቤት ሥራ ተቋረጠ፤ እስከ ፋርስም ንጉሥ እስከ ዳርዮስ መንግሥት እስከ ሁለተኛው ዓመት ድረስ ተጓጐለ።'),
  ('855a90bb-2bd9-5209-a175-046712062da1', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 1, 1, 'ነቢያቱ ሐጌና የአዶ ልጅ ዘካርያስ በይሁዳና በኢየሩሳሌም ለነበሩ አይሁድ በእስራኤል አምላክ ስም ትንቢት ተናገሩላቸው።'),
  ('9a8e2a32-4301-574d-a740-4825a585b904', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 2, 2, 'በዚያን ጊዜም የሰላትያል ልጅ ዘሩባቤል የኢዮሴዴቅም ልጅ ኢያሱ ተነሥተው በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት መሥራት ጀመሩ፤ የሚያግዙአቸውም የእግዚአብሔር ነቢያት ከእነርሱ ጋር ነበሩ።'),
  ('85b5ec80-86d9-57cf-a00f-57c47e41bf53', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 3, 3, 'በዚያም ጊዜ በወንዝ ማዶ የነበረው ገዥ ተንትናይ፥ ደግሞ አስተርቡዝናይ ተባባሪዎቻቸውም ወደ እነርሱ መጥተው፥ “ይህን ቤት ትሠሩ ዘንድ ማን አዘዛችሁ? የምትሠሩበትንስ ሥልጣን ማን ሰጣችሁ?” አሉአቸው።'),
  ('72f14f8a-c3f9-5c38-ac26-143bc54f3826', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 4, 4, 'ደግሞም፥ “ይህችን ከተማስ የሚሠሩ ሰዎች ስም ማን ማን ነው?” ብለው ጠየቁአቸው።'),
  ('f1f74747-c0ed-53d4-a1c2-903570842d4b', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 5, 5, 'የእግዚአብሔር ዐይን ግን በይሁዳ ምርኮኞች ላይ ነበረ፤ ይህም ነገር ወደ ዳርዮስ እስኪደርስ ድረስ፥ መልሱም በመልእክተኛ እስኪመጣ ድረስ አልከለከሉአቸውም።'),
  ('2ed3d933-d8dd-5dbe-a5f8-d3aa386ffc89', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 6, 6, 'በወንዙ ማዶ የነበረው ገዥ ተንትናይ፥ ደግሞ አስተርቡዝናይ፥ ተባባሪዎቻቸውም፥ በወንዙ ማዶ የነበሩት አፈርስካውያንም ወደ ንጉሡ ወደ ዳርዮስ የላኩት የደብዳቤው ቃል ይህ ነበረ።'),
  ('8dfad1fd-2854-569c-aafe-bbde5a90a98c', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 7, 7, 'እንዲህም የሚል ደብዳቤ ላኩለት፥ “ለንጉሡ ለዳርዮስ ሙሉ ሰላም ይሁን፤'),
  ('761b157e-3e57-5013-abb9-8db064586831', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 8, 8, 'ወደ ይሁዳ ሀገር ወደ ታላቁም አምላክ ቤት እንደ ሄድን ንጉሡ ይወቅ፤ እርሱም በጥሩ ድንጋይ ይሠራል፤ በቅጥሩም ውስጥ ልዩ እንጨት ይደረጋል፤ ያም ሥራ በትጋት ይሠራል፤ በእጃቸውም ይከናወናል።'),
  ('666157d3-26b6-5c38-aa33-912b75d8ab72', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 9, 9, 'እነዚያንም ሽማግሌዎች፦ ‘ይህን ቤት ትሠሩ ዘንድ ማን አዘዛችሁ? የምትሠሩበትንስ ሥልጣን ማን ሰጣችሁ?’ ብለን ጠየቅናቸው።'),
  ('fad22f5c-cd8e-5871-ab1a-e45c17aa7355', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 10, 10, 'ደግሞም እናስታውቅህ ዘንድ፥ በእነርሱም ያሉትን ሹሞች ስም እንጽፍልህ ዘንድ ስማቸውን ጠየቅን።'),
  ('86622e96-fdf1-5f05-ae66-218f87991285', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 11, 11, 'እንደዚህም ብለው መለሱልን፦ እኛ የሰማይና የምድር አምላክ ባሪያዎች ነን፥ ከብዙም ዘመን ጀምሮ ተሠርቶ የነበረውን፥ ታላቁም የእስራኤል ንጉሥ ሠርቶ ፈጽሞላቸው የነበረውን ቤት እንሠራለን።'),
  ('8f13dd8c-7de4-5451-ab2d-424330b496d4', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 12, 12, 'አባቶቻችንም የሰማይን አምላክ ከአስቈጡ በኋላ በከለዳዊው በባቢሎን ንጉሥ በናቡከደነፆር እጅ አሳልፎ ሰጣቸው፤ እርሱም ይህን ቤት አፈረሰ፤ ሕዝቡንም ወደ ባቢሎን አፈለሰ።'),
  ('6416bd52-5e9f-5e5e-a355-910387f8539c', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 13, 13, 'ነገር ግን በባቢሎን ንጉሥ በቂሮስ በመጀመሪያው ዓመት ንጉሡ ቂሮስ ይህን የእግዚአብሔርን ቤት ይሠሩ ዘንድ አዘዘ።'),
  ('04513705-bdc2-57e3-a91b-cdf0f290fec3', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 14, 14, 'ናቡከደነፆርም በኢየሩሳሌም ከነበረው መቅደስ የወሰደውን፥ ወደ ባቢሎንም መቅደስ ያፈለሰውን የእግዚአብሔርን ቤት የወርቁንና የብሩን ዕቃ ንጉሡ ቂሮስ ከባቢሎን መቅደስ አውጥቶ ለቤተ መዛግብቱ ሹም ለሲሳብሳር ሰጠውና፦'),
  ('929b1ffa-bc0a-5c40-a59c-6fc518c40949', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 15, 15, '‘ይህን ዕቃ ይዘህ ሂድ፤ በኢየሩሳሌምም ባለው መቅደስ በቦታው አኑረው፤ የእግዚአብሔርም ቤት በስፍራው ይሠራ’ አለው።'),
  ('db15998b-7a10-5789-a922-81af50f9b0c8', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 16, 16, 'በዚያ ጊዜም ይህ ሲሳብሳር መጣ፤ በኢየሩሳሌምም ያለውን የእግዚአብሔርን ቤት መሠረተ፤ ከዚያም ጊዜ ጀምሮ እስከ ዛሬ ድረስ እየተሠራ አልተጨረሰም።'),
  ('308626cd-d81a-5f01-a2ca-c1b6194b5aba', 'eb946fae-a950-5b88-a0d4-f0d5cd970f79', '4577cf8f-67a0-5a1a-a42d-be26be8f06a6', 17, 17, 'አሁንም ይህ ነገር በንጉሡ ዐይን መልካም ቢሆን ይህ የእግዚአብሔር ቤት በኢየሩሳሌም ይሠራ ዘንድ ከንጉሡ ከቂሮስ ታዝዞ እንደ ሆነ በባቢሎን ባለው በንጉሡ ቤተ መዛግብት ይመርመር፤ ስለዚህም ነገር ንጉሡ ፈቃዱን ይላክልን።”'),
  ('246551eb-4503-571c-af23-dac6ee64f8d2', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '27f0fb96-9433-5959-a5bd-dcd551745ff2', 1, 1, 'በዚያ ጊዜም ንጉሡ ዳርዮስ በባቢሎን ቤተ መዛግብት ያሉ የታሪክ መጻሕፍት እንዲመረመሩ አዘዘ።'),
  ('ab568447-cb47-506b-a9a5-6c5b8b8958af', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '27f0fb96-9433-5959-a5bd-dcd551745ff2', 2, 2, 'በሜዶን አውራጃ ባለው ባሪ በሚባል ከተማ በንጉሡ ቤት ውስጥ አንድ ጥቅልል ተገኘ፤ በውስጡም ይህ ነገር ለመታሰቢያ ተጽፎ ነበር።'),
  ('11a47521-a7f2-5c6f-a0c2-afee21284e65', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '27f0fb96-9433-5959-a5bd-dcd551745ff2', 3, 3, 'በንጉሡ በቂሮስ በመጀመሪያው ዓመት ንጉሡ ቂሮስ በኢየሩሳሌም ስላለው የእግዚአብሔር ቤተ መቅደስ እንዲህ ብሎ አዘዘ፥ “ይህ ቤት ይሠራ መሥዋዕት የሚቀርብበትም ቦታ ይሠራ፤ ቁመቱም ስድሳ ክንድ፥ ወርዱም ስድሳ ክንድ ይሁን።'),
  ('aed87d4c-18bd-5fad-a8c3-11a413621d6f', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '27f0fb96-9433-5959-a5bd-dcd551745ff2', 4, 4, 'በሦስት ተራ ታላላቅ ድንጋይ፥ በአንድ ተራ እንጨት ይደረግ፤ ወጭውም ከንጉሡ ቤት ይሰጥ።'),
  ('74450563-0d56-5295-a0d1-e54d1573d2be', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '27f0fb96-9433-5959-a5bd-dcd551745ff2', 5, 5, 'ናቡከደነዖርም በኢየሩሳሌም ካለው መቅደስ ወስዶ ወደ ባቢሎን ያመጣው የእግዚአብሔር ቤት የወርቅና የብር ዕቃ ይሰጥ፤ በኢየሩሳሌምም ወዳለው መቅደስ ወደ ስፍራው ይወሰድ፤ በእግዚአብሔርም ቤት ይኑር።'),
  ('7a44ae4f-3d95-5e8b-a2f8-ab0825771c7b', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 1, 6, '“አሁንም አንተ በወንዝ ማዶ ያለኸው የሀገሩ ገዥ ተንትናይ ደግሞ አሰተርቡዝናይ በወንዝ ማዶም ያሉ ተባባሪዎቻችሁ አፈርስካውያን ከዚያ ራቁ፤'),
  ('9a45ee6d-b2b9-54ff-a6b8-e8f5e3319358', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 2, 7, 'ይህም የእግዚአብሔር ቤት ይሠራ ዘንድ ተዉ፤ የአይሁድም አለቆችና የአይሁድ ሽማግሌዎች ይህን የእግዚአብሔርን ቤት በስፍራው ይሥሩ።'),
  ('ce3f6b9c-aeec-53a5-ac1d-f37a97f01f91', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 3, 8, 'ይህን የእግዚአብሔርን ቤት ይሠሩ ዘንድ ለአይሁድ ሽማግሌዎች የምታደርጉትን፥ በወንዝ ማዶ ካለው ሀገር ከሚመጣው ግብር ከንጉሡ ገንዘብ ለእነዚህ ሰዎች ወጭውን በትጋት እንድትሰጡአቸው፥ ሥራም እንዳታስፈቱአቸው አዝዣለሁ።'),
  ('59ba940e-8ae9-567e-a816-4bf270523806', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 4, 9, 'ለሰማይ አምላክ ለሚቃጠል መሥዋዕት የሚያስፈልገውን ወይፈኖችና አውራ በጎች፥ ጠቦቶችም፥ በኢየሩሳሌምም እንዳሉ እንደ ካህናቱ ቃል ስንዴና ጨው፥ የወይን ጠጅና ዘይት የሚጠይቋችሁን ዕለት ዕለት ስጡአቸው።'),
  ('8f395d39-b8b5-5145-a808-fd85e82d22fd', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 5, 10, 'ይኸውም ለሰማይ አምላክ በጎ መዓዛ የሆነውን መሥዋዕት ያቀርቡ ዘንድ፥ ለንጉሡና ለልጆቹም ዕድሜ ይጸልዩ ዘንድ ነው።'),
  ('34923a42-3b3a-5167-aa8f-cee0eb59c5a7', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 6, 11, 'ይህንም ትእዛዝ የሚለውጥ ሁሉ ምሰሶው ከቤቱ ተነቅሎ እርሱ ይሰቀልበት፤ በላዩም ይገደል፤ ቤቱም የጕድፍ መጣያ ይደረግ ብዬ አዝዣለሁ።'),
  ('36e64a60-ddb7-5a4a-a13a-740d83e99d65', '82b3f425-4a06-58f0-a0f8-6809273d10ef', '1fb2a86b-5499-5330-a642-b5264bd5b0d5', 7, 12, 'ስሙ በዚያ የሚኖር አምላክ ይህን ይለውጡ ዘንድ፥ በኢየሩሳሌም ያለውንም የእግዚአብሔርን ቤት ያፈርሱት ዘንድ እጃቸውን የሚዘረጉትን ነገሥታትና አሕዛብ ሁሉ ያጥፋ። እኔ ዳርዮስ ይህን አዝዣለሁ፤ በትጋት ይፈጸም።”'),
  ('bdbb0d5f-6e65-56fa-a934-479f59345a90', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 1, 13, 'ንጉሡም ዳርዮስ እንደ ላከው ቃል፥ በዚያን ጊዜ በወንዝ ማዶ ያለ ገዥ ተንትናይ ደግሞ አስተርቡዝናይ ተባባሪዎቻቸውም እንዲሁ ተግተው አደረጉ።'),
  ('54877e83-9323-532a-a7fb-8204df5499f1', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 2, 14, 'የአይሁድ ሽማግሌዎችና ሌዋውያንም በነቢዩ በሐጌና በአዶ ልጅ በዘካርያስ ትንቢት መሠረት ሠሩ፤ ተከናወነላቸውም። እንደ እስራኤልም አምላክ ትእዛዝ፥ እንደ ፋርስም ነገሥታት እንደ ቂሮስና እንደ ዳርዮስ፥ እንደ አርተሰስታም ትእዛዝ ሠርተው ፈጸሙ።'),
  ('fad46d61-e21a-5585-a5b2-c933c7fb1105', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 3, 15, 'ይህም ቤት በንጉሡ በዳርዮስ መንግሥት በስድስተኛው ዓመት አዳር በሚባል ወር በሦስተኛው ቀን ተፈጸመ።'),
  ('9419d421-5191-5e75-a9eb-39b81f774c01', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 4, 16, 'የእስራኤልም ልጆች ካህናቱና ሌዋውያኑ፥ የቀሩትም የምርኮኞች ልጆች የዚህን የእግዚአብሔርን ቤት ቅዳሴ በደስታ አደረጉ።'),
  ('2f738e85-ce82-5a90-aee4-b2d7bf74758a', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 5, 17, 'በዚህም በእግዚአብሔር ቤት ቅዳሴ መቶ ወይፈኖችና ሁለት መቶ አውራ በጎች፥ አራት መቶም የበግ ጠቦቶች አቀረቡ፤ ስለ ኀጢአትም መሥዋዕት እንደ እስራኤል ነገዶች ቍጥር ለእስራኤል ሁሉ ዐሥራ ሁለት አውራ ፍየሎች አቀረቡ።'),
  ('93e3614e-3189-5f02-a31d-fdf70e2a6f28', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 6, 18, 'በሙሴም መጽሐፍ እንደ ተጻፈው በኢየሩሳሌም ባለው በእግዚአብሔር አገልግሎት ላይ ካህናቱን በየማዕርጋቸው፥ ሌዋውያኑንም በየክፍላቸው አቆሙ።'),
  ('40794c57-544c-5f14-a02d-cabda28626b7', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 7, 19, 'የምርኮኞቹም ልጆች በመጀመሪያው ወር በዐሥራ አራተኛው ቀን ፋሲካውን አደረጉ።'),
  ('76fa00f7-ac9e-58cd-a8cc-c1ad9e2bebd2', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 8, 20, 'ካህናቱና ሌዋውያኑም አንድ ሆነው ነጽተው ነበር፤ ሁሉም ንጹሓን ነበሩ፤ ለምርኮኞቹም ልጆች ሁሉ፥ ለወንድሞቻቸው ለካህናቱ፥ ለራሳቸውም የፋሲካውን በግ ዐረዱ።'),
  ('c1c55df6-604e-56e0-aaf2-204506e07138', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 9, 21, 'ከምርኮም ተመልሰው የመጡት የእስራኤል ልጆች፥ የእስራኤልን አምላክ እግዚአብሔርን ይፈልጉ ዘንድ ራሳቸውን ከምድር አሕዛብ ርኵሰት ለይተው ወደ እነርሱ መጥተው የነበሩት ሁሉ ፋሲካውን በሉ፤'),
  ('eae03859-7f1f-56e5-a292-ab7c98a61081', '82b3f425-4a06-58f0-a0f8-6809273d10ef', 'e98a90e9-e26f-5317-a9de-4e7e8e757892', 10, 22, 'እግዚአብሔርም ደስ አሰኝቶአቸዋልና፥ የእስራኤልንም አምላክ የእግዚአብሔርን ቤት ለመሥራት እጃቸውን ያጸና ዘንድ የአሦርን ንጉሥ ልብ ወደ እነርሱ መልሶአልና የቂጣውን በዓል ሰባት ቀን በደስታ አደረጉ።'),
  ('6aa02338-0a7a-5007-a2c5-6e7affc19c32', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 1, 1, 'ከዚህም ነገር በኋላ በፋርስ ንጉሥ በአርተሰስታ መንግሥት ዕዝራ የሠራያ ልጅ፥ የዓዛርያስ ልጅ፥ የኬልቅያስ ልጅ፥'),
  ('9740611f-77f5-525a-a037-707510d08a4f', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 2, 2, 'የሰሎም ልጅ፥ የሳዶቅ ልጅ፥ የአኪጦብ ልጅ፥'),
  ('af5c62ee-f726-567e-a2b8-781a138e8a84', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 3, 3, 'የአማርያ ልጅ፥ የዓዛርያስ ልጅ፥ የመራዮት ልጅ፥'),
  ('4de85dcf-01fa-51d7-a8a8-2fc246241c70', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 4, 4, 'የዘራእያ ልጅ፥ የኡዚ ልጅ፥ የቡቂ ልጅ፥'),
  ('07668565-8c4d-5cf0-ab36-a5f1fee94390', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 5, 5, 'የአቢሱ ልጅ፥ የፊንሐስ ልጅ፥ የአልዓዛር ልጅ፥ የመጀመሪያው ካህን የአሮን ልጅ፥'),
  ('600d8fe9-204c-5dbc-af9f-d4b624db3a7e', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 6, 6, 'ይህም ዕዝራ ከባቢሎን ወጣ፤ እርሱም የእስራኤል አምላክ እግዚአብሔር ለሙሴ የሰጠውን ሕግ ዐዋቂ ነበረ፤ የአምላኩም የእግዚአብሔር እጅ በእርሱ ላይ ነበረችና ንጉሡ ያሻውን ሁሉ ሰጠው።'),
  ('fe6a463f-6ea1-504a-a487-e72b37385293', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 7, 7, 'ከእስራኤልም ልጆች ከካህናቱም፥ ከሌዋውያኑም፥ ከመዘምራኑም፥ ከበረኞቹም፥ ከናታኒምም በንጉሡ በአርተሰስታ በሰባተኛው ዓመት ዐያሌዎች ወደ ኢየሩሳሌም ወጡ።'),
  ('05892ed3-666c-5d90-aac8-8a6751186cfa', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 8, 8, 'በንጉሡም በሰባተኛው ዓመት በአምስተኛው ወር ወደ ኢየሩሳሌም ደረሱ።'),
  ('b83fc9e8-7003-5f1e-a7af-f7e55fcccb77', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 9, 9, 'በመጀመሪያውም ወር በአንደኛው ቀን ከባቢሎን ሊወጡ ጀመሩ፤ መልካሚቱም የአምላኩ እጅ በእርሱ ላይ ነበረችና በአምስተኛው ወር በመጀመሪያው ቀን ወደ ኢየሩሳሌም ደረሱ።'),
  ('1d1dc8b1-8e32-5c89-adb5-1ec94c41f1e6', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '35916e00-cbdd-5caf-a349-9f4362593383', 10, 10, 'ዕዝራም የእግዚአብሔርን ሕግ ይፈልግና ያደርግ ዘንድ፥ ለእስራኤልም ሥርዐትንና ፍርድን ያስተምር ዘንድ ልቡን አዘጋጅቶ ነበር።'),
  ('989db896-6ba5-5f3b-af6d-ac6aea11b1fa', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 1, 11, 'ንጉሡም አርተሰስታ የእግዚአብሔርን ትእዛዝ ቃልና ለእስራኤል የሆነውን ሥርዐት ይጽፍ ለነበረው ለጸሓፊው ለካህኑ ለዕዝራ የሰጠው የደብዳቤው ቃል ይህ ነው፦'),
  ('90da0b2d-4a3f-581f-ade3-94b23de33e0b', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 2, 12, '“ከንጉሠ ነገሥት ከአርተሰስታ ለሰማይ አምላክ ሕግ ጸሓፊ ለካህኑ ለዕዝራ፥ ሰላም ይሁን፤'),
  ('4b57eef3-f9d1-5c5b-a2c6-18ac87fb8b38', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 3, 13, 'በመንግሥቴም ውስጥ ካሉ ከእስራኤል ሕዝብ ከካህናቱና ከሌዋውያኑ ወደ ኢየሩሳሌም ይሄድ ዘንድ የሚወድድ ሁሉ ከአንተ ጋር እንዲሄድ አዝዣለሁ።'),
  ('7fed928f-71fe-56ee-abdc-fd0df9c2d6c5', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 4, 14, 'ንጉሡና ሰባቱ አማካሪዎቹ በእጅህ እንዳለችው እንደ አምላክህ ሕግ ይሁዳንና ኢየሩሳሌምን ትጐበኝ ዘንድ አዝዘዋል፤'),
  ('cbfe2da8-3b9d-59a9-af55-86827d434e34', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 5, 15, 'ንጉሡና አማካሪዎቹም መኖሪያው በኢየሩሳሌም ለሆነው ለእስራኤል አምላክ በፈቃዳቸው ያቀረቡትን ብርና ወርቅ፥'),
  ('3f08b2eb-aea4-500e-a50a-c646bf4a1920', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 6, 16, 'በባቢሎንም አውራጃ ሁሉ የምታገኘውን ብርና ወርቅ ሁሉ፥ ሕዝቡና ካህናቱም በኢየሩሳሌም ላለው ለአምላካቸው ቤት በፈቃዳቸው የሚያቀርቡትን ትወስድ ዘንድ አዝዘዋል፤'),
  ('352f07d7-6069-5cf1-af47-95d1a888b43a', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 7, 17, 'ስለዚህ በዚህ መጽሐፍ ያዘዝሁህ ትእዛዝ ይህ ነው። በዚህ ገንዘብ ወይፈኖችንና አውራ በጎችን፥ ጠቦቶችንም፥ የእህላቸውንና የመጠጣቸውን ቍርባን ተግተህ ግዛ፤ በኢየሩሳሌምም ባለው በአምላካችሁ ቤት መሠዊያ ላይ አቅርባቸው።'),
  ('024111ba-09d6-5cc9-a4a5-7b499f5aa178', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 8, 18, 'ከቀረውም ብርና ወርቅ አንተና ወንድሞችህ ለማድረግ ደስ የሚያሰኛችሁን ነገር እንደ አምላካችሁ ፈቃድ አድርጉ።'),
  ('a2312c51-f027-57b5-aec6-c90923e19b6c', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 9, 19, 'ስለ አምላክህም ቤት አገልግሎት የተሰጠህን ዕቃ በኢየሩሳሌም አምላክ ፊት አሳልፈህ ስጥ።'),
  ('f997c973-db48-52dc-a50b-2d712d0c03f0', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 10, 20, 'ከዚህም በላይ ለማውጣት የሚያስፈልግህን ለአምላክህ ቤት የሚያሻውን ነገር ከንጉሡ ቤተ መዛግብት ስጥ።'),
  ('e0ba1b3c-7165-5c70-afff-ca559e1f08ee', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 11, 21, 'እኔም ንጉሡ አርተሰስታ በወንዝ ማዶ ላሉት ግምጃ ቤቶች ሁሉ ይህን ትእዛዝ ሰጥቻለሁ፦ የሰማይ አምላክ ሕግ ጸሓፊ ካህኑ ዕዝራ ከእናንተ የሚፈልገውን ሁሉ አዘጋጁለት፤'),
  ('5dfc55e9-ffe8-5b51-ab49-a214e17e710b', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 12, 22, 'እስከ መቶ መክሊት ብርም ቢሆን፥ እስከ መቶም የቆሮስ መስፈሪያ ስንዴ፥ እስከ መቶም የባዶስ መስፈሪያ የወይን ጠጅ፥ እስከ መቶም የባዶስ መስፈሪያ ዘይት ቢሆን፥ ጨውም ያለ ልክ ቢሆን፤'),
  ('3d4c307c-9654-5ea1-acfc-cb6f9f927635', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 13, 23, 'በንጉሡ መንግሥትና በልጆቹ ላይ ቍጣ እንዳይሆን፥ የሰማይ አምላክ ያዘዘው ሁሉ ይደረግ፤ ለሰማይ አምላክ ቤት የታዘዘውንም እንዳታቋርጡ ተጠንቀቁ።'),
  ('6c360eee-b295-5306-a3a9-cc6c28a20123', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 14, 24, 'ደግሞም በካህናቱና በሌዋውያኑ፥ በመዘምራኑም፥ በበረኞቹም፥ በናታኒምም በዚህም በእግዚአብሔር ቤት በሚሠሩ አገልጋዮች ላይ ግብርና ቀረጥ እንዳይጣል፥ የምትገዙአቸውም አገዛዝ እንዳይኖር ብለን እናስታውቃችኋለን።'),
  ('46bfd85d-0fa6-505c-aead-8a886278bf8b', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 15, 25, 'አንተም ዕዝራ፥ በእጅህ እንዳለው እንደ አምላክህ ጥበብ መጠን በወንዝ ማዶ ባሉ ሕዝብ ሁሉ፥ የአምላክህን ሕግ በሚያውቁ ሁሉ ላይ ይፈርዱ ዘንድ ጻፎችንና ፈራጆችን ሹም፤ የማያውቁትንም አስተምሩአቸው።'),
  ('f694eead-e8bf-5159-a135-825dcb07397c', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 16, 26, 'የአምላክህንም ሕግ፥ የንጉሡንም ሕግ በማያደርግ ሁሉ ላይ ሞት፥ ወይም ስደት፥ ወይም ገንዘብ መወረስ፥ ወይም ግዞት በፍጥነት ይፈረድበት።”'),
  ('f21cec96-9134-5302-a72d-0afa2f787e56', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 17, 27, 'ያባቶቻችን አምላክ እግዚአብሔር ይመስገን፤ በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ያከብር ዘንድ ይህን ነገር በንጉሡ ልብ ያኖረ፥'),
  ('262ad2d5-e35a-5719-af83-9f681d595070', 'cd156dd5-b01a-5a65-a561-88f0e1e4fba4', '117458a9-6097-554c-a496-2880ad2e9dc9', 18, 28, 'በንጉሡ ፊት በሚመክሩትም፥ በኀያላኑም፥ በንጉሡ አለቆች ሁሉ ፊት በእኔ ላይ ምሕረቱን ላከ። እኔም በእኔ ላይ ባለችው በአምላኬ በእግዚአብሔር እጅ በረታሁ፤ ከእኔም ጋራ ይወጡ ዘንድ ከእስራኤል አለቆቹን ሰበሰብሁ።'),
  ('57ceb9cb-5001-5d7f-a18f-d0f995027281', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 1, 1, 'በንጉሡ በአርተሰስታ መንግሥት ከእኔ ጋር ከባቢሎን የወጡ የአባቶች ቤቶች አለቆች እነዚህ ናቸው፤ ትውልዳቸውም ይህ ነው፤'),
  ('8a109061-9149-5f47-a2d0-0c97fa0dfa19', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 2, 2, 'ከፊንሐስ ልጆች ጌርሶም፥ ከኢታምር ልጆች ዳንኤል፥ ከዳዊት ልጆች ሐጡስ፥'),
  ('bd7fd53c-ba72-5246-a427-4333a72dd7ff', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 3, 3, 'ከሴኬንያ ልጆች፥ ከፋሮስ ልጆች ዘካርያስ፥ ከእርሱም ጋር የተቈጠሩ መቶ አምሳ ወንዶች ናቸው።'),
  ('943cee78-cc9d-5d8c-aad5-4ce89d9b6375', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 4, 4, 'ከፋሐት ሞዓብ ልጆች የዘርህያ ልጅ ኤሊሆዔናይ፥ ከእርሱም ጋር ሁለት መቶ ወንዶች።'),
  ('ff667703-45a3-5459-ace3-e5d8e55f8df6', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 5, 5, 'ከዘቱኤስ ልጆች የአዚኤል ልጅ ሴኬንያ፥ ከእርሱም ጋር ሦስት መቶ ወንዶች።'),
  ('6693e9e8-5d92-543d-a045-592afa3b99ae', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 6, 6, 'ከዓዴን ልጆች የዮናታን ልጅ ዔቤድ፥ ከእርሱም ጋራ አምሳ ወንዶች።'),
  ('278fe75a-6a2e-5600-aef3-6013409627b1', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 7, 7, 'ከኤሌም ልጆች የጎቶልያ ልጅ የሻያ፥ ከእርሱም ጋር ሰባ ወንዶች።'),
  ('736b7af7-914a-5d09-a641-7c245616646d', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 8, 8, 'ከሰፋጥያስ ልጆች የሚካኤል ልጅ ዘብድያ፥ ከእርሱም ጋር ሰማንያ ወንዶች።'),
  ('a30a024b-521a-5499-aef1-2a8be0c8e424', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 9, 9, 'ከኢዮአብ ልጆች የያሔኤል ልጅ አብድያ፥ ከእርሱም ጋር ሁለት መቶ ዐሥራ ስምንት ወንዶች።'),
  ('ca47d1e9-0840-5a25-adab-438623c56901', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 10, 10, 'ከበዐኛ ልጆች የዮሴፍያ ልጅ ሰሎሚት፥ ከእርሱም ጋር መቶ ስድሳ ወንዶች።'),
  ('5f40f9d2-4ed5-5a04-aa72-9acb71fbbdfe', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 11, 11, 'ከቤባይ ልጆች የቤባይ ልጅ ዘካርያስ፥ ከእርሱም ጋር ሃያ ስምንት ወንዶች።'),
  ('e1d437c2-1f65-5162-a86e-ff9b5ea850ee', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 12, 12, 'ከዓዝጋድ ልጆች የአቃጦን ልጅ፤ ዮሓናን፥ ከእርሱም ጋር መቶ ዐሥር ወንዶች።'),
  ('e8d355b8-bb72-542d-a0ed-4a714189cd62', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 13, 13, 'ከኋለኞቹ ከአዶኒቃም ልጆች ስማቸው ይህ ነው፤ ኤሊፋልጥ፥ ይኢኤል፥ ሰማአያ፥ ከእነርሱም ጋር ስድሳ ወንዶች።'),
  ('891fec36-46b1-5261-a409-3b42716d11ac', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 14, 14, 'ከባጎዊ ልጆች ውታይና ዘቡድ፥ ከእነርሱም ጋር ሰባ ወንዶች።'),
  ('1702c910-5981-5501-a6e1-3a6198e05261', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 15, 15, 'ወደ አኅዋም ወደሚፈስስ ወንዝ ሰበሰብኋቸው፤ በዚያም ሦስት ቀን ሰፈርን፤ ሕዝቡንና ካህናቱንም ስቈጥራቸው በዚያ ከሌዊ ልጆች ማንንም አላገኘሁም።'),
  ('6c53635e-f19d-51f4-ad5a-69da8fa2530e', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 16, 16, 'ወደ አለቆቹም ወደ አልዓዛር፥ ወደ አርኤል፥ ወደ ሰማአያ፥ ወደ ሀሎናም፥ ወደ ያሪብ፥ ወደ ሄልናታን፥ ወደ ናታን፥ ወደ ዘካርያስ፥ ወደ ሜሱላም፥ ደግሞም ወደ ዐዋቂዎቹ ወደ ዮያሪብና ወደ ሄልናታን ላክሁ።'),
  ('b86e73f3-75ce-5871-a7fe-044e494cddfd', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 17, 17, 'በካሲፍያ ስፍራ ወደ ነበረው ወደ አለቃው ወደ አዶ ላክኋቸው፤ ለአምላካችን ቤትም አገልጋዮችን ያመጡልን ዘንድ በካሲፍያ ስፍራ ለሚኖሩት ለአዶና ለወንድሞቹ ለናታኒም የሚነግሩአቸውን በአፋቸው አደረግሁ።'),
  ('3565a7e9-995a-5930-a5f6-ab8dcd7c3539', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 18, 18, 'በላያችንም መልካም በሆነው በአምላካችን እጅ ከእስራኤል ልጅ ከሌዊ ልጅ ከሞሐሊ ልጆች ወገን የነበረውን አስተዋይ ሰው ሰራብያን፥ ከእርሱም ጋር ዐሥራ ስምንቱን ልጆቹንና ወንድሞቹን አመጡልን።'),
  ('40dbd0b1-3de7-5b80-a0ef-3ed29c6e29b0', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 19, 19, 'ደግሞም አሴብያስን፥ ከእርሱም ጋር ከሜራሪ ልጆች ወገን የነበረውን ኢሳይያስን፥ ሃያውን ወንድሞቹንና ልጆቻቸውን።'),
  ('87481caa-fd8e-5462-a42b-c1585781379f', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 20, 20, 'ሌዋውያንንም እንዲያገለግሉ ዳዊትና አለቆቹ ከሰጡአቸው ናታኒም ውስጥ ሁለት መቶ ሃያ ናታኒምን አመጡ፤ እነዚህም ሁሉ በስም በስማቸው ተሰበሰቡ።'),
  ('844676cf-2352-5e3e-abee-ecbe551901aa', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 21, 21, 'በአምላካችን ፊት ራሳችንን እናዋርድ ዘንድ፥ ከእርሱም የቀናውን መንገድ ለእኛና ለልጆቻችን፥ ለንብረታችንም ሁሉ እንለምን ዘንድ በዚያ በአኅዋ ወንዝ አጠገብ ጾምን አወጅሁ።'),
  ('4877e818-3a6d-543c-ae3e-54059c5de8b0', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 22, 22, 'ንጉሡንም፥ “የአምላካችን እጅ በሚሹት ሁሉ ላይ ለመልካም ነው፤ ኀይሉና ቍጣው ግን እርሱን በሚተዉ ሁሉ ላይ ነው” ብለን ተናግረን ነበርና፤ በመንገድ ካለው ጠላት ያድኑን ዘንድ ጭፍራና ፈረሰኞች ከንጉሡ እለምን ዘንድ አፍሬ ነበርና።'),
  ('94dbdf26-0846-541d-a1ea-50a43e990c3f', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 23, 23, 'ስለዚህም ነገር ጾምን፤ ወደ እግዚአብሔርም ለመንን፤ እርሱምሰማን።'),
  ('5c9cad24-755b-5fe7-a335-2b2d1a11b3d1', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 24, 24, 'ከካህናቱም አለቆች ዐሥራ ሁለት ሰዎችን፥ ሰራብያንና ሐሳብያን፥ ከእነርሱም ጋር ዐሥር ወንድሞቻቸውን ለየሁ፤'),
  ('ef06d67c-3734-52f4-a242-5d56e29541e0', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 25, 25, 'ንጉሡና አማካሪዎቹ፥ አለቆቹም፥ በዚያም የተገኙት እስራኤል ሁሉ ያቀረቡትን፥ ለአምላካችን ቤት የቀረበውን ብሩንና ወርቁን፥ ዕቃውንም መዝኜ ሰጠኋቸው።'),
  ('3066871f-bc34-56ce-aff9-f8eece1a6a6c', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 26, 26, 'ስድስት መቶ አምሳ መክሊት ብር፥ አንድ መቶም መክሊት የብር ዕቃዎች፥ አንድ መቶም መክሊት ወርቅ፥'),
  ('2f9cbc6d-52e6-5629-af7c-dc61e4310644', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 27, 27, 'ሃያም ባለ ሺህ ዳሪክ የወርቅ ጽዋዎች፥ ሁለትም እንደ ወርቅ የከበሩ ከጥሩና ከሚያንጸበርቅ ናስ የተሠሩ ዕቃዎችን መዝኜ በእጃቸው ሰጠሁ።'),
  ('1ae8a212-57d9-551f-aa54-e40dee3692cc', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 28, 28, 'እኔም “እናንተ ለእግዚአብሔር ተቀድሳችኋል፤ ዕቃዎቹም ቅዱሳን ናቸው፤ ብሩና ወርቁም ለአባቶቻችን አምላክ ለእግዚአብሔር በፈቃድ የቀረበ ነው፤'),
  ('15b0b98f-c3e4-532e-ab05-019c5ecde125', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 29, 29, 'በካህናትና በሌዋውያን አለቆች፥ በእስራኤልም አባቶች ቤቶች አለቆች ፊት በኢየሩሳሌም በእግዚአብሔር ቤት ጓዳዎች ውስጥ እስክትመዝኑ ድረስ ተግታችሁ ጠብቁ” አልኋቸው።'),
  ('de07bfed-3287-5754-a8f4-5285fdddc909', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 30, 30, 'ካህናቱና ሌዋውያኑም ወደ ኢየሩሳሌም ወደ አምላካችን ቤት ይወስዱት ዘንድ ብሩንና ወርቁን፥ ዕቃዎቹንም በሚዛን ተቀበሉ።'),
  ('ed148580-0c14-51f6-af22-3c0814269284', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 31, 31, 'በመጀመሪያውም ወር በዐሥራ ሁለተኛው ቀን ወደ ኢየሩሳሌም እንሄድ ዘንድ ከአኅዋ ወንዝ ተነሣን፤ የአምላካችንም እጅ በላያችን ነበረ፤ በመንገድም ከጠላትና ከሚሸምቅ ሰው እጅ አዳነን።'),
  ('6a398b8b-a255-5c67-ab38-b58998421d53', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 32, 32, 'ወደ ኢየሩሳሌምም ደረስን፤ በዚያም ሦስት ቀን ተቀመጥን።'),
  ('d0ee5c07-13a3-58b6-a1da-d39ca1bc89fa', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 33, 33, 'በአራተኛውም ቀን ብሩና ወርቁ፥ ዕቃዎቹም በአምላካችን ቤት በካህኑ በኦርያ ልጅ በሜሪሞት እጅ ተመዘኑ፤ ከእርሱም ጋር የፊንሐስ ልጅ አልዓዛር ነበረ፤ ከእነርሱም ጋር ሌዋውያን የኢያሱ ልጅ ኢዮዛብድና የቤንዊ ልጅ ናሕድያ ነበሩ።'),
  ('bfbdbda6-bd45-58b8-ac28-5ac7c41c0dcf', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 34, 34, 'ሁሉም በቍጥርና በሚዛን ተመዘነ፤ ሚዛኑም ሁሉ በዚያ ጊዜ ተጻፈ።'),
  ('b2c59f11-ae0e-5c40-a306-86c013c66ee4', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 35, 35, 'ከምርኮም የወጡት የምርኮኞች ልጆች ለእስራኤል አምላክ ለሚቃጠል መሥዋዕት ስለ እስራኤል ሁሉ ዐሥራ ሁለት ወይፈኖች፥ ዘጠና ስድስትም አውራ በጎች፥ ሰባ ሰባትም ጠቦቶች፥ ለኀጢአት መሥዋዕት ዐሥራ ሁለት አውራ ፍየሎችን አቀረቡ። ይህ ሁሉ ለእግዚአብሔር የሚቃጠል መሥዋዕት ነበረ።'),
  ('1e0c81bb-6857-52e0-a5fb-79f5cf11a98b', '8468b0e0-61d9-55b1-a061-2ae1862e9dc8', '72ba464b-1765-58b3-a921-c4d00c9df179', 36, 36, 'የንጉሡንም ትእዛዝ በወንዙ ማዶ ላሉት ለንጉሡ ሹሞችና ገዢዎች ሰጡ፤ እነርሱም ሕዝቡንና የእግዚአብሔርን ቤት አከበሩ።'),
  ('06092b95-c83c-5153-a272-8a1404f580fb', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 1, 1, 'ይህም ከተፈጸመ በኋላ የሕዝቡ አለቆች ወደ እኔ ቀርበው፥ “የእስራኤል ሕዝብ ካህናቱም፥ ሌዋውያኑም፥ እንደ ከነዓናውያን፥ እንደ ኬጤዎናውያን፥ እንደ ፌርዜዎናውያን፦ እንደ ኢያቡሴዎናውያን፥ እንደ አሞናውያን፥ እንደ ሞዓባውያን፥ እንደ ግብፃውያንና እንደ አሞራውያን ርኵሰት ያደርጋሉ እንጂ ከምድር አሕዛብ አልተለዩም፤'),
  ('15da7503-425c-528d-a933-9354e4cfead2', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 2, 2, 'ለራሳቸውና ለልጆቻቸውም ሴቶች ልጆቻቸውን ወስደዋል፤ የተቀደሰውንም ዘር ከምድር አሕዛብ ጋር ደባልቀዋል፤ አስቀድሞም አለቆቹና ሹሞቹ በዚህ መተላለፍ መጀመሪያ ሆነዋል” አሉኝ።'),
  ('65b9ffc5-ade9-5f83-a9e2-307c65d2fa29', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 3, 3, 'ይህንም ነገር በሰማሁ ጊዜ ልብሴንና መጐናጸፊያዬን ቀደድሁ፤ አዘንሁም፤ የራሴንና የጢሜንም ጠጕር ነጨሁ፤ ደንግጬም ተቀመጥሁ።'),
  ('21b70890-01ed-5005-a0fb-45a32e729117', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 4, 4, 'ስለ ምርኮኞቹም መተላለፍ የእስራኤልን አምላክ ቃል የሚፈሩ ሁሉ ወደ እኔ ተሰበሰቡ፤ እኔም እስከ ሠርክ መሥዋዕት ድረስ ዐዝኜ ተቀመጥሁ።'),
  ('edd32406-ef70-5665-a78e-cfcc55f2c8d4', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 5, 5, 'በሠርክም መሥዋዕት ጊዜ ልብሴና መጐናጸፊያዬ እንደ ተቀደደ ሆኖ ከመዋረዴ ተነሣሁ፤ በጕልበቴም ተንበርክኬ ወደ አምላኬ ወደ እግዚአብሔር እጄን ዘረጋሁ።'),
  ('6f1848dd-05b8-59c8-a2f4-6f46e1f02bab', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 6, 6, 'እንዲህም አልሁ፥ “አምላኬ ሆይ፥ ኀጢአታችን በራሳችን ላይ በዝቶአልና፥ በደላችንም ወደ ሰማይ ከፍ ብሎአልና አምላኬ ሆይ፥ ፊቴን ወደ አንተ አነሣ ዘንድ አፍራለሁ፤ እፈራማለሁ።'),
  ('e69a0eb7-8d47-52d7-af36-9b7ae9f85171', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 7, 7, 'ከአባቶቻችን ዘመን ጀምረን እስከ ዛሬ ድረስ እጅግ በድለናል፤ ስለ ኀጢአታችን እኛና ልጆቻችን ንጉሦቻችን፥ ካህናቶቻችንም ለሰይፍና ለምርኮ፥ ለብዝበዛና ለዕፍረት በአሕዛብ ነገሥታት እጅ ተጣልን፤ እስከ ዛሬም ድረስ በፊታችን እፍረት እንኖራለን።'),
  ('3d190be3-257f-5e58-adeb-d11ed6f63330', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 8, 8, 'አሁንም ቅሬታ ይተዉልን ዘንድ፥ በተቀደሰውም ስፍራው ኀይልን ይሰጠን ዘንድ፥ አምላካችንም ዐይናችንን ያበራ ዘንድ፥ በባርነትም ሳለን ጥቂት የሕይወት መታደስን ይሰጠን ዘንድ ለጥቂት ጊዜ ከአምላካችን ከእግዚአብሔር ጥቂት ዕረፍትን አገኘን።'),
  ('fa8bd797-40d8-58b0-ab9c-0bb8badbac8e', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 9, 9, 'ባሪያዎቹ ነንና፥ አምላካችን ግን በባርነታችን አልተወንም፤ ቀለባችንን ይሰጡን ዘንድ፥ የአምላካችንንም ቤት ከፍ ከፍ ያደርጉ ዘንድ፥ የተፈታውንም ይጠግኑ ዘንድ፥ በይሁዳና በኢየሩሳሌምም ቅጥር ያደርጉልን ዘንድ በፋርስ ነገሥታት ፊት ሞገስን ሰጠን።'),
  ('317ed085-f9ee-5b1b-aefd-53e21ecd7e5f', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 10, 10, 'አሁንስ ከዚህ በኋላ ምን እንላለን? አምላካችን ሆይ፥ ትእዛዝህን ትተናልና።'),
  ('b69be38e-8a9e-5d11-a45f-23bb014bd1a1', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 11, 11, 'በባሮችህ በነቢያት እጅ ያዘዝሃትን እንዲህ ስትል፦ ትወርሱአት ዘንድ የምትገቡባት ምድር በምድር አሕዛብ ርኵሰት የረከሰች ናት፤ በርኵሰታቸውም ከዳር እስከ ዳርቻዋ ድረስ መልተዋታል።'),
  ('49e00c95-0636-5688-a2ef-ecc57ef73a66', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 12, 12, 'አሁንም ትበረቱ ዘንድ፥ የምድሩንም ፍሬ ትበሉ ዘንድ፥ ልጆቻችሁም ለዘለዓለም ይወርሱአት ዘንድ፥ ሴቶችን ልጆቻችሁን ለወንዶች ልጆቻቸው አትስጡ፤ ሴቶች ልጆቻቸውንም ለወንዶች ልጆቻችሁ አትውሰዱ፤ ሰላማቸውንና ደኅንነታቸውንም ለዘለዓለም አትሹ።'),
  ('cb8ada2f-9054-5dd6-a46f-fc739d56edca', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 13, 13, 'ስለ ክፉ ሥራችንና ስለ ታላቁ በደላችን ካገኘን ነገር ሁሉ በኋላ፥ አንተ አምላካችን እንደ ኀጢአታችን ብዛት አልቀሠፍኸንም፤ ነገር ግን ድኅነትን ሰጠኸን።'),
  ('a830fbba-3854-5e77-a192-a27f601bb9ec', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 14, 14, 'ትእዛዝህን እናፈርስ ዘንድ ተመልሰናልና፥ ርኵስ ሥራ ከሚሠሩ ከእነዚህ አሕዛብ ጋርም ተጋብተናልና ከእኛ ከሞት የሚያመልጥ እስከማይኖር ድረስ ፈጽመህ አትቈጣን።'),
  ('7f43471a-6030-5808-afdf-c0d61f48fd10', 'e8cbf603-8836-527f-a938-c033f36ab145', '1df4e505-b686-53ca-af3c-eea655cd1654', 15, 15, 'አቤቱ የእስራኤል አምላክ ሆይ፥ አንተ ጻድቅ ነህ፤ ዛሬም እንደ ሆነው እኛ አምልጠን ቀርተናል፤ እነሆ በፊትህ በበደላችን አለን፤ ስለዚህ በፊትህ ሊቆም የሚችል የለም።”'),
  ('a1a14af2-1381-51a8-a815-2b3afb3fbeb3', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 1, 1, 'ዕዝራም እያለቀሰና በእግዚአብሔር ፊት እየወደቀ በጸለየና በተናዘዘ ጊዜ ከእስራኤል ዘንድ የወንድና የሴት፥ የሕፃናትም እጅግ ታላቅ ጉባኤ ወደ እርሱ ተሰበሰበ፤ ሕዝቡም እጅግ አለቀሱ።'),
  ('1e9d0715-bef1-5d5b-acb1-8646d23e656b', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 2, 2, 'ከኤላም ልጆች ወገን የነበረውም የኢያሔል ልጅ ሴኬንያ ዕዝራን እንዲህ ብሎ ተናገረው፥ “አምላካችንን በድለናል፤ የምድርንም አሕዛብ እንግዶች ሴቶችን አግብተናል፤ አሁን ግን ስለዚህ ነገር ገና ለእስራኤል ተስፋ አለ።'),
  ('3fc851dd-c8c0-550f-a1b4-6e7c249a11c2', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 3, 3, 'አሁንም እንደ ጌታዬና የአምላካችንን ትእዛዝ እንደሚፈሩት ምክር፥ ሴቶችን ሁሉ፥ ከእነርሱም የተወለዱትን እንሰድድ ዘንድ ከአምላካችን ጋር ቃል ኪዳን እናድርግ። ተነሥ እንደ አምላካችንም ትእዛዝ ገሥፃቸው፤ እንደ ሕጉም ያድርጉ፤'),
  ('34b561a5-32ec-57ee-abc1-49905f5e6057', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 4, 4, 'ይህም ነገር ለአንተ ይገባልና፥ እኛም ከአንተ ጋር ነንና ተነሣ፤ በርታ፤ አድርገውም።”'),
  ('d0c14b33-d9b3-5d05-a034-fb0e4ccae0ae', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 5, 5, 'ዕዝራም ተነሣ፤ አለቆቹንና ካህናቱንም፥ ሌዋውያኑንም፥ እስራኤልን ሁሉ እንደዚህ ቃል ያደርጉ ዘንድ አማላቸው፤ እነርሱም ማሉ።'),
  ('6d2a47d0-63c5-5df1-a2c8-c4f8d919449b', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 6, 6, 'ዕዝራም ከእግዚአብሔር ቤት ፊት ተነሥቶ ወደ ኤሊያሴብ ልጅ ወደ ዮሐናን ጓዳ ገባ፤ ስለ ምርኮኞቹም ኀጢአት ያለቅስ ነበርና ገብቶ እንጀራ አልበላም፤ ውኃም አልጠጣም።'),
  ('5ac1c30a-ecb6-5559-a8cb-d2449c4e65a2', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 7, 7, 'የምርኮ ልጆች ሁሉም ወደ ኢየሩሳሌም ይሰበሰቡ ዘንድ ወደ ይሁዳና ወደ ኢየሩሳሌም ዐዋጅ ነገረ'),
  ('59378b26-7cb4-5f55-a693-86e2a5009fe9', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 8, 8, '“እስከ ሦስት ቀን ድረስ የማይመጣ ሁሉ እንደ ሽማግሎችና እንዳለቆች ምክር ከብቱ ሁሉ ይበዝበዝ፤ እርሱም ከምርኮው ጉባኤ ይለይ” ብሎ ዐዋጅ አስነገረ።'),
  ('313e8162-9f20-50f3-ae1a-59b5de7d836d', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 9, 9, 'ሦስት ቀንም ሳያልፍ በዘጠነኛው ወር ከወሩም በሃያኛው ቀን የይሁዳና የብንያም ሰዎች ሁሉ በኢየሩሳሌም ተሰበሰቡ። ሕዝቡም ሁሉ ስለዚህ ነገርና ስለ ታላቁ ዝናብ እየተንቀጠቀጡ በእግዚአብሔር ቤት ፊት ባለው አደባባይ ተቀመጡ።'),
  ('a863c6bd-7b79-5d23-aa6e-e9bd87ceab9f', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 10, 10, 'ካህኑም ዕዝራ ተነሥቶ፥ “ተላልፋችኋል፤ የእስራኤልን በደል ታበዙ ዘንድ እንግዶችን ሴቶች አግብታችኋል።'),
  ('f46ce8f2-f9ae-565c-a8b4-08f4c39968f8', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 11, 11, 'አሁንም የአባቶቻችንን አምላክ እግዚአብሔርን አመስግኑ፤ ደስ የሚያሰኘውንም አድርጉ፤ ከምድርም አሕዛብና ከእንግዶች ሴቶች ተለዩ” አላቸው።'),
  ('1517d423-d6eb-551c-a7db-25a6e5599137', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 12, 12, 'ጉባኤውም ሁሉ በታላቅ ድምፅ መልሰው እንዲህ አሉ፥ “እንደ ተናገርኸን እናደርግ ዘንድ ይገባናል።')
